-- quest.lua
local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[2] = {id=2,name="Sharptalon's Claw",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,mapID=63,description="The mighty hippogryph Sharptalon has been slain, with the claw of the felled beast serving as a testament to your victory. Senani Thunderheart at the Silverwind Refuge will no doubt be interested in seeing this trophy as proof of your deeds.",objectivesText="Bring Sharptalon's Claw to Senani Thunderheart at Silverwind Refuge. Progress: What have you there, <class>? Could it be....?",rewardGold=105000,rewardXP=1010,ends={{npcID=12696}},coords={mapID=63,source="quest_giver",x=0.498,y=0.652},questType="standard"},
[11] = {id=11,name="Riverpaw Gnoll Bounty",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="Gnolls, brutish creatures with no decent business in these lands, have been seen along the borders of Elwynn Forest . A large pack of them, many more than we can handle alone, have infested the woods south of the guard tower yonder. Another group has infested the areas near Stone Cairn Lake to the east. The Stormwind Army will commend whomever helps kill them. Bring me their painted gnoll armbands as proof of your deed.",objectivesText="Bring 8 Painted Gnoll Armbands to Deputy Rainer at the Barracks. Progress: Hail, <name>. Have you been killing Gnolls...?",rewardXP=200,rewardItems={2238,2249,57526,57527,131192},rewardChoices={57527,2238,57526,131192},starts={{npcID=963}},ends={{npcID=963}},coords={x=0.242,y=0.746,source="quest_giver",zoneID=12},questType="standard"},
[16] = {id=16,name="Give Gerard a Drink",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,objectivesText="Progress: Farming is thirsty work, and I'm always looking for refreshing spring water . If you have any, then I'm willing to make a trade.",rewardItems={4536},starts={{npcID=255}},ends={{npcID=255}},coords={x=0.43,y=0.856,source="quest_giver",zoneID=12},questType="standard",packageItems={159}},
[23] = {id=23,name="Ursangous' Paw",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,description="The mighty bear Ursangous is no more! The small quarter-crescent emblem on its paw indicates that this beast was trained by the night elves to prowl the forest in search of their enemies. There is no telling how many of your Horde allies fell to this creature. The paw should be brought to Tarkan at Silverwind Refuge. He will be pleased that such a weapon has been removed from the enemy's arsenal.",objectivesText="Bring Ursangous' Paw to Captain Tarkan at Silverwind Refuge. Progress: Ah - <name> - I was just thinking about you! How goes your hunting?",rewardGold=53500,rewardXP=1010,ends={{npcID=12696},{npcID=34559}},coords={mapID=63,x=0.404,y=0.664},questType="standard"},
[24] = {id=24,name="Shadumbra's Head",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,mapID=63,description="The once swift Shadumbra now lies still as you claim victory over it. This legenday creature is dear to the night elves. Its head should serve as an intimidating trophy, and as a sign of the end of the Alliance in Ashenvale . Captain Goggath at Hellscream's Watch will no doubt be delighted to receive the head of the slain nightsaber.",objectivesText="Bring Shadumbra's Head to Captain Goggath at Hellscream's Watch. Progress: Yes, <class>?",rewardGold=53500,rewardXP=1010,ends={{npcID=12696},{npcID=34359}},coords={mapID=63,source="quest_giver",x=0.498,y=0.652},questType="standard"},
[25] = {id=25,name="Simmer Down Now",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,mapID=63,description="You should've seen it, ! The elves thought Silverwind to be impenetrable. With its heavy defenses and their army of water elementals, they were almost right. Almost. One of our mages was able to summon a twisted elemental designed to send the others into a chaotic rage. Ahh, the looks on their faces! Unfortunately, the mage who summoned it fell in battle. Now I need someone to bring down our creation.",objectivesText="Captain Tarkan at Silverwind Refuge wants you to defeat Tideress and 12 Befouled Water Elementals at Mystral Lake.",rewardGold=105000,rewardXP=1010,starts={{npcID=34559}},ends={{npcID=12737},{npcID=34559}},coords={x=0.5,y=0.674,source="quest_giver",zoneID=331},questType="standard"},
[35] = {id=35,name="Further Concerns",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="If you are concerned that the rumors of murlocs are true, then do this -- travel to the eastern Elwynn bridge and speak with Guard Thomas . He has been stationed at the bridge for the past week and will know the state of the area. I have here a Stormwind charger that will take you to Guard Thomas . Let me know if you wish to make use of the horse.",objectivesText="Marshal Dughan wants you to speak with Guard Thomas .",rewardXP=25,starts={{npcID=240}},ends={{npcID=261}},coords={x=0.422,y=0.658,source="quest_giver",zoneID=12},questType="standard"},
[37] = {id=37,name="Find the Lost Guards",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="A few days ago we sent two Guards, Rolf and Malakai, to investigate along the river, and they have not yet returned. To complete my report, I must know what happened to those men. Travel north along the river and find the guards... or their remains.",objectivesText="Guard Thomas wants you to travel north up the river and search for the two lost guards, Rolf and Malakai.",rewardXP=50,starts={{npcID=261}},ends={{npcID=55}},coords={x=0.738,y=0.722,source="quest_giver",zoneID=12},questType="standard"},
[40] = {id=40,name="A Fishy Peril",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description=", there's a new threat in Elwynn Forest ! Murlocs are swimming up the streams of eastern Elwynn, scaring away fish and attacking gentle folk! I warned Marshal Dughan , but he's more worried about the gnolls and the bandits. He's not convinced that the murlocs are a danger. Please, , speak to Dughan and persuade him to send more troops to the east!",objectivesText="Remy \"Two Times\" wants you to speak with Marshal Dughan in Goldshire.",rewardXP=25,starts={{npcID=241}},ends={{npcID=240}},coords={x=0.42,y=0.672,source="quest_giver",zoneID=12},questType="standard"},
[45] = {id=45,name="Discover Rolf's Fate",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="Upon further searching the area, you find webbed footprints leading east along the shore of Stone Cairn Lake. In the distance to the east, you can just barely see a Murloc village. Perhaps Rolf's fate ended there...",objectivesText="Search the murloc village for Rolf, or signs of his death.",rewardXP=100,starts={{npcID=55}},ends={{npcID=56}},coords={x=0.727,y=0.604,source="quest_giver",zoneID=12},questType="standard"},
[46] = {id=46,name="Bounty on Murlocs",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="The Stormwind Army has placed a bounty on murloc lurkers and foragers in Elwynn. Slaughter them and bring Guard Thomas their torn murloc fins , and the Stormwind Army will reward you well. The murlocs have built a village at Stone Cairn Lake north of here, and another to the south where the stream forks.",objectivesText="Bring 8 Torn Murloc Fins to Guard Thomas at the east Elwynn bridge. Progress: How goes the hunting, <name>?",rewardXP=200,rewardItems={1008,1158,4840,57248,57521,156980,156981},rewardChoices={4840,1158,57248,57521,156980,156981},starts={{npcID=203733}},ends={{npcID=261}},coords={x=0.74,y=0.723,source="quest_giver",zoneID=12},questType="standard"},
[47] = {id=47,name="Gold Dust Exchange",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="The kobolds in these parts sometimes carry Gold Dust on them. I could really use the stuff - bring me a load of it and I'll give you the best price in town...best price in town! You can find kobolds in the Fargodeep Mine to the south, and around the Jasperlode Mine to the northeast.",objectivesText="Bring 10 Gold Dust to Remy \"Two Times\" in Goldshire. Gold Dust is gathered from Kobolds in Elwynn Forest . Progress: Psst! You have that Gold Dust for me...for me?",rewardGold=105000,rewardXP=200,rewardItems={1191,57400,57401},rewardChoices={57400,57401},starts={{npcID=241}},ends={{npcID=241}},coords={x=0.42,y=0.672,source="quest_giver",zoneID=12},questType="standard"},
[52] = {id=52,name="Protect the Frontier",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1519,mapID=37,description="Hail, . Wild animals are growing more and more aggressive the farther we get from Goldshire, and the Eastvale Logging Camp suffers nearly constant attacks from wolves and bears! We could use your help out here.",objectivesText="Kill 8 Prowlers or Gray Forest Wolves and 5 Young Forest Bears , and then return to Guard Thomas at the east Elwynn bridge. Progress: Have you killed those wolves and bears?",rewardGold=78750,rewardXP=150,rewardItems={57523,57524,57525,131193},rewardChoices={57523,57524,57525,131193},starts={{npcID=261}},ends={{npcID=261}},coords={x=0.738,y=0.722,source="quest_giver",zoneID=12},questType="standard"},
[54] = {id=54,name="Report to Goldshire",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=6170,mapID=37,description=", you are a with proven interest in the security of Northshire . You are now tasked with the protection of the surrounding Elwynn Forest. If you accept this duty, then I have prepared papers that must be delivered to Marshal Dughan in Goldshire. Goldshire lies along the southern road, past the border gates.",objectivesText="Take Marshal McBride's Documents to Marshal Dughan at Goldshire in Elwynn Forest. Progress: You have word from McBride? Northshire is a garden compared to Elwynn Forest, but I wonder what Marshal McBride has to report. Here, let me have his papers...",rewardXP=100,rewardItems={6078,57389,57390,57391,131876,248798},rewardChoices={6078,57391,57390,131876,57389},starts={{npcID=197}},ends={{npcID=240}},coords={x=0.48,y=0.42,source="quest_giver",zoneID=12},questType="standard"},
[59] = {id=59,name="Cloth and Leather Armor",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="For your shrewdness and valor, I have a marker here that is good for one piece of armor. I want you to take it to Sara Timberlain at the Eastvale Logging Camp. Give her the marker, and she will fashion the armor for you. And after you receive it, , use it in the defense of Elwynn. Eastvale is just east of this post across the bridge.",objectivesText="Give Sara Timberlain the Stormwind Armor Marker . Progress: I have been commissioned by the Stormwind Army to supply their people with cloth and leather armor. If you have a marker for me, then I'd be happy to make you something.",rewardXP=50,rewardItems={1171,2237,57520,131194},rewardChoices={1171,2237,57520,131194},starts={{npcID=261}},ends={{npcID=278}},coords={x=0.738,y=0.722,source="quest_giver",zoneID=12},questType="standard"},
[60] = {id=60,name="Kobold Candles",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="Hello, ! Do you have a moment? My brother and I run an apothecary in Stormwind, and I'm here to gather large candles for their wax. Can you help me? You can get large candles from kobolds, and I hear rumors that kobolds are infesting the Elwynn mines... the Fargodeep Mine to the south and Jasperlode Mine to the east. I suggest looking for candles in one of those places.",objectivesText="Bring 8 Large Candles to William Pestle in Goldshire. Progress: Did you gather those candles yet?",rewardGold=800,rewardXP=200,rewardItems={1434,57398,57399,248938},rewardChoices={57398,57399},starts={{npcID=253}},ends={{npcID=253}},coords={x=0.432,y=0.658,source="quest_giver",zoneID=12},questType="standard"},
[62] = {id=62,name="The Fargodeep Mine",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="The mine in Northshire isn't the only one with problems! I have reports that the Fargodeep Mine in Elwynn has also become a haven for Kobolds. Explore the mine and confirm these reports, then return to me. The mine is almost due south of Goldshire, between the Stonefield and Maclure homesteads.",objectivesText="Explore the Fargodeep Mine, then return to Marshal Dughan in Goldshire.",rewardGold=800,rewardXP=200,starts={{npcID=240}},ends={{npcID=240}},coords={x=0.422,y=0.658,source="quest_giver",zoneID=12},questType="standard"},
[71] = {id=71,name="Report to Thomas",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="Now that you have both medallions, deliver them to Guard Thomas at the bridge so that he might know the fate of his murdered guards.",objectivesText="Deliver Rolf and Malakai's Medallions to Guard Thomas at the eastern Elwynn bridge. Progress: Hello, <name>. Have you discovered the fates of Rolf and Malakai?",rewardXP=50,starts={{npcID=56}},ends={{npcID=261}},coords={x=0.798,y=0.556,source="quest_giver",zoneID=12},questType="standard"},
[76] = {id=76,name="The Jasperlode Mine",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="Thanks to you we know the Fargodeep Mine is infested with kobolds. Now we need a scout to investigate the more distant Jasperlode Mine. Explore Jasperlode and confirm any kobold presence. To reach the mine, travel east along the road until you reach the Tower of Azora. From the tower, head north and you'll find the mine in the foothills.",objectivesText="Explore the Jasperlode Mine, then report back to Marshal Dughan in Goldshire. Progress: Hail, <name>. What do you have to report? Have you scouted the Jasperlode Mine?",rewardGold=1015,rewardXP=200,starts={{npcID=240}},ends={{npcID=240}},questType="standard"},
[83] = {id=83,name="Fine Linen Goods",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="The thugs in Elwynn wear linen which I can use to make fine linen goods. Bring me linen scraps and I'll use them to fashion something for you. You'll find those lawless criminals in pockets across Elwynn Forest .",objectivesText="Bring 6 Linen Scraps to Sara Timberlain at the Eastvale Logging Camp. Progress: I'm running low on linen, <name>. Do you have any for me?",rewardXP=200,rewardItems={983,2575,57405,57406,131195},rewardChoices={983,57405,57406,131195},starts={{npcID=278}},ends={{npcID=278}},coords={x=0.794,y=0.686,source="quest_giver",zoneID=12},questType="standard"},
[84] = {id=84,name="Back to Billy",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="Here you go. And when you give this pie to that Billy, you tell him I hope he chokes on it!",objectivesText="Bring the Pork Belly Pie to Billy Maclure at the Maclure Vineyards. Progress: Ugh... I'm starving! Do you have that pie for me, <name>?",rewardXP=50,starts={{npcID=246}},ends={{npcID=247}},coords={x=0.344,y=0.842,source="quest_giver",zoneID=12},questType="standard"},
[85] = {id=85,name="Lost Necklace",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="I lost my necklace and I think that guttersnipe Billy Maclure took it! He's usually scuttling like a rat around the Maclure Vineyards east of here. Get my necklace back for me and you'll warm an old widow's heart.",objectivesText="Speak with Billy Maclure .",rewardXP=50,starts={{npcID=246}},ends={{npcID=247}},coords={x=0.344,y=0.842,source="quest_giver",zoneID=12},questType="standard"},
[86] = {id=86,name="Pie for Billy",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="Maybe if I got a pie, I could tell you who has that necklace. And you know, I think that old Bernice lady at that other farm makes great Pork Belly Pies... Maybe if you gave her some tender boar meat from the boars that hang around our farms, and told her what it was for, she'd bake up a pie for you.",objectivesText="Bring 4 Tender Boar Meat to Auntie Bernice Stonefield at the Stonefield's Farm. Progress: I don't think it's right feeding the boy who stole my necklace in the first place, but if that's what it takes to get back what's mine, then so be it! Do you have that boar meat?",rewardXP=200,starts={{npcID=247}},ends={{npcID=246}},coords={x=0.43,y=0.858,source="quest_giver",zoneID=12},questType="standard"},
[87] = {id=87,name="Goldtooth",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="I was playing near the Fargodeep Mine, and I think I dropped, er...I mean I saw, the old lady's necklace. Don't ask me how it got there...it wasn't me! Well anyway, I saw this big, gold-toothed kobold pick up the necklace and run back to his den above the mine. Go find that kobold and you'll find the necklace, I swear!",objectivesText="Bring Bernice's Necklace to \"Auntie\" Bernice Stonefield at the Stonefield Farm. Progress: Hello, <name>. Have you found my necklace?",rewardXP=200,rewardItems={1359,57402,131196},rewardChoices={1359,57402,131196},starts={{npcID=247}},ends={{npcID=246}},coords={x=0.43,y=0.858,source="quest_giver",zoneID=12},questType="standard"},
[88] = {id=88,name="Princess Must Die!",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="The Brackwells have a prize-winning pig, Princess. The sow is HUGE, and she got that way from sneaking over here and eating my veggies! It just so happens that she's here now! Princess must die! Bring me her collar as proof of the deed and I'll give you something for your time! You'll find Princess smack dab in the middle of our watermelon patch. Get her!",objectivesText="Kill Princess, grab her collar, then bring it back to Ma Stonefield at the Stonefield Farm. Progress: Did you see her yet? Did you get her?",rewardXP=200,rewardItems={1173,1182,11191,131197},rewardChoices={1173,1182,11191,131197},starts={{npcID=244}},ends={{npcID=244}},coords={x=0.346,y=0.844,source="quest_giver",zoneID=12},questType="standard"},
[106] = {id=106,name="Young Lovers",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="Oh, I'm cursed! My heart belongs to Tommy Joe Stonefield , but our families are bitter enemies. So I can't see him, even though my eyes ache to gaze upon that handsome face! Please, take this letter and give it to Tommy Joe. He's usually at the river to the west of the Stonefield Farm, which is due west of here.",objectivesText="Give Maybell's Love Letter to Tommy Joe Stonefield . Progress: You have what?? Maybell is the light of my dull life. Hurry, let me see her letter!",rewardXP=50,starts={{npcID=251}},ends={{npcID=252}},coords={x=0.43,y=0.896,source="quest_giver",zoneID=12},questType="standard"},
[107] = {id=107,name="Note to William",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="I bet William Pestle has a potion to unite our two young lovers! Here, take this note to William. He's staying at the Lion's Pride Inn in Goldshire.",objectivesText="Take Gramma Stonefield's Note to William Pestle . Progress: You have a note from \"Gramma\" Stonefield, eh? I haven't seen Mildred in years! I wonder what she has to say...",rewardXP=50,starts={{npcID=248}},ends={{npcID=253}},coords={x=0.348,y=0.838,source="quest_giver",zoneID=12},questType="standard"},
[111] = {id=111,name="Speak with Gramma",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="Please, , talk with my Gramma. If anyone can find a way to bring me together with Maybell, she can. She's inside our house east of here.",objectivesText="Speak with Gramma Stonefield .",rewardXP=50,starts={{npcID=252}},ends={{npcID=248}},coords={x=0.298,y=0.86,source="quest_giver",zoneID=12},questType="standard"},
[112] = {id=112,name="Collecting Kelp",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="I can make an invisibility liquor for Maybell, so she can slip away from the Maclure Vineyards and go to Tommy Joe. But to make the liquor, I need some crystal kelp. Although the kelp usually grows in the ocean... sometimes murlocs collect it. See if the murlocs near Crystal Lake have any. Crystal Lake is just east of Goldshire.",objectivesText="Bring 4 Crystal Kelp Fronds to William Pestle in Goldshire. Progress: Do you have that crystal kelp? I'm sure Maybell is anxious to see her beau...",rewardXP=200,starts={{npcID=253}},ends={{npcID=253}},coords={x=0.432,y=0.658,source="quest_giver",zoneID=12},questType="standard"},
[114] = {id=114,name="The Escape",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="Take this invisibility liquor to young Maybell. It should last long enough for her to visit Tommy Joe.",objectivesText="Take the Invisibility Liquor to Maybell Maclure . Progress: Did you deliver my letter to Tommy Joe? What did he say??",rewardXP=200,rewardItems={118,253527},starts={{npcID=253}},ends={{npcID=251}},coords={x=0.432,y=0.658,source="quest_giver",zoneID=12},questType="standard"},
[123] = {id=123,name="The Collector",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="This note is a schedule with a list of days and times when a person -- described only as \"The Collector\" -- will receive a shipment of gold from the mines in Elwynn Forest . From the schedule, it looks as if the Collector resides near the Brackwell Pumpkin Patch in eastern Elwynn. This sounds important. You should report it to Marshal Patterson at Eastvale Logging Camp.",objectivesText="Go to Marshal Patterson at the Eastvale Logging Camp in Elwynn Forest and give him The Collector's Schedule . Progress: What?!? We haven't had our people working the Elwynn mines for months! Let me see that note you have...",rewardGold=105000,rewardXP=200,ends={{npcID=42256}},coords={mapID=37,source="quest_giver",x=0.818,y=0.66},questType="standard"},
[147] = {id=147,name="Manhunt",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="If the \"Collector\" is taking gold from our mines then he's stealing from the kingdom! Bring the Collector to justice, and bring me the ring mentioned in the pickup schedule you gave me. It may tell us whom the Collector is working for... That Pickup Schedule says the Collector is hiding out at the Brackwell Pumpkin Patch. You should search for him there.",objectivesText="Find and kill \"the Collector\" then return to Marshal Patterson with The Collector's Ring . Progress: Did you find the Collector? Did you discover whom he's working for?",rewardXP=200,rewardItems={1183,1360,57251,57522,131198},rewardChoices={1360,1183,57522,131198},starts={{npcID=42256}},ends={{npcID=42256}},coords={x=0.818,y=0.66,source="quest_giver",zoneID=12},questType="standard"},
[171] = {id=171,name="A Warden of the Alliance",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1519,mapID=84,description="You have been so very kind to me, . I never dreamed that I'd have so much fun during Children's Week. Thank you. I wish all the orphans were lucky enough to get to do the stuff we did. Do you think we could find Craggle Wobbletop again and get a foam sword rack from him? I think he's still pushing that cart in the Canals outside the Trade District. That way, everyone else at the orphanage could do something fun too! After that, it'll be time for me to go home.",objectivesText="Purchase a Foam Sword Rack from Craggle Wobbletop and then return your ward to the Stormwind orphanage by speaking to Orphan Matron Nightingale in the Cathedral District. Progress: It is a pleasure to see you again, <name>. Have you attended to the duties you've volunteered for during Children's Week?",rewardXP=355,rewardItems={23002,23007,23015,23022,66073,116202,241215},rewardChoices={23007,23015,23002,66073,116202,23022,241215},starts={{npcID=14305}},ends={{npcID=14450},{npcID=51988}},questType="standard"},
[172] = {id=172,name="Children's Week",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,mapID=85,description="You're willing to help us here at the orphanage? Bless you, friend; your aid during Children's Week will be invaluable. Take this whistle. You will only be able to use it for a short amount of time - typically not longer than Children's Week itself. When you use it, you will be able to talk with the child you've agreed to look after. Using it again will dismiss the child. By all means - use the whistle and meet your ward! I'm sure the child will be most eager to meet you.",objectivesText="Use the Orcish Orphan Whistle to talk with the child you will be looking after during Children's Week. Provided item:",rewardItems={18597},starts={{npcID=51989}},ends={{npcID=51989}},coords={x=0.58,y=0.576,source="quest_giver",zoneID=1637},questType="standard"},
[176] = {id=176,name="WANTED: \"Hogger\"",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="Wanted: Hogger A huge gnoll, Hogger , is prowling the woods in southwestern Elwynn. He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll. To earn the reward, bounty hunters should venture into the woods and deal with the beast.",objectivesText="Deal with \"The Hogger Situation\" and return to Marshal Dughan .",rewardXP=250,rewardItems={6084,6085,6215,60219,131199},rewardChoices={6085,6084,60219,131199},starts={{npcID=68},{npcID=156561},{npcID=307068},{npcID=307265},{npcID=307325}},ends={{npcID=240}},coords={x=0.245,y=0.747,source="quest_giver",zoneID=12},questType="group"},
[182] = {id=182,name="The Troll Menace",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=6176,mapID=27,description="The trolls're acting up. More than usual, I'd say. We've seen them put together war parties before, but this time it's... different. What matters most, however, is the continued protection of Anvilmar. I've no intention to let these trolls flank Anvilmar while its attention is turned towards troggs. Go thin their ranks a bit. They need to know that we're still not without defenses.",objectivesText="Kill 10 Frostmane Troll Whelps .",rewardGold=2000,rewardXP=200,rewardItems={961,2047,2048,2195,5761,12446},rewardChoices={2047,5761,2195,12446},starts={{npcID=786}},ends={{npcID=786}},coords={x=0.32,y=0.742,source="quest_giver",zoneID=1},questType="standard"},
[184] = {id=184,name="Furlbrow's Deed",level=5,requiredLevel=5,faction="alliance",expansion=0,zoneID=1581,mapID=52,description="This is an old deed to an expanse of farmlands within Westfall . It is signed by a Theodore Furlbrow and cosigned by his wife, Verna. And on the back of the deed are hastily scrawled words: \"We leaned on Furlbrow and got his deed. Thought it might be handy if you wanted to forge one of these for your own place. The Furlbrows won't give us trouble. Last I saw them they were on their way out of Westfall , stuck with a broken wagon.\" You think the Furlbrows might want their deed back...",objectivesText="Bring Furlbrow's Deed to the Jansen Stead in Westfall . Progress: We don't need any civilian vigilante types getting involved, kid. Leave this one to the professionals.",rewardXP=555,starts={{npcID=203734}},ends={{npcID=42308},{npcID=42309}},coords={x=0.248,y=0.952,source="quest_giver",zoneID=12},questType="standard"},
[185] = {id=185,name="Tiger Hunting",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=33,mapID=50,description="When I was but a young girl, my father trained me in the art of tiger hunting. You'll find the young felines much easier to track and slay. One can often find young tigers near the expedition camp. Test your tracking skills and see if you can hunt some of the beasts down. Start your hunt near our camp, to the south.",objectivesText="Hunt 10 Young Stranglethorn Tigers .",rewardXP=1415,starts={{npcID=717}},ends={{npcID=717}},coords={x=0.444,y=0.226,source="quest_giver",zoneID=33},questType="standard"},
[186] = {id=186,name="Tiger Stalking",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=33,mapID=50,description="Young tigers are one thing. Fully-grown cats are another. Hunting the grown Stranglethorn tigers will prove an even greater challenge. The adult cats normally spend their days south of Kurzen's Compound, east of the river.",objectivesText="Hunt 10 Stranglethorn Tigers .",rewardXP=1415,starts={{npcID=717}},ends={{npcID=717}},coords={x=0.444,y=0.226,source="quest_giver",zoneID=33},questType="standard"},
[187] = {id=187,name="Tiger Prowess",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=33,mapID=50,description="Elder Stranglethorn tigers are the strongest of the bunch. More than one has seen own demise at the tip of those razor-sharp teeth and heavy claws. Ajeck will be thrilled to know that you have bested them. The largest pack of these elders can be found to the south, near the Sundering, on the border of the Cape of Stranglethorn.",objectivesText="Hunt 5 Elder Stranglethorn Tigers .",rewardXP=1415,starts={{npcID=717}},ends={{npcID=717}},coords={x=0.444,y=0.226,source="quest_giver",zoneID=33},questType="standard"},
[188] = {id=188,name="Tiger Mastery",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=33,mapID=50,description="Legends speak of an elusive tigress... a feline so powerful that she dwarfs even the elder males. The hunters at Nesingwary's Expedition have hunted for her without success. Many of them have fallen prey to her raking claws, their bodies now decaying at the foot of her hill, north of Grom'gol. They call the beast Sin'Dall. You resolve to do what no has done before: hunt, kill, and claim the paw of Sin'Dall .",objectivesText="Hunt Sin'Dall and return with her paw. Progress: How goes the hunt?",rewardGold=160500,rewardXP=1770,rewardItems={4107,61113,61114,61115,61116,131200},rewardChoices={61116,61115,61114,61113,131200},starts={{npcID=717}},ends={{npcID=717}},coords={x=0.444,y=0.226,source="quest_giver",zoneID=33},questType="standard"},
[190] = {id=190,name="Panther Hunting",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=33,mapID=50,description="If you want to be a part of the hunt with this crack group under Hemet Jr.'s leadership, you're going to need to prove yourself an able panther hunter. You should start out easy: just focus on the young panthers for now. As you improve and gain experience as a hunter, you will undoubtedly find increasingly dangerous quarry. Start by heading east. Return to me when you are a master panther hunter.",objectivesText="Hunt 10 Young Panthers .",rewardXP=1415,starts={{npcID=718}},ends={{npcID=718}},coords={x=0.438,y=0.224,source="quest_giver",zoneID=33},questType="standard"},
[191] = {id=191,name="Panther Stalking",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=33,mapID=50,description="The youngest panthers fell easily before you. panthers that have come of age will naturally be stronger, and quicker, and more difficult to defeat. Larger panther tracks lead to the west.",objectivesText="Hunt 10 Panthers .",rewardXP=1415,starts={{npcID=718}},ends={{npcID=718}},coords={x=0.438,y=0.224,source="quest_giver",zoneID=33},questType="standard"},
[192] = {id=192,name="Panther Prowess",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=33,mapID=50,description="Now the hard part. As panthers grow older, they become more wily, blending in with their environment and becoming difficult to spot. These cunning panthers are known by the name \"shadowmaw\", for their tendency to suddenly appear out of the darkness... with a waiting mouth full of teeth. If you want to prove yourself as a true panther hunter, shadowmaws are the only way to do so. They prowl to the southeast, across the river.",objectivesText="Hunt 5 Shadowmaw Panthers .",rewardXP=1415,starts={{npcID=718}},ends={{npcID=718}},coords={x=0.438,y=0.224,source="quest_giver",zoneID=33},questType="standard"},
[193] = {id=193,name="Panther Mastery",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=33,mapID=50,description="You've almost proven yourself to be a master hunter of panthers. Yet there is one panther which has eluded your grasp. Songs are sung about a mighty panther by the name of Bhag'thera. You will see if you can use your skills to kill the great beast. Bringing the Fang of Bhag'thera to Erlgadin should be proof enough that you are a master panther hunter.",objectivesText="Obtain the Fang of Bhag'thera . Progress: You're still alive! Excellent! How fares the hunt?",rewardGold=21450,rewardXP=1770,rewardItems={4108,61107,61108,61109},rewardChoices={61109,61108,61107},starts={{npcID=718}},ends={{npcID=718}},coords={x=0.438,y=0.224,source="quest_giver",zoneID=33},questType="standard"},
[194] = {id=194,name="Raptor Hunting",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=33,mapID=50,description="So you think your hunting skills are in tip-top shape? I can put them to the test in a jiffy. Head out into that jungle and kill ten Stranglethorn raptors . We'll see just how much of a big game hunter you are. And no, I won't tell you where you can find them! Locating the beasts is half the challenge. Okay, go west.",objectivesText="Hunt 10 Stranglethorn Raptors .",rewardXP=1415,starts={{npcID=715}},ends={{npcID=715}},coords={x=0.44,y=0.232,source="quest_giver",zoneID=33},questType="standard"},
[195] = {id=195,name="Raptor Stalking",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=33,mapID=50,description="It is time to step up the challenge. Venturing into the jungle and bagging 10 lashtail raptors should be sufficient. They will certainly be stronger than the raptors you have already disposed of. The lashtail raptors mainly stay southeast of here, near the Kal'ai Ruins.",objectivesText="Hunt 10 Lashtail Raptors .",rewardXP=1415,starts={{npcID=715}},ends={{npcID=715}},coords={x=0.44,y=0.232,source="quest_giver",zoneID=33},questType="standard"},
[196] = {id=196,name="Raptor Prowess",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=33,mapID=50,description="A particularly cagey brand of raptor, known by locals as the \" Jungle Stalker \", prowls the forests to the south, across the river. They are far more difficult to track down and kill than the other breeds you've been trying your luck at. Killing these Jungle Stalkers will undoubtedly make for a good tale around the fire.",objectivesText="Hunt 10 Jungle Stalkers .",rewardXP=1415,starts={{npcID=715}},ends={{npcID=715}},coords={x=0.44,y=0.232,source="quest_giver",zoneID=33},questType="standard"},
[197] = {id=197,name="Raptor Mastery",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=33,mapID=50,description="Before returning to Nesingwary's Expedition, you will have to complete the impossible: hunt the raptor that no other hunter has been able to capture. That beast goes by the name of Tethis, and he's been known to terrorize the southeastern corner of Northern Stranglethorn . Bringing Tethis' talon back to that dwarf hunter should be proof that you are no ordinary .",objectivesText="Hunt Tethis. Progress: Ah, so you're hunting Tethis? Tracked her all the way back to camp, did you?",rewardGold=145050,rewardXP=1770,rewardItems={4119,61110,61111,61112,131201},rewardChoices={61112,61111,61110,131201},starts={{npcID=715}},ends={{npcID=715}},coords={x=0.44,y=0.232,source="quest_giver",zoneID=33},questType="standard"},
[208] = {id=208,name="Big Game Hunter",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=33,mapID=50,description=", you are a hunter worthy of our company. From the battlefields of Lordaeron to the deepest jungle, I have rarely witnessed such prowess with weaponry as you have demonstrated. You have killed the ferocious Sin'Dall, the elusive Bhag'thera, and the treacherous Tethis. But the true prize is the head of King Bangalash. That white tiger is the reason I am here... yet still, he taunts me from his roost to the south. Kill King Bangalash and your hunting prowess is proven to be second to none.",objectivesText="Hunt for the head of King Bangalash, the great white tiger. Progress: I see you're back, old bloke. King Bangalash has caused me to come crawling back to camp many times. Hang in there.",rewardGold=160500,rewardXP=2125,rewardItems={4110,4111,17686,17687,61124,61125,61126,61127,131202},rewardChoices={61127,61126,61125,61124,131202,17687},starts={{npcID=715}},ends={{npcID=715}},coords={x=0.44,y=0.232,source="quest_giver",zoneID=33},questType="standard"},
[216] = {id=216,name="Between a Rock and a Thistlefur",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,mapID=63,description="The Thistlefur furbolgs are threatening our expansion! Thistlefur Village to our west blocks the way between us here and the Splintertree Post. It's a path that would circumvent the village of Astranaar; without it, we give the Alliance an extra expansion path. , we must not allow... an expansion path gap! Proceed to Thistlefur Village and thin out the furbolgs. You will be given compensation for this task, but more importantly you will be doing your duty for the Horde!",objectivesText="Karang Amakkar at Hellscream's Watch wants you to take down any 15 Thistlefur furbolg in Thistlefur Village.",rewardGold=105000,rewardXP=1010,starts={{npcID=12757}},ends={{npcID=12757}},coords={x=0.378,y=0.434,source="quest_giver",zoneID=331},questType="standard"},
[218] = {id=218,name="Ice and Fire",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=6176,mapID=27,description="Soren did well to send you out on recon. That's some good information you have right there. Trouble is, this just adds more work for us to do. The trolls, confused as they are right now, still would like to kick the dwarves right out of Coldridge. And I'm certainly not going to let some fiery demon turn our snowy valley into a mountain lake. The troll leader, his servants, and the fire creature should all be in the cave to the southeast. Take 'em all out.",objectivesText="Kill Grik'nir the Cold , 6 Frostmane Blades , 3 Frostmane Novices , and the Wayward Fire Elemental . Progress: <name>! Any luck?",rewardGold=4000,rewardXP=250,rewardItems={5581,6176,57534,57535,57536,131891},rewardChoices={57534,57535,57536,131891},starts={{npcID=786}},ends={{npcID=786}},coords={x=0.32,y=0.742,source="quest_giver",zoneID=1},questType="standard"},
[239] = {id=239,name="Westbrook Garrison Needs Help!",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="The Garrison on our western border sends word of increasing gnoll and thief activity. They're requesting we send more Stormwind soldiers... but we just don't have any to spare! If you can help, we could use it. Go and speak with Deputy Rainer at the Westbrook Garrison and see what he needs done. The Garrison is down the road to the west. After you cross the bridge over the small brook it will be to the right.",objectivesText="Go to the Westbrook Garrison and speak with Deputy Rainer .",rewardXP=50,starts={{npcID=240}},ends={{npcID=963}},coords={x=0.422,y=0.658,source="quest_giver",zoneID=12},questType="standard"},
[264] = {id=264,name="Until Death Do Us Part",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=130,mapID=88,description="Filthy scum! Leaves me for his damn crusade. Because \"the Light is the most important thing we have against the threats the undead pose.\" Well, what about his children?! What about ME?! Night after night I sat patiently waiting for him... always second to his blasted duty! Well, witness what \"justice\" brings you, ! He's dead and I'm bearing the very thing he was trying to stop! Take this piece of junk and put it on his tomb at the Sepulcher. I want nothing to do with it anymore... or him!",objectivesText="Place Clarice's Pendant on Yuriv's Tomb in Silverpine. Progress: The stone is cold to the touch, but has obviously been abused. Trash litters the area; nicks and gashes decorate the relief atop the coffin; and the foliage around the grave has started to grow over the site. No one cares for whoever is buried here, especially not any victims of the plague.",rewardXP=370,starts={{npcID=5543}},ends={{npcID=24776}},coords={x=0.284,y=0.256,source="quest_giver",zoneID=1638},questType="standard"},
[309] = {id=309,name="Protecting the Shipment",level=5,requiredLevel=5,faction="alliance",expansion=0,zoneID=38,mapID=48,description="We need to get this powder to Ironband, but this cart isn't going anywhere now. It'll be a lot for us to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for us now that Saean is with them. I'll feel a lot better if you helped me watch over things. Miran can offload the powder kegs at camp while you and I protect the cart.",objectivesText="Protect Huldar and the Ironband Caravan, and then inform Prospector Ironband . Progress: I'm glad to finally have my powder! We're on top of some amazing discoveries.",rewardGold=105000,rewardXP=925,rewardItems={3217,6188,58981,58982,58983,131204},rewardChoices={58983,58982,58981,131204},starts={{npcID=2057}},ends={{npcID=1344}},coords={x=0.562,y=0.658,source="quest_giver",zoneID=38},questType="standard"},
[313] = {id=313,name="Forced to Watch from Afar",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1,mapID=27,description="The cataclysm drove the troggs to the surface in hordes, forcing the Frostmane trolls to flee for their lives. Unfortunately, they've decided to settle right on our doorstep and make trouble for us. I deployed Mountaineer Dunstan and his squad to the Grizzled Den just southwest of town to keep an eye on the wendigos that live there, but now I need to recall them to Kharanos. Find them and tell them to deploy those remote observation bots the gnomes provided, then return to Kharanos.",objectivesText="Relay Captain Tharran 's orders to Mountaineer Dunstan , Mountaineer Lewin , and Mountaineer Valgrum in the Grizzled Den.",rewardGold=1015,rewardXP=200,starts={{npcID=1377},{npcID=40950}},ends={{npcID=1377},{npcID=40950}},questType="standard"},
[314] = {id=314,name="Protecting the Herd",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1,mapID=27,description="We heard the cries in the middle of the night. Then this morning, sure enough, the herd was missing two rams. That dastardly beast known as Vagash has been preying on our livelihood. With Ironforge's troops already spread thin, there is no one to keep Vagash at bay. Perhaps you are brave enough to seek out the beast and slay him. Bring me one of his fangs and I will reward you. Vagash lurks just above the ranch here, but be warned, he is deadly.",objectivesText="Obtain Vagash's Fang. Progress: Vagash still terrorizes the herd! Please help us by killing the wretched beast.",rewardXP=200,rewardItems={2817,3103,10549,57552,131205},rewardChoices={10549,2817,57552,131205},starts={{npcID=1265}},ends={{npcID=1265}},coords={x=0.702,y=0.482,source="quest_giver",zoneID=1},questType="standard"},
[315] = {id=315,name="The Perfect Stout",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1,mapID=27,description="I'm on a quest to make the perfect stout. I know I can do it -- brewing's in my blood. I just need to find the right recipe... The Frostmane trolls grow a plant, shimmerweed , up on Shimmer Ridge to the northwest. They use it in their strange, tribal rituals. We haven't found much use for it, but it has a unique taste... and I want to experiment with it in my brews! Obtaining the shimmerweed will be dangerous, but I'll pay well for any you can \"borrow\" from the baskets in the troll village.",objectivesText="Bring 7 Shimmerweeds to Rejold Barleybrew in Kharanos. Progress: Do you have that shimmerweed ? I almost have a batch of stout ready to brew, and I want to try throwing the weed in with this mixture.",rewardXP=200,rewardItems={2326,2905,57547,57548,131206},rewardChoices={2326,57547,57548,131206},starts={{npcID=1374}},ends={{npcID=1374}},coords={x=0.542,y=0.512,source="quest_giver",zoneID=1},questType="standard"},
[332] = {id=332,name="Wine Shop Advert",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1519,mapID=84,description="If you talk to anyone about wine, then you know we Gallinas sell the best wine in Stormwind. And we're not far, still in the Trade District along the city's lovely canals. Here, take this pamphlet. Bring it to my sister Suzetta at our shop for a complimentary bottle of the famous Dalaran Noir. You won't regret it!",objectivesText="Go to the Gallina Winery, and bring Suzetta Gallina the Wine Ticket for a free bottle of wine. Progress: Greetings and welcome, master. Have you yet tried one of our fine wines?",rewardXP=150,rewardItems={2723},starts={{npcID=1432}},ends={{npcID=1431}},coords={x=0.638,y=0.734,source="quest_giver",zoneID=1519},questType="standard"},
[333] = {id=333,name="Harlan Needs a Resupply",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1519,mapID=84,description="We've been doing a lot of business lately. It seems like everyone is buying armor and sturdy clothes. Almost like they expect a cold, harsh season ahead... But those are future worries. My worry today is that I'm running out of knitted clothing to sell. I need another load from our supplier. If you can take this request to Rema Schneider at the Canal Tailor and Fit Shop, I'd be most grateful.",objectivesText="Go to the Canal Tailor Shop and bring Rema Schneider the Cloth Request from Harlan Bagley . Progress: You bring word from Mr. Bagley?",rewardGold=52500,rewardXP=100,starts={{npcID=1427}},ends={{npcID=1428}},coords={x=0.622,y=0.678,source="quest_giver",zoneID=1519},questType="standard"},
[334] = {id=334,name="Package for Thurman",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1519,mapID=84,description="My son Thurman is an apprentice at the Larson Clothiers, in the Mage's Quarter. He was in a hurry today and forgot his shears and needles. I know a great like you must have important tasks at hand, but without his tools Thurman can't do his apprentice work! Please, . Can you take my son's sewing kit to him? Larson Clothiers is one of two clothing shops in the Mage's Quarter - it's the one deeper in, near the Mage's Tower.",objectivesText="Go to the Larson Clothiers in the Stormwind Mage Quarter, and give Thurman Schneider his Sewing Kit. Progress: Are you here to buy clothes?",rewardXP=150,starts={{npcID=1428}},ends={{npcID=1429}},coords={x=0.58,y=0.672,source="quest_giver",zoneID=1519},questType="standard"},
[351] = {id=351,name="Find OOX-17/TN!",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1176,mapID=71,description="You have uncovered some sort of strange, egg-shaped device made from metal. Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption! A voice from inside the robotic egg crackles to life. \"The name's Oglethorpe, and my homing robot has gone missing! I will reward you for its recovery! Please take this beacon to the robot. Excellent, I now have computed the coordinates for you! It crashed near the Gaping Chasm in Tanaris !\"",objectivesText="Bring the distress beacon to Oglethorpe's homing robot. Progress: You appear to have uncovered the wreckage of... a robotic chicken? The voice from within the egg crackles to life again: \"Yes, excellent work! This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs. Go ahead and place the beacon inside the rover. The beacon will take care of the rest!\"",rewardXP=2090,ends={{npcID=7784}},coords={mapID=71,source="quest_giver",x=0.59825,y=0.60675},questType="standard"},
[353] = {id=353,name="Stormpike's Delivery",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=38,mapID=84,description="The Stormpikes are a respected dwarven clan, and are well known for their fine and discerning tastes. So it's no wonder that Gringer Stormpike, a Mountaineer of Ironforge, commissioned me to craft him a weapon. The weapon is finished, but... Mountaineer Stormpike is far away, in distant Loch Modan. If you plan on traveling to the north, can you deliver this package to him? My last message from Mountaineer Stormpike said he's stationed at the northern guard tower in Loch Modan.",objectivesText="Deliver the Package for Stormpike to Mountaineer Stormpike in Loch Modan. Progress: You come all the way from Stormwind? I hear it's getting dicey down there in the human lands, with brigands and orcs running about. A perfect place for a <class> to prove his worth!",rewardGold=105000,rewardXP=200,starts={{npcID=1416}},ends={{npcID=1343}},coords={x=0.596,y=0.34,source="quest_giver",zoneID=1519},questType="standard"},
[384] = {id=384,name="Beer Basted Boar Ribs",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1,mapID=27,description="Nothing my tavern patrons enjoy more than some Beer Basted Boar Ribs ! Only problem is, the local trapper who used to bring me supplies enlisted in the King's Army to help with the war on the Alliance front. Maybe you can help me out? If you bring me some boar ribs and a Rhapsody Malt from the tavern here, I'll give you the family recipe for my famous Beer Basted Boar Ribs , not to mention a free sample! The secret's in the Malt!",objectivesText="Ragnar Thunderbrew in Kharanos wants 4 Tender Boar Ribs and a mug of Rhapsody Malt . Progress: I'm going to need those crag boar ribs and a mug of Rhapsody Malt , <name>.",rewardGold=105000,rewardXP=200,rewardItems={2888,2889},starts={{npcID=1267}},ends={{npcID=1267}},coords={x=0.538,y=0.506,source="quest_giver",zoneID=1},questType="standard"},
[412] = {id=412,name="Operation Recombobulation",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1,mapID=27,description="I should go back to Gnomeregan and continue researching a cure for irradiated gnomes. But, I stayed behind in Kharanos because the town is my home and I wanted to help defend it from the Frostmane attacks. I've been working on maintaining and repairing the steam tanks. For some reason, Frostmane scavengers have taken a liking to the gyromechanic gears I need to complete the repairs. They're all over the Frostmane Front to the southeast of town. Will you help me get those gears back?",objectivesText="Bring Razzle Sprysprocket 8 Gyromechanic Gears . Progress: Those pilots can't wait to get back into their steam tanks and take to the field again. Let's not let them down.",rewardXP=200,rewardItems={3152,3153,57545,57546,131207},rewardChoices={57546,57545,131207},starts={{npcID=1269}},ends={{npcID=1269}},coords={x=0.532,y=0.518,source="quest_giver",zoneID=1},questType="standard"},
[432] = {id=432,name="Those Blasted Troggs!",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1,mapID=27,description="Those Light-blasted troggs, turning my work site into a wreck! Look at that, there goes another barrel of powder! Ohhh, I wish I could go down there and wring every one of their scrawny little necks! I want to kill them all! This can't be good for my health, all this stress and anger... What have they left me with? Nothing! I'd kill them myself, but my aim's no good anymore! You go into the quarry and kill some of the filthy buggers! I'll pay you! Just hurt them, kill them!",objectivesText="Kill 8 Rockjaw Skullthumpers and 8 Rockjaw Bonesnappers in the Gol'Bolar Quarry and its mine. Progress: It makes me so mad! Grrr...",rewardGold=105000,rewardXP=200,starts={{npcID=1254}},ends={{npcID=1254}},coords={x=0.762,y=0.546,source="quest_giver",zoneID=1},questType="standard"},
[433] = {id=433,name="The Public Servant",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1,mapID=27,description="As a member of the Senate and the Explorers' League, I've taken it upon myself to investigate conditions at the quarry. The troggs have run wild! They've made a mess of the Gol'Bolar quarry. As we dug deep into the earth, they poured out, destroying our equipment and trapping many of the miners below ground. We have to get them out of there. I've had mages working overtime to enchant these runes of return . If you can get them to the trapped miners , they can return to the surface in safety.",objectivesText="Distribute Runes of Return to 7 Trapped Miners in the Gol'Bolar Quarry Mine.",rewardGold=105000,rewardXP=200,rewardItems={57568,57569,57570,131208,131209},rewardChoices={57570,57568,57569,131208,131209},starts={{npcID=1977}},ends={{npcID=1977}},coords={x=0.758,y=0.542,source="quest_giver",zoneID=1},questType="standard"},
[475] = {id=475,name="A Troubling Breeze",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="A troubling breeze blows through the forest. Gaerolas Talvethren serves as Great Warden to the hibernating Druids of the Talon in the Ban'ethil Barrow Den. His duty as the chosen protector of the Sleeping is to ensure their safety so that their pact with Ysera remains fulfilled. But word from Gaerolas is now delayed and I grow nervous. Travel east to Starbreeze Village and bring back a report from Gaerolas so that I can put my worries to rest, knowing my dreaming brethren slumber safely.",objectivesText="Seek out Gaerolas Talvethren in Starbreeze Village.",rewardXP=100,starts={{npcID=2078}},ends={{npcID=2107}},coords={x=0.556,y=0.518,source="quest_giver",zoneID=141},questType="standard"},
[476] = {id=476,name="Gnarlpine Corruption",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="The Gnarlpine tribe's corruption has returned! They ambushed me as I left for the Ban'ethil Barrow Den and proceeded to pillage Starbreeze Village. Something in the forest has corrupted Ursal the Mauler, their chieftain, and he is using the evil powers of the fel moss to drive them mad. I am too wounded to return to Athridas to bring him this grave news. The task is left to you, young . We can only hope that the deranged Gnarlpines have not made it to Ban'ethil yet!",objectivesText="Return to Athridas Bearmantle in Dolanaar.",rewardGold=105000,rewardXP=200,starts={{npcID=2107}},ends={{npcID=2078}},coords={x=0.646,y=0.512,source="quest_giver",zoneID=141},questType="standard"},
[483] = {id=483,name="The Relics of Wakening",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den, tucked in the hill to the west. The slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help. The delicate hibernation ritual cannot be broken without the Relics of Wakening. Journey to the Den and retrieve the Raven Claw Talisman , Black Feather Quill , Sapphire of Sky , and Rune of Nesting . The druids store them in sacred chests. Return them to me and I will prepare the awakening ritual.",objectivesText="Retrieve the Relics of Wakening. Progress: <name>, the kidnapped Druids of the Talon will be forever trapped in the Emerald Dream if we cannot retrieve the Relics of Wakening from the Ban'ethil Barrow Den to the west. For every minute we delay their fate comes one step closer to eternal doom.",rewardGold=105000,rewardXP=200,rewardItems={9599,9603,54868,60240,131210},rewardChoices={54868,9599,131210},starts={{npcID=2078}},ends={{npcID=2078}},coords={x=0.556,y=0.518,source="quest_giver",zoneID=141},questType="standard"},
[485] = {id=485,name="Find OOX-09/HL!",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=47,mapID=26,description="You have uncovered some sort of strange, egg-shaped device made from metal. Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption! A voice from inside the robotic egg crackles to life. \"My name's Oglethorpe Obnoticus, and my homing robot has crashed! I will reward you for its recovery; please take this beacon to the robot!\" \"I now have computed the coordinates of the robot for you; it crashed at the head of the river near Skulk Rock!\"",objectivesText="Take the distress beacon to Oglethorpe's homing robot at the head of the river in the Hinterlands , near Skulk Rock. Progress: You appear to have uncovered the wreckage of... a robotic chicken? The voice from within the egg crackles to life again: \"Yes, excellent work! This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs. Go ahead and place the beacon inside the rover - the beacon will take care of the rest!\"",rewardXP=1415,ends={{npcID=7806}},coords={mapID=26,source="quest_giver",x=0.524857,y=0.441714},questType="standard"},
[486] = {id=486,name="Ursal the Mauler",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="Now the time has come to save the Druids of the Talon. If we fail now, , they will be forever lost in sleep. I shall prepare the Relics of Wakening and perform the ritual. For my work to take effect, the cursed beast responsible for this horrible situation must be slain. It was Ursal the Mauler who meddled with our brethren's calling and it is Ursal the Mauler who must now pay so they can be freed. Travel northwest on the road and find the path north into The Cleft. Ursal's den will be there.",objectivesText="Kill Ursal the Mauler .",rewardGold=210000,rewardXP=250,rewardItems={5459,5587,54869,54870,131211},rewardChoices={54869,54870,131211},starts={{npcID=2078}},ends={{npcID=2078}},coords={x=0.556,y=0.518,source="quest_giver",zoneID=141},questType="standard"},
[487] = {id=487,name="The Road to Darnassus",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="The road to Darnassus must be kept safe. Corrupted furbolgs from the Gnarlpine tribe have been attacking travelers relentlessly. Important news and commerce travels to and from Darnassus by way of this road daily. We cannot afford to have a rogue band of heathens terrorizing people. Take up arms in the name of the sacred forest, . Their den lies up this northern path. Slay these Gnarlpine ambushers and report back to me.",objectivesText="Slay 8 Gnarlpine Ambushers . Progress: The road is still not safe, <class>. Travel forth and slay the Gnarlpine ambushers and return to me.",rewardGold=105000,rewardXP=200,starts={{npcID=2151}},ends={{npcID=2151}},coords={x=0.494,y=0.446,source="quest_giver",zoneID=141},questType="standard"},
[488] = {id=488,name="Zenn's Bidding",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="Eager for work, I see. Lucky for you a day never goes by that I don't wish I had a fledgling to perform my bidding. You see, , I can make you very happy and provide you with things you never dreamed of having. But in order for that to happen you must bring me certain items. My business in the forest often requires certain... reagents. Fetch for me nightsaber fangs , strigid owl feathers and swatches of webwood spider silk . Let's keep this our little secret, .",objectivesText="Retrieve 2 Nightsaber Fangs , 2 Strigid Owl Feathers and 2 swatches of Webwood Spider Silk . Progress: Have you been a busy little bee, <name>? I've been waiting for you to bring me what I need.",rewardGold=105000,rewardXP=200,rewardItems={5457,60239},starts={{npcID=2150}},ends={{npcID=2150}},coords={x=0.596,y=0.492,source="quest_giver",zoneID=141},questType="standard"},
[489] = {id=489,name="Seek Redemption!",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="The Council of the Forest has news that you aided Zenn Foulhoof . The satyr is an enemy of the forest. As a , you should know better than to defile the forest by killing Nature's creatures. You must redeem yourself in the eyes of the Council if you wish to remain a friend of Teldrassil . Teach Foulhoof a lesson and you shall be redeemed. Fel Cones are corrupted seeds that fall from the trees. They billow with green smoke. Give some to Foulhoof. He'll think you have brought him a harmless snack.",objectivesText="Collect 3 Fel Cones . Progress: What do you have for me, <name>? A lovely snack I presume?",rewardGold=17450,rewardXP=200,starts={{npcID=2083}},ends={{npcID=2150}},coords={x=0.558,y=0.504,source="quest_giver",zoneID=141},questType="standard"},
[543] = {id=543,name="The Perenolde Tiara",level=7,requiredLevel=7,faction="alliance",expansion=0,zoneID=267,mapID=84,description="The Perenolde Tiara is an old heirloom of the Perenolde \"nobles\" - the ruling family of Alterac before that kingdom fell to ruin. It is said to have been crafted by master jewelers in Ironforge, and fitted with the finest of emeralds. When Alterac was destroyed the Tiara was lost, but there are rumors that an Ogre Mage, Grel'borg the Miser, found the tiara and now wanders the Ruins of Alterac searching for more treasures. We would have you acquire the tiara for us.",objectivesText="Recover the Perenolde Tiara . Progress: Salutations, <name>. Do try to avoid stepping on my pant cuffs. This outfit is newly tailored.",rewardGold=315000,rewardXP=1515,rewardItems={248662},starts={{npcID=2285}},ends={{npcID=2285}},coords={x=0.814,y=0.342,source="quest_giver",zoneID=1519},questType="group"},
[583] = {id=583,name="Welcome to the Jungle",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=33,mapID=50,description="Welcome to Stranglethorn! Perhaps you're not aware of this, but that dwarf over there is the son of the one and only Hemet Nesingwary, renowned war hero of the Alliance and master big game hunter. Like his father, he's not one for welcoming strangers into his camp, but you look like you've seen quite a bit of action in your day, . Go and speak with him. He's a chip off the old block, so perhaps he can give you some hunting pointers.",objectivesText="Speak with Hemet Nesingwary Jr.",rewardGold=5350,rewardXP=175,starts={{npcID=716}},ends={{npcID=715}},coords={x=0.442,y=0.222,source="quest_giver",zoneID=33},questType="standard"},
[648] = {id=648,name="Rescue OOX-17/TN!",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=5287,mapID=71,description="The gnome's voice crackles once again from the robot: \"I need to move OOX-17/TN to an open, safe place so it can begin a lengthy take-off procedure. It has built-in cloaking, but I need time on my end to make it operational again. I need you to escort the robot from its current location to, let's say, near the Caverns of Time! That should be a perfect place, and long enough, to get things on line!\" \"Escort it safely and then come talk to me in Booty Bay! Oglethorpe Obnoticus - out!\"",objectivesText="Escort OOX-17/TN to safety, then report to Oglethorpe Obnoticus in Booty Bay.",rewardXP=4180,rewardItems={9643,9644},rewardChoices={9643,9644},starts={{npcID=7784}},ends={{npcID=7406}},coords={x=0.598,y=0.64,source="quest_giver",zoneID=440},questType="standard"},
[743] = {id=743,name="Dangers of the Windfury",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=215,mapID=7,description="Thank you for taking the time to speak to me, . I am Ruul, warrior and teacher. You have obviously reached an age when you must prepare for your trials if you are to adventure much further out of Mulgore . If you wish a test of your strength, start by seeking out the Windfury harpies to the southeast. They nestle along the mountain's edges away from the road. They are one of our natural enemies here in Mulgore and will be a good gauge of your skill.",objectivesText="Bring 8 Windfury Talons to Ruul Eagletalon in Bloodhoof Village. Progress: The Windfuries are deadly foes. Their strength in battle is only rivaled by their desire for fresh meat.",rewardGold=105000,rewardXP=200,starts={{npcID=2985}},ends={{npcID=2985}},coords={x=0.474,y=0.612,source="quest_giver",zoneID=215},questType="standard"},
[744] = {id=744,name="Preparation for Ceremony",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=215,mapID=7,description=", my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him. I want to ask a favor of you while I finish tanning these leather straps. There is not time for me to find enough feathers, and I was wondering, would you gather more for me? You can find feathers of the correct size from the harpies residing far to the north and northwest of Thunder Bluff. I need only 6 azure and 6 bronze feathers to complete the design.",objectivesText="Collect 6 Azure Feathers and 6 Bronze Feathers . Progress: This headdress will certainly be a wonderful gift for my brother.",rewardGold=105000,rewardXP=200,rewardItems={4967,4968,57211,57227,57236,131212},rewardChoices={57211,57227,57236,131212},starts={{npcID=2987}},ends={{npcID=2987}},coords={x=0.496,y=0.174,source="quest_giver",zoneID=215},questType="standard"},
[749] = {id=749,name="The Ravaged Caravan",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=215,mapID=7,description="A few days ago, we found a Venture Co. caravan traveling under guard on the northern shore of Stonebull Lake. We'd lost two of our number in an earlier battle, so we were quick to attack and lay waste to the caravan. We left their supply crates, thinking that our torches would destroy anything of value, but given that Venture Co. salvagers have been spotted near the burned wagons, maybe we were wrong. Perhaps you could go to the caravan and examine the contents of the crates.",objectivesText="Morin Cloudstalker wants you to examine the contents of a supply crate at the Ravaged Caravan.",rewardXP=150,starts={{npcID=2988}},ends={{npcID=2908}},coords={x=0.57,y=0.604,source="quest_giver",zoneID=215},questType="standard"},
[751] = {id=751,name="The Ravaged Caravan",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=215,mapID=7,description="Prying open the lid reveals a tightly packed assortment of ore and minerals, more evidence of the Venture Co.'s mining operation in Mulgore . On the top of the ore and minerals you remove a tightly bound sheaf of papers. Up in the foothills to the east, you can barely hear the sounds of work, and see smoke rising from a large fire.",objectivesText="Return the Venture Co. Documents to Morin Cloudstalker near Bloodhoof Village. Progress: Hail, <name>. Have you learned anything new about the Venture Co.'s plans and operations in our homeland? If they plan to exploit our lands as they have others, the Outrunners will be quick to put an end to it.",rewardXP=150,rewardItems={4834},starts={{npcID=2908}},ends={{npcID=2988}},coords={x=0.536,y=0.484,source="quest_giver",zoneID=215},questType="standard"},
[761] = {id=761,name="Swoop Hunting",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1638,mapID=7,description="The swoop is a cunning bird, and difficult to find and hunt. A collection of Swoop Quills is a badge of cleverness and determination for a hunter. If you are willing to take up this task, then enter the plains and hunt the swoop. Bring me their quills, and bring honor to your clan. The swoops may be found anywhere in Mulgore , but your eyes must be sharp to spot them, and your hooves must be quick to catch them.",objectivesText="Bring 8 Trophy Swoop Quills to Harken Windtotem in Bloodhoof Village. Progress: Have you found the swoops, <name>. Do you have their quills?",rewardGold=210000,rewardXP=250,starts={{npcID=2947}},ends={{npcID=2947}},coords={x=0.486,y=0.588,source="quest_giver",zoneID=215},questType="standard"},
[768] = {id=768,name="Gathering Leather",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1638,mapID=88,description="Greetings, young one. You have a gleam in your eye; I can tell you are eager to venture back to the plains for the hunt. May you bring honor to your clan! I work with the skins of beasts, fashioning them into clothes and armor for the people of Thunder Bluff . If you hunt beasts and bring me their skins, then I will fashion something for you.",objectivesText="Bring 12 pieces of Light Leather to Veren Tallstrider in Thunder Bluff . Progress: Hello again. Have you been hunting? Do you have skins for me?",rewardXP=250,rewardItems={4962,5936,131214,131215},rewardChoices={5936,4962,131214,131215},starts={{npcID=3050}},ends={{npcID=3050}},coords={x=0.44,y=0.446,source="quest_giver",zoneID=1638},questType="standard"},
[769] = {id=769,name="Kodo Hide Bag",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1638,mapID=88,description="The kodo beasts of Mulgore are strong and sturdy -- traits much respected among us. If you are skilled in leatherworking and wish the knowledge to make a Kodo Hide Bag, then bring me supplies for my trade. Do this, and I will share my knowledge with you.",objectivesText="Bring 4 Light Leather and 4 Coarse Thread to Veren Tallstrider in Thunder Bluff . Progress: Do you have my supplies, <name>?",rewardXP=100,rewardItems={5083},starts={{npcID=3050}},ends={{npcID=3050}},coords={x=0.44,y=0.446,source="quest_giver",zoneID=1638},questType="standard"},
[770] = {id=770,name="The Demon Scarred Cloak",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=215,mapID=7,description="The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion. Perhaps someone in Camp Sungraze should know of Ghost Howl's demise....",objectivesText="Find someone who knows of Ghost Howl. Provided item:",rewardXP=200,rewardItems={3079,4971},rewardChoices={4971,3079},ends={{npcID=3052}},coords={mapID=7,source="quest_giver",x=0.496,y=0.172},questType="standard"},
[773] = {id=773,name="Rite of Wisdom",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=215,mapID=7,description="To gain acceptance amongst the elders of Thunder Bluff you must next complete the Rite of Wisdom. Now that you have passed the Rite of Vision, the ancestral spirits of Red Rocks will give you the blessing of our ancestors. Only those who have drunk from the Water of Seers can gain the blessing. Travel east of Thunder Bluff, to Red Rocks and seek out the Ancestral Spirit , .",objectivesText="Travel to Red Rocks east of Thunder Bluff and speak with the Ancestral Spirit .",rewardXP=200,starts={{npcID=3233}},ends={{npcID=2994}},coords={x=0.494,y=0.172,source="quest_giver",zoneID=215},questType="standard"},
[824] = {id=824,name="Je'neu of the Earthen Ring",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=719,mapID=63,description="The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements. They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know. Lucky for you, I know someone in the Earthen Ring here in Ashenvale . Head over to Zoram'gar Outpost on the coast of the Zoram Strand; show Je'neu Sancrea what you found. If anyone can figure out that globe's significance, it'd be him.",objectivesText="Bring the Befouled Water Globe to Je'neu Sancrea in Blackfathom Deeps. Provided item:",rewardXP=2020,rewardItems={16659,16660,16661,131216},rewardChoices={16659,16660,16661,131216},starts={{npcID=12737}},ends={{npcID=12737}},coords={x=0.74,y=0.606,source="quest_giver",zoneID=331},questType="standard"},
[833] = {id=833,name="A Sacred Burial",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=215,mapID=7,description="Only the most valiant tauren are laid to rest at Red Rocks, our sacred burial ground. It is an honor bestowed upon the great warriors who helped found and defend Thunder Bluff and those who have given their lives for the greater good of their tribes and chieftains. But it appears a foul menace has made its way onto our holy land. A band of Bristleback Interlopers is ravaging the grave site and I am too old and past my prime to drive them away. They must be driven off with force, .",objectivesText="Kill 8 Bristleback Interlopers at Red Rocks. Progress: The Bristleback Interlopers must be driven away from our sacred burial ground, <name>.",rewardGold=9225,rewardXP=150,rewardItems={57212,57228,57237,131217},rewardChoices={57237,57228,57212,131217},starts={{npcID=3233}},ends={{npcID=3233}},coords={x=0.494,y=0.172,source="quest_giver",zoneID=215},questType="standard"},
[834] = {id=834,name="Winds in the Desert",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=14,mapID=1,description="I'm Rezlak , one of Gazlowe's boys. Boss sent me to help the orcs here in Durotar . Things'd been going good except for the caravans. Can't manage to keep them safe! Makes my job a little harder, you know? The last shipment, which they PROMISED would get through, was snatched by the Dustwind harpies of...where was it...Razorwind Canyon? I gotta have those supplies! Follow the big canyon to the south, you'll find the ravine cut right into the west and east sides of the walls.",objectivesText="Retrieve 5 Sacks of Supplies. Progress: I'm great at what I do, don't get me wrong, but this is ridiculous! What am I supposed to do, build sand castles?",rewardGold=105000,rewardXP=200,starts={{npcID=3293}},ends={{npcID=3293}},coords={x=0.464,y=0.228,source="quest_giver",zoneID=14},questType="standard"},
[835] = {id=835,name="Securing the Lines",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=14,mapID=1,description="Gazlowe told me once, \" Rezlak . There's one thing you need to know in life, and that's if you want something done well, do it yourself.\" I can't deal with losing all our caravans, so I'm just going to take matters into my own hands. Harpies plague our supply routes. If we kill the harpies, the caravans are safe. Of course, there was one other thing that Gazlowe taught me, and that's \"You can get anything done for a price.\" You in, ? Good... I recommend starting in the canyon to the east.",objectivesText="Kill 12 Durotar Harpies. Any type of harpy will suffice.",rewardXP=200,rewardItems={4931,4932,4938,133693},rewardChoices={4932,4931,4938,133693},starts={{npcID=3293}},ends={{npcID=3293}},coords={x=0.464,y=0.228,source="quest_giver",zoneID=14},questType="standard"},
[836] = {id=836,name="Rescue OOX-09/HL!",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5287,mapID=26,description="The gnome's voice crackles once again from the robot: \"I need to move OOX-09/HL to an open, safe place so it can begin a lengthy take-off procedure. It has built-in cloaking, but I need time on my end to make it operational again. Escort the robot from its current location to, let's say, some big rocks that obscure visibility! That should be a perfect place, and long enough, to get things online!\" \"Escort it safely and then come talk to me in Booty Bay! Oglethorpe Obnoticus - out!\"",objectivesText="Escort OOX-09/HL to safety, then report to Oglethorpe Obnoticus in Booty Bay.",rewardXP=2830,rewardItems={9645,9646},rewardChoices={9645,9646},starts={{npcID=7806}},ends={{npcID=7406}},coords={x=0.494,y=0.378,source="quest_giver",zoneID=47},questType="standard"},
[840] = {id=840,name="Conscript of the Horde",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=1,description="Hmm, you look pretty strong. Listen, my good friend Kargal needs some new recruits for Barrens duty. I know you want to do what's right for the Horde. Well, this is your chance. Take this recruitment letter to Kargal and see if he'll sign it.",objectivesText="Give Kargal Battlescar at the Barrens outpost your recruitment letter . Progress: What do you want, pup? If you're not here for recruitment, I don't have time for you.",rewardXP=370,starts={{npcID=3336}},ends={{npcID=3337}},coords={x=0.508,y=0.436,source="quest_giver",zoneID=14},questType="standard"},
[844] = {id=844,name="Plainstrider Menace",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="Are you familiar with plainstriders? Useless animals. Can't fly. Gamey. Brain the size of my knuckle. Too dim to get out of the way of a moving cart. I've broken more axles thanks to their thick skulls... Sometimes I think the quilboar intentionally frighten flocks of them into the path of our caravans just prior to an ambush. Make me proud, . Cut a swath through those filthy birds to keep the roads free, and bring me their beaks as proof.",objectivesText="Collect 7 Plainstrider Beaks . Progress: Have you collected the plainstrider beaks ?",rewardGold=105000,rewardXP=740,starts={{npcID=3338},{npcID=34258}},ends={{npcID=3338},{npcID=34258}},coords={x=0.5,y=0.598,source="quest_giver",zoneID=17},questType="standard"},
[845] = {id=845,name="The Zhevra",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=4709,mapID=10,description="If you wish to serve my beloved horde, you'll have to prove your strength to me, pup. You can cut your teeth by hunting zhevra. They may not be the strongest of beasts in the Barrens, but stay clear of their kick or you'll regret it. Hunt the zhevra to the north and south, and collect their hooves. Bring them to me and perhaps we'll next send you against something tougher.",objectivesText="Slay Zhevra Runners to collect 4 Zhevra Hooves . Progress: How many zhevra have you slain?",rewardGold=105000,rewardXP=740,starts={{npcID=3338}},ends={{npcID=3338}},coords={x=0.5,y=0.598,source="quest_giver",zoneID=17},questType="standard"},
[848] = {id=848,name="Fungal Spores",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="The oases of the Barrens hide a mystery. Life energy flows from their waters, invigorating the plants and beasts that drink it. Invigorating, and altering. There is a mushroom that grows near the Forgotten Pools to the northwest. Its spores hold properties that we, the apothecaries of Lordaeron, find useful. Bring me these spores and you will earn our gratitude.",objectivesText="Collect 5 Fungal Spores from mushrooms at the Forgotten Pools. Progress: Do you have the spores, <name>? My associates and I are eager to study this phenomenon...",rewardGold=210000,rewardXP=740,starts={{npcID=3390}},ends={{npcID=3390}},coords={x=0.486,y=0.584,source="quest_giver",zoneID=17},questType="standard"},
[851] = {id=851,name="Verog the Dervish",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=14,mapID=10,description="Verog may be hard to find, but judging by the info you gathered, his mate Wyneth is always in his command tent just west of here. If we kill her, Verog will come running. Regthar sent us here to scout, but he also said we should seize any opportunity to upset the centaur chain of command if we can. Lure out Verog and kill him!",objectivesText="Kill Wyneth in order to lure out Verog the Dervish, then slay him and grab his head. Progress: Did you find Verog, <name>?",rewardGold=565,rewardXP=555,rewardItems={59566,59567,131219},rewardChoices={59566,59567,131219},starts={{npcID=3389},{npcID=34638}},ends={{npcID=3389},{npcID=34638}},coords={x=0.378,y=0.552,source="quest_giver",zoneID=17},questType="standard"},
[852] = {id=852,name="Hezrul Bloodmark",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us. So kill him. Bring me Hezrul's Head , and I will mount it from this outpost, so that they may know fear. Hezrul leads his people from the Lushwater Oasis, to the south.",objectivesText="Slay Hezrul Bloodmark and collect his head. Progress: Is Hezrul defeated, <name>?",rewardGold=105000,rewardXP=740,rewardItems={5351,59585,59586,59587,131220},rewardChoices={59585,59586,59587,131220},starts={{npcID=3389}},ends={{npcID=3389}},coords={x=0.378,y=0.552,source="quest_giver",zoneID=17},questType="standard"},
[855] = {id=855,name="Centaur Bracers",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="The centaur leadership relies on a core of trusted, disciplined warriors to keep the others in line. If we reduce their numbers, the Kolkar will have no might with which to support their rage. And so, I have a bounty task for you. Around the Lushwater Oasis to the south, slay Kolkar Marauders and Stormseers to collect their bracers. Return when you have a heap of these trophies and the Horde will reward you well.",objectivesText="Collect 10 Centaur Bracers from Kolkar Marauders and Stormseers. Progress: How goes your hunting, <name>?",rewardXP=740,rewardItems={5344,5345,5346,59583,59584,131221},rewardChoices={59583,59584,131221},starts={{npcID=3389}},ends={{npcID=3389}},coords={x=0.378,y=0.552,source="quest_giver",zoneID=17},questType="standard"},
[858] = {id=858,name="Ignition",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="I don't suppose Sputtervalve sent you? I'm in a bind here. I hopped in without realizing that I need a key to unlock the shredder's movement column. One of the other shredder operators asked me if everything was okay, and I panicked! Instead of telling him that I was missing my key, I told him there was some sort of mechanical problem. We need to get out of here on the double! Search the upper level of the derrick, Supervisor Lugwizzle should have a key for this shredder. Help me out here!",objectivesText="Get the Ignition Key from Supervisor Lugwizzle. Progress: Quick, we need to get out of here before someone gets suspicious!",rewardXP=740,starts={{npcID=3439}},ends={{npcID=3439}},coords={x=0.576,y=0.182,source="quest_giver",zoneID=17},questType="standard"},
[863] = {id=863,name="The Escape",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?",objectivesText="Protect Wizzlecrank and the stolen goblin shredder on the way out of the Sludge Fens.",rewardGold=158500,rewardXP=925,rewardItems={5326,5327,59577,59578,59579,131222},rewardChoices={59577,59578,59579,131222},starts={{npcID=3439}},ends={{npcID=3442}},coords={x=0.576,y=0.182,source="quest_giver",zoneID=17},questType="standard"},
[865] = {id=865,name="It's Gotta be the Horn",level=5,requiredLevel=5,faction="both",expansion=0,zoneID=17,mapID=10,description="The raptors of the Barrens are smarter than raptors in other lands. I think all those smarts are hiding in their horns! If so, then I could grind their horns into powder and use it to make \"smart drinks.\" I'll make a fortune! Here's where you come in: I want the horn from the smartest raptor around. \"King Reaperclaw\" leads a whole pack of intelligent raptors up on the bluffs north of Ratchet. Bring me his horn! And don't get ripped to ribbons like everyone else I've sent!",objectivesText="Acquire King Reaperclaw's Horn . Progress: Did you get King Reaperclaw's horn , <name>? I need to test my first smart drink!",rewardXP=740,rewardItems={5342,5343,59580,59581,59582,131223},rewardChoices={59580,59581,59582,131223},starts={{npcID=3446}},ends={{npcID=3446}},coords={x=0.678,y=0.716,source="quest_giver",zoneID=17},questType="standard"},
[866] = {id=866,name="Root Samples",level=5,requiredLevel=5,faction="both",expansion=0,zoneID=17,mapID=10,description="The herbs of the Barrens are not quite like herbs in other lands. Their properties are mostly the same, but the oasis water here alters the plants; they are just slightly different. I want to study those differences... to see if they're exploitable! If you are skilled in herbalism, then gather root samples off the herbs you find in the Barrens. Bring back these samples so that I may compare them with herbs from other regions.",objectivesText="Collect 8 Root Samples from herbs around North Barrens. Progress: Hello, <name>. Did you get those root samples ?",rewardGold=53500,rewardXP=740,rewardItems={5341},rewardChoices={5341},starts={{npcID=3446}},ends={{npcID=3446}},coords={x=0.678,y=0.716,source="quest_giver",zoneID=17},questType="standard"},
[867] = {id=867,name="Harpy Raiders",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="Since you're here, , perhaps you can help me with a small problem. The blasted harpies have been ravaging our caravan supplies for too long. It's time we slit a few of their throats and diminished their numbers. The most devastating attack will destroy a good section of their lower chain of command and then we can work our way to the top. Take out Witchwing harpies of any kind in the Northwest and bring me 6 Witchwing Talons . That should be a good start...",objectivesText="Collect 6 Witchwing Talons from Witchwing harpies. Progress: Cut up enough of them yet? Keep slicing and taking trophies. I want 8 Witchwing talons .",rewardGold=105000,rewardXP=740,starts={{npcID=3449}},ends={{npcID=3449}},coords={x=0.306,y=0.458,source="quest_giver",zoneID=17},questType="standard"},
[869] = {id=869,name="To Track a Thief",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="Animal tracks surround the wreckage, tracks made by enormous curved claws. They appear to be raptor tracks. Your first instinct is that raptor-riders assaulted the caravan, but the impressions aren't deep and there are no non-animal tracks to be seen. The tracks head northeast of here toward the east side of Thorn Hill. The answer to this mystery must lie in its shadow.",objectivesText="The tracks lead to the east side of Thorn Hill. Follow them and see what you find.",rewardXP=185,starts={{npcID=3464}},ends={{npcID=3464}},coords={x=0.668,y=0.726,source="quest_giver",zoneID=17},questType="standard"},
[870] = {id=870,name="The Forgotten Pools",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="Have you felt the tremors, ? Something has cleaved this land in two. But we druids can sense other tremors, as well. Life is stirring in lands once dry and lifeless. The oases around the Crossroads are suddenly blooming. I can sense a power leaking its way to the surface, but from where? Is it related to the disaster that shattered the Barrens? We must find the source. Travel to the Forgotten Pools, northwest of the Crossroads. Search its waters for a source of power, then return here.",objectivesText="Search the bottom of the Forgotten Pools northwest of the Crossroads.",rewardXP=555,starts={{npcID=3448}},ends={{npcID=3448}},coords={x=0.494,y=0.586,source="quest_giver",zoneID=17},questType="standard"},
[871] = {id=871,name="In Defense of Far Watch",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="All the quilboars are our enemies, . Some just prove to be more of a nuisance than others. The Razormane tribe has been attacking our supply caravans that roll through here from Orgrimmar. I have scouts seeking the leader of these raids, but until then, any losses you can inflict on the filthy pig men would aid us. Start just south of here, where they've been raiding our camps near the river. Seek them out, and slay them.",objectivesText="Kill 8 Razormane Plunderers and 3 Razormane Hunters .",rewardXP=740,starts={{npcID=3337}},ends={{npcID=3337},{npcID=3429}},coords={x=0.676,y=0.394,source="quest_giver",zoneID=17},questType="standard"},
[872] = {id=872,name="The Far Watch Offensive",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="Pigmen running amok right on the border of Durotar? Not on my watch! It is as they say, : The best defense is crushing all who oppose you. One of my scouts followed the quilboar after the last caravan raid, so we know where to strike. Kreenig Snarlsnout is the mastermind behind the attacks along the river. Crush him, . Defeat him and disembowel his forces so that the attacks on this camp cease. Search for a quilboar-infested cavern along the river, just south of our stables.",objectivesText="Kill 5 Razormane Defenders , 5 Razormane Thornweavers , and Kreenig Snarlsnout. Take Snarlsnout's Tusk. Progress: Cut off the head of their leader, and chaos ensues, <name>. Learn this lesson well. It will aid you in the future.",rewardXP=740,rewardItems={5275,5328,59542,59543,59544,131224},rewardChoices={59542,59543,59544,131224},starts={{npcID=3337},{npcID=3429}},ends={{npcID=3337},{npcID=3429}},coords={x=0.676,y=0.394,source="quest_giver",zoneID=17},questType="standard"},
[875] = {id=875,name="Harpy Lieutenants",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="The only way to stop the harpy raiders is to destroy their chain of command. The harpies are led by fearless lieutenants, Witchwing Slayers . If the Slayers fall, the rest will follow. Go to the Dry Hills and cut down the Witchwing Slayers . Make sure they die painfully, . We want those harpy wenches to know the idiocy of picking fights with the Horde.",objectivesText="Kill 6 Witchwing Slayers in the Dry Hills of the Northern Barrens . Progress: Do you have 6 Harpy Lieutenant Rings yet? Justice must be dealt to them for their vicious attacks on the Horde.",rewardGold=105000,rewardXP=740,starts={{npcID=3449}},ends={{npcID=3449}},coords={x=0.306,y=0.458,source="quest_giver",zoneID=17},questType="standard"},
[876] = {id=876,name="Serena Bloodfeather",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="The harpies you've killed mentioned their matron, Serena Bloodfeather. Judging from their vile hatred toward the Horde, she must hold some kind of deep-seated grudge. You decide to hunt down Serena Bloodfeather and end matters once and for all.",objectivesText="Slay Serena Bloodfeather and collect her head. Progress: You're not getting anything until I see Serena's head .",rewardXP=925,rewardItems={5279,5318,5321,59588,59589,59590},rewardChoices={59588,59589,59590},starts={{npcID=3449}},ends={{npcID=3449}},coords={x=0.306,y=0.458,source="quest_giver",zoneID=17},questType="standard"},
[877] = {id=877,name="The Stagnant Oasis",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="Can what's happening to the south happen here? Judging by what you found at the Forgotten Pools, these oases may be the key. Let's perform an experiment. Here, take these seeds I've collected from the summit here. They are dead and infertile, but carry them down to the Stagnant Oasis just below us. If there is a fissure there, then place the seeds within it... and observe. Report your findings back to Tonga at the Crossroads.",objectivesText="Use the dried seeds to investigate the fissures in the Stagnant Oasis. Progress: Did Jerrik have any ideas? You look like you've been rummaging around in the mud...",rewardXP=740,starts={{npcID=3448},{npcID=34626}},ends={{npcID=3448}},coords={x=0.494,y=0.586,source="quest_giver",zoneID=17},questType="standard"},
[880] = {id=880,name="Altered Beings",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=4709,mapID=10,description="It will be important to study both plant and animal life impacted by the oases and the unusual energies you've discovered. The Stagnant Oasis below us is home to a species of snapjaw turtles. Recently their population has exploded. Moreover, the once peaceful animals are growing aggressive, as I learned the hard way before trekking up here. I suspect they've been altered by the oases. Collect their shells and take them to Tonga at Crossroads for further study.",objectivesText="Collect 6 Altered Snapjaw Shells from Snapjaws in the Stagnant Oasis. Progress: What else have you brought me?",rewardGold=105000,rewardXP=740,starts={{npcID=3448},{npcID=34626}},ends={{npcID=3448}},coords={x=0.494,y=0.586,source="quest_giver",zoneID=17},questType="standard"},
[881] = {id=881,name="Echeyakee",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="Whitemist, or ' Echeyakee ' in the tauren tongue, is the king of the savannah cats. He hunts with such stealth, they say he's like a thin, white mist on the earth. He kills so fast his prey have no time for fear or pain. The tauren say he is both mercy and death. , I now set you on the path to hunt Echeyakee . His lair is just northwest of here, on the north side of a small mountain, among the bones of giant Kodo. Go. Blow this horn when you reach his lair. Blow the horn, and he will come.",objectivesText="Blow your horn at Echeyakee 's lair to summon him. Slay or subdue him.",rewardXP=925,starts={{npcID=3338}},ends={{npcID=3338}},coords={x=0.5,y=0.598,source="quest_giver",zoneID=17},questType="standard"},
[887] = {id=887,name="Southsea Freebooters",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="Gazlowe promised me a promotion if I can help him with Ratchet's pirate issues. The problem is these new buccaneers that sailed in and took over Fray Island, south of here. They're not just after our goods - they've got grudges to settle! The other night they even went after one of our war galleons. I've got plans in the works to deal with the situation, but Gazlowe wants to see quick results. Head over to Fray Island and start lopping off some heads, will you?",objectivesText="Kill 8 Southsea Cutthroats or Privateers on Fray Island.",rewardGold=482040,rewardXP=740,starts={{npcID=3391},{npcID=3453}},ends={{npcID=3391},{npcID=3453}},coords={x=0.684,y=0.69,source="quest_giver",zoneID=17},questType="standard"},
[891] = {id=891,name="A Captain's Vengeance",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="Yet another ship from my fleet has been lost to those overzealous humans from Theramore! Their new Rear Admiral has parked himself right off the coast here. He's boarding or sinking any vessel that doesn't heave-to at his whim. Travel south along the Merchant Coast to his camp. Bring me the medals of the marines and deck hands. Execute his top Lieutenants, Pyre and Buckland. Lay waste to them as they have laid waste to my fleet!",objectivesText="Collect 10 Theramore Medals from Theramore Marines and Deck Hands. Kill Lieutenants Pyre and Buckland. Progress: Fill my hand with medals from their dead and I will know that vengeance has been given to my fallen privateers.",rewardXP=740,rewardItems={5309,5310},starts={{npcID=3339}},ends={{npcID=3339}},coords={x=0.676,y=0.74,source="quest_giver",zoneID=17},questType="standard"},
[895] = {id=895,name="WANTED: Cap'n Garvey",level=5,requiredLevel=5,faction="both",expansion=0,zoneID=17,mapID=10,description="WANTED ! \"Cap'n\" J. Garvey of the Maiden's Dagger Charged with piracy on the open seas, kidnapping, extortion, arson, slavery, et al. Garvey recently arrived in these waters leading a crew of Southsea Freebooters and was last seen assaulting Fray Island. Bring proof of death in an identifiable condition! -- Gazlowe",objectivesText="Bring the head of Cap'n Garvey to Gazlowe in Ratchet. Progress: What's happening? Something I can help you with? Goods to ship, perhaps an engineering job?",rewardGold=53500,rewardXP=740,rewardItems={49446,49543,49548,49560,131225,131226},rewardChoices={49560,49543,49548,49446,131225,131226},starts={{npcID=3972}},ends={{npcID=3391}},coords={x=0.683,y=0.713,source="quest_giver",zoneID=17},questType="standard"},
[899] = {id=899,name="Consumed by Hatred",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="They murdered my wife. They burned my homestead. Since that awful night I have traveled these lands, from the sun's rising till its decline, scouring the horizon for more of those monsters. I've killed every pig man I've come across since, but my thirst for their blood is far from quenched. You, - you could help me. Kill them. Kill as many as you can. Bring me their tusks, and we will celebrate their deaths together.",objectivesText="Collect 30 Quilboar Tusks . Progress: The quilboar will pay for this, <name>. I swear it.",rewardXP=740,rewardItems={5314,6477,59539,59540,59541,131227},rewardChoices={59539,59540,59541,131227},starts={{npcID=3432}},ends={{npcID=3432}},coords={x=0.552,y=0.41,source="quest_giver",zoneID=17},questType="standard"},
[903] = {id=903,name="Hunting the Huntress",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="If you want to really demonstrate your bravery to me, let me send you after something that really bites. The savannah huntresses of the Barrens are as sly as they come. Tough, resourceful, quick... and deadly. They've been hassling our scouts recently around the outskirts of the town, especially to the northeast. Be wary as you hunt them, , or you may find yourself no longer the predator, but instead the prey.",objectivesText="Collect 5 Huntress Claws from Savannah Huntresses. Progress: How goes your hunt, <name>?",rewardGold=105000,rewardXP=740,starts={{npcID=3338}},ends={{npcID=3338}},coords={x=0.5,y=0.598,source="quest_giver",zoneID=17},questType="standard"},
[905] = {id=905,name="Into the Raptor's Den",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="The hunt deepens, . Now you must find and defeat your prey within its lair. Hunt the Sunscale raptors to the south, where they have built a warren amongst the hills just off of the road. Slay them and remove the feathers they wear. Place the feathers on the sunscale raptor nests to show their brethren you do not fear them! Be cautious, . Raptors hunt in packs and will swarm you if you are not cautious.",objectivesText="Kill Sunscale raptors and collect their feathers. Use the feathers on the 3 Sunscale Nests. Progress: Have you been to the nests, <name>?",rewardGold=105000,rewardXP=740,rewardItems={5165,59549,59550},rewardChoices={59549,59550},starts={{npcID=3338}},ends={{npcID=3338}},coords={x=0.5,y=0.598,source="quest_giver",zoneID=17},questType="standard"},
[918] = {id=918,name="Timberling Seeds",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="The timberlings of Teldrassil are elementals of nature. In some ways they reflect the natural order of plants and animals on our great tree. So it is disturbing to see how angry the timberlings are, particularly considering that things should be healing. I want to help hunt down the source. I have been working on different methods of nurturing plants and would like to try them on timberling seeds . Please, can you gather seeds from timberlings around Lake Al'Ameth and bring them to me?",objectivesText="Retrieve 6 Timberling Seeds . Progress: Do you have the seeds? I am eager to plant them.",rewardGold=105000,rewardXP=200,rewardItems={4604},starts={{npcID=2080}},ends={{npcID=2080}},coords={x=0.598,y=0.596,source="quest_giver",zoneID=141},questType="standard"},
[919] = {id=919,name="Timberling Sprouts",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="Small timberlings are sprouting around the waters of Lake Al'Ameth. I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble. When you're wandering the lake, if you see any timberling sprouts please take them. Help keep our land clean!",objectivesText="Collect 10 Timberling Sprouts . Progress: Hello, <name>. Have you found any sprouts near the waters?",rewardGold=107000,rewardXP=250,rewardItems={5606,6061},rewardChoices={5606,6061},starts={{npcID=2080}},ends={{npcID=2080}},coords={x=0.598,y=0.596,source="quest_giver",zoneID=141},questType="standard"},
[922] = {id=922,name="Rellian Greenspyre",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description=", can you take one of the seeds you brought me to my friend, Rellian Greenspyre ? He is a druid that resides at Wellspring Hovel, and when last we spoke he revealed his interest in my work with the Timberlings. He had some ideas himself, and he will appreciate a specimen seed to work with. Thank you, . I hope that, some day, you will see the fruit of my labors. You will find Wellspring Hovel along the road heading west out of Dolanaar, on the way to Darnassus.",objectivesText="Bring a Timberling Seed to Rellian Greenspyre at Wellspring Hovel. Progress: Hello... And how may I help you?",rewardGold=40125,rewardXP=150,starts={{npcID=2080}},ends={{npcID=3517}},coords={x=0.598,y=0.596,source="quest_giver",zoneID=141},questType="standard"},
[923] = {id=923,name="Mossy Tumors",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="There is a malevolence growing in the timberlings. We are trying to find the source, but until we do...in order to keep Teldrassil safe we must cut down the timberlings who are beyond help. Those that wander Wellspring Lake to the north are the most tainted. They must be removed! Destroy the Timberlings you find there, and gather the mossy tumors growing upon them. Bring the tumors to me so that they may be burned.",objectivesText="Retreive 5 Mossy Tumors . Progress: Have you been to Wellspring Lake, <name>? Have you been hunting the timberlings there?",rewardGold=107000,rewardXP=250,rewardItems={5605,157016},rewardChoices={5605,157016},starts={{npcID=3517}},ends={{npcID=3517}},coords={x=0.44,y=0.442,source="quest_giver",zoneID=141},questType="standard"},
[927] = {id=927,name="The Moss-twined Heart",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="The heart of Blackmoss the Fetid is covered with a dark, oily moss. In fact, the only way to tell this is a heart is from its slow, rhythmic beat... A beat that continues even now. Perhaps Denalan will want to see this heart.",objectivesText="Bring the Moss-twined Heart to Denalan at Lake Al'Ameth. Progress: <name>! You have something for me?",rewardXP=100,ends={{npcID=2080}},coords={mapID=57,source="quest_giver",x=0.518,y=0.519},questType="standard"},
[929] = {id=929,name="Teldrassil: The Refusal of the Aspects",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="Let me tell you more of the task you must complete. The druids in Darnassus use the water of the moonwells of Teldrassil , and their moonwell must be replenished from time to time. Using these specially crafted phials, you can collect the water of the moonwells. Take this vessel to the moonwell outside of Starbreeze Village to the east, and fill it with some of its waters, then return to me. Pay heed to the lessons of the moonwells, lest we find ourselves furthering our shortcomings.",objectivesText="Fill the Jade Phial . Progress: Hello again, <name>. Have you completed your task?",rewardXP=200,starts={{npcID=3515}},ends={{npcID=3515}},coords={x=0.558,y=0.538,source="quest_giver",zoneID=141},questType="standard"},
[930] = {id=930,name="The Glowing Fruit",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="Hanging from beneath the fronds of this glowing plant is a large, round fruit. Denalan would want to study this fruit, you are certain.",objectivesText="Bring the glowing fruit to Denalan at Lake Al'Ameth. Progress: <name>, you look like you have something to tell me. Do you have news concerning the timberlings?",rewardGold=105000,rewardXP=200,starts={{npcID=6751}},ends={{npcID=2080}},coords={x=0.578,y=0.63,source="quest_giver",zoneID=141},questType="standard"},
[931] = {id=931,name="The Shimmering Frond",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="The fronds on this plant shimmer in the forest light, giving it a twisting, pulsing aura. You believe that Denalan would want a specimen of this.",objectivesText="Bring a Shimmering Frond to Denalan . He can usually be found at Lake Al'Ameth, but sometimes travels to Wellspring Hovel. Progress: You have something for me?",rewardGold=105000,rewardXP=200,starts={{npcID=6752}},ends={{npcID=2080}},coords={x=0.373,y=0.255,source="quest_giver",zoneID=141},questType="standard"},
[932] = {id=932,name="Twisted Hatred",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="I must warn you, , this matter must stay between us. The satyr are enough of an embarrassment to us already, and this one is much too close to home. He is called Lord Melenas. He resides in the nearby cave of Fel Rock, to the north, where he has gathered a large group of grell warriors. His heart is black as night, and he plots something most foul. You must find him within his nearby cave just to the north of here, and bring me his head.",objectivesText="Retrieve the head of Lord Melenas. Progress: Did you kill Lord Melenas yet? It is vital that he be taken care of quickly and quietly, <name>. His continued existence is an embarrassment to us all.",rewardXP=200,rewardItems={2571,5419,54867,131228},rewardChoices={5419,2571,54867,131228},starts={{npcID=3567}},ends={{npcID=3567}},questType="standard"},
[933] = {id=933,name="Teldrassil: The Coming Dawn",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="There is one last moonwell that I would like you to visit. It is directly south of here, on the shores of the Pools of Arlithrien. Be wary as you seek out the well, and keep your weapons close at hand. I sense a growing corruption from the boughs of southern Teldrassil . When you have the water, I want you to bring it to a familiar face that you'll see at the pools. She wishes to battle the corruption, and has asked for you personally.",objectivesText="Fill the Tourmaline Phial . Progress: It is good to see you again, <name>. I see you have succeeded in collecting the waters of the moonwells on behalf of Corithras Moonrage . I hope you have learned much along the way.",rewardXP=200,starts={{npcID=3515}},ends={{npcID=1992}},coords={x=0.558,y=0.538,source="quest_giver",zoneID=141},questType="standard"},
[935] = {id=935,name="The Waters of Teldrassil",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="Our tasks are done here for now. This water proved to be of great importance, but it wasn't originally meant for me. Go ahead and bring it back to Corithras at the crossroads, I'm sure he'd like you to deliver it to its original destination.",objectivesText="Bring the Filled Vessel to Corithras Moonrage at the crossroads in front of Darnassus. Progress: It is good to see you again. I sense that Tarindrella 's task went smoothly with you by her side.",rewardXP=200,rewardItems={5595,5596,54873,54874,131861,156992},rewardChoices={54873,54874,131861,5595,5596,156992},starts={{npcID=1992}},ends={{npcID=3515}},coords={x=0.424,y=0.582,source="quest_giver",zoneID=141},questType="standard"},
[937] = {id=937,name="The Enchanted Glade",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade. Little by little we are trying to push them back. When the Oracle Tree attempted to send a runner to Darnassus with a report, the messenger was attacked and killed by a group of the harpies. If you feel up to the task, go to their nests, slay them, and return their belts to me as proof of your deeds.",objectivesText="Acquire 6 Bloodfeather Belts . Progress: Their slashing talons and piercing beaks may prove a difficult match for your own abilities, <name>, but I have faith that you will not fail in this task.",rewardXP=200,rewardItems={5591,5592,54872,131229},rewardChoices={54872,5591,131229},starts={{npcID=3519}},ends={{npcID=3519}},coords={x=0.394,y=0.298,source="quest_giver",zoneID=141},questType="standard"},
[938] = {id=938,name="Mist",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="The sabercat's fur is a distinctive gray color, blending into the surrounding forest. As she lays there, you observe that she is badly wounded, with deep lacerations across her back and stomach. She raises her head and gazes at you, bright intelligence shining in blue eyes. She seems to wish to follow you.",objectivesText="Escort Mist to Sentinel Arynia Cloudsbreak at the moon well near the Oracle Tree. Progress: Mist ... It was my fault! The witches caught me off guard... I should not have let them take you...",rewardGold=22600,rewardXP=200,rewardItems={5590,5593,5618,54871,131230},rewardChoices={5590,54871,5593,131230},starts={{npcID=3568}},ends={{npcID=3519}},coords={x=0.344,y=0.278,source="quest_giver",zoneID=141},questType="standard"},
[941] = {id=941,name="Planting the Heart",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="I have removed that foul moss from the heart, but it remains tainted... Try placing the heart in my planter. It is filled with a nutritive soil that may cleanse and heal the heart.",objectivesText="Plant the Tainted Heart in Denalan's Planter . Progress: This planter is filled with soil, specially prepared by Denalan .",rewardXP=200,rewardItems={5218},starts={{npcID=2080}},ends={{npcID=7923}},coords={x=0.598,y=0.596,source="quest_giver",zoneID=141},questType="standard"},
[996] = {id=996,name="Corrupted Windblossom",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=361,objectivesText="Progress: You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.",rewardItems={11950},starts={{npcID=164887}},ends={{npcID=164887}},coords={x=0.39,y=0.591,source="quest_giver",zoneID=361},questType="standard"},
[997] = {id=997,name="Denalan's Earth",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="Are you heading to the south? To Lake Al'Ameth? If so, then I have a task I might ask of you... My colleague Denalan has a camp along the eastern end of the lake, where he is studying and experimenting on the plant life of Teldrassil . He requested a package of rare earths from Darnassus and it was late, only recently arriving here in Dolanaar. Can you take the package to him?",objectivesText="Bring the package of Rare Earth to Denalan at Lake Al'Ameth. Progress: You have something for me?",rewardGold=26750,rewardXP=100,starts={{npcID=2083}},ends={{npcID=2080}},coords={x=0.558,y=0.504,source="quest_giver",zoneID=141},questType="standard"},
[998] = {id=998,name="Corrupted Windblossom",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=361,objectivesText="Progress: You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.",rewardItems={11950},starts={{npcID=164887}},ends={{npcID=164887}},coords={x=0.39,y=0.591,source="quest_giver",zoneID=361},questType="standard"},
[1036] = {id=1036,name="Avast Ye, Scallywag",level=10,requiredLevel=55,faction="both",expansion=0,zoneID=5287,mapID=210,description="... yeah, I've heard of you. I've heard that you're no friend of Booty Bay - just like us Bloodsail Buccaneers . Fleet Master Firallon is looking for hale and hearty just like you for a special mission. If you're interested, head on out to the Crimson Veil and speak with him below decks. She's anchored off the Wild Coast east of here, next to the Riptide and the Damsel's Luck.",objectivesText="Speak with Fleet Master Firallon aboard the Crimson Vale off the coast of Stranglethorn Vale.",rewardXP=175,starts={{npcID=2545}},ends={{npcID=2546}},coords={x=0.444,y=0.926,source="quest_giver",zoneID=5287},questType="standard"},
[1097] = {id=1097,name="Elmore's Task",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1519,mapID=37,description="There's a dwarven weaponsmith in Stormwind, Grimand Elmore , who sent word that he needs help with a delivery. I believe he wants a package sent to his homeland in the north. You have a sturdy pair on you! So if you're interested in some legwork then speak with Grimand. We could use you down here, but we must also keep our ties strong with the dwarves. You can find Grimand Elmore at the weapon shop in the Dwarven District of Stormwind, in the northeast section of town.",objectivesText="Speak with Grimand Elmore in Stormwind.",rewardXP=25,starts={{npcID=514}},ends={{npcID=1416}},coords={x=0.416,y=0.656,source="quest_giver",zoneID=12},questType="standard"},
[1168] = {id=1168,name="Army of the Black Dragon",level=15,requiredLevel=15,faction="horde",expansion=0,zoneID=15,mapID=70,description="Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres. Black dragons kill many ogre. Kill Tharg 's wife. Mok'Morokk tell us to run. Make us come here. Ogre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk. Me call Stonemaul Ruins home. Me like it in the south. This place not home. Help ogres fight army of the black dragon. Me want revenge. Me want to go home.",objectivesText="Tharg in Brackenwall Village wants you to kill 10 Firemane Scouts , 10 Firemane Ash Tails , and 5 Firemane Scalebanes .",rewardXP=2090,rewardItems={9705,9706,10702},rewardChoices={10702,9706},starts={{npcID=4502}},ends={{npcID=4502}},coords={x=0.372,y=0.314,source="quest_giver",zoneID=15},questType="standard"},
[1201] = {id=1201,name="Theramore Spies",level=15,requiredLevel=15,faction="horde",expansion=0,zoneID=15,mapID=70,description="The Horde and Alliance hold an uneasy truce. Outlying skirmishes and covert actions are taken by one side against the other, and it is our duty to ensure the Horde is on top! Now is the chance to do just that. Alliance infiltrators have taken positions east of Brackenwall Village. They spy on the village and report our movements to Theramore, which we cannot allow. Hunt down the infiltrators and slay them. Send a clear message to their superiors that we will not tolerate their spies' presence!",objectivesText="Kill 9 Theramore Infiltrators , then return to Nazeer Bloodpike in Brackenwall Village.",rewardXP=2090,starts={{npcID=4791}},ends={{npcID=4791}},coords={x=0.352,y=0.306,source="quest_giver",zoneID=15},questType="standard"},
[1202] = {id=1202,name="The Theramore Docks",level=15,requiredLevel=15,faction="horde",expansion=0,zoneID=15,mapID=70,description=", two of our spies were sent to steal documents from a ship at the Theramore docks. They gained the papers but were discovered, and were forced to throw the documents into the sea. One spy later escaped, but was unable to recover the prize. He reported his failure to me, and I now charge the task to you. The documents are in a footlocker, in the waters somewhere beneath the Theramore docks. Find those documents, , and bring them to me.",objectivesText="Bring the Captain's Documents to Nazeer Bloodpike in Brackenwall Village. Progress: Did you find the documents, <name>? They hold information vital to the stability of the Alliance and, hence, vital to the security of the Horde.",rewardXP=2090,starts={{npcID=4791}},ends={{npcID=4791}},coords={x=0.352,y=0.306,source="quest_giver",zoneID=15},questType="standard"},
[1204] = {id=1204,name="Mudrock Soup and Bugs",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=15,mapID=70,description="I'm working on a dish I call \"Mudrock Soup and Bugs.\" I still need the major ingredients, and... well, I don't think I'd last long trudging through Dustwallow Marsh ! So, , can you do some hunting for me? First, I need the tongues of Mudrock turtles. You can find Mudrocks along the coast, mostly around the bay. But I don't want just any tongues! I hear that the tongues of some Mudrocks are forked... They say the forked tongues have a distinct flavor, and I want that flavor in my dish...",objectivesText="Bring 8 Forked Mudrock Tongues to Morgan Stern in Theramore. Progress: Did you get the forked tongues?",rewardXP=2090,starts={{npcID=4794}},ends={{npcID=4794}},coords={x=0.682,y=0.486,source="quest_giver",zoneID=15},questType="standard"},
[1222] = {id=1222,name="Stinky's Escape",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=6040,mapID=70,description="Great, finally something that doesn't want to eat me! I need help handling the critters around here, and you fit the mold, . The cook Morgan Stern is researching a new recipe, and he sent me out here to gather bogbean leaves. I guess he thinks they're tasty. Anyway, while looking for a bogbean plant... I got myself surrounded! Can you help me out of here, and watch my back as I look for the bogbean?",objectivesText="Escort \"Stinky\" Ignatz, then speak with Morgan Stern in Theramore.",rewardGold=27750,rewardXP=2090,rewardItems={3825},starts={{npcID=4880}},ends={{npcID=4794}},coords={x=0.468,y=0.176,source="quest_giver",zoneID=15},questType="standard"},
[1258] = {id=1258,name="... and Bugs",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=8,mapID=70,description="Another component of my new recipe is the shelled leg of a giant crab. And the crabs they have in Dustwallow -- spiny rock crawlers they call them -- will be perfect! The shell of the crab leg is a key element of the dish's presentation so I need pristine, unscarred legs. An adult crab might only have one or two such legs, and I need a lot in order to research my dish. Head on over to the rocks surrounding Theramore and get me those legs!",objectivesText="Bring 12 Pristine Crawler Legs to Morgan Stern in Theramore. Progress: My research with the Mudrock tongues is progressing nicely. I trust your crab hunt goes well?",rewardXP=2090,rewardItems={6801,57843,57844},rewardChoices={57843,57844},starts={{npcID=4794}},ends={{npcID=4794}},coords={x=0.682,y=0.486,source="quest_giver",zoneID=15},questType="standard"},
[1270] = {id=1270,name="Stinky's Escape",level=15,requiredLevel=15,faction="horde",expansion=0,zoneID=6040,mapID=70,description="Great, finally something that doesn't want to eat me!! I need help handling the critters around here, and you fit the mold, . A goblin from Ratchet named Mebok Mizzyrix needs some bogbean leaves for a potion, or something... I honestly don't care why -- his money was good and I know this swamp, so here I am. Too bad I got myself surrounded before I found the bogbean! Can you help me out of here, and watch my back as I look for Mebok's plant?",objectivesText="Escort \"Stinky\" Ignatz, then speak with Mebok Mizzyrix in Ratchet.",rewardGold=27750,rewardXP=2090,rewardItems={3825},starts={{npcID=4880}},ends={{npcID=3446}},coords={x=0.468,y=0.176,source="quest_giver",zoneID=15},questType="standard"},
[1271] = {id=1271,name="Feast at the Blue Recluse",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=1519,mapID=84,rewardItems={5951},starts={{npcID=1141}},ends={{npcID=1141}},coords={x=0.516,y=0.934,source="quest_giver",mapID=84},questType="standard"},
[1453] = {id=1453,name="Reclaimers' Business in Desolace",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=405,mapID=87,description="There's work to be done in Desolace, . It's an atrocious place, befouled by centaur and other nasties. But if you're looking for a good week's honest work, then head there, meet with Kreldig Ungor , and tell him I sentcha. You can find him holed up at Nijel's Point--it's a little cozy camp hidden in the mountains of northern Desolace. Just head east if you enter from the Stonetalon Mountains. It's easy to miss, so be on the lookout.",objectivesText="Speak to Kreldig Ungor in Desolace.",rewardXP=710,starts={{npcID=5637}},ends={{npcID=5638}},coords={x=0.696,y=0.21,source="quest_giver",zoneID=1537},questType="standard"},
[1454] = {id=1454,name="The Karnitol Shipwreck",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=405,mapID=66,description="Greetings, friend. Have yerself a seat here... My first order of business is for the mage Karnitol--a noble of some sort in Stormwind. Seems his ship was attacked by sea giants while off the coast in the northwest of Desolace . He and his servants tried to bring one of his more valuable chests ashore, but when the sea giants attacked in droves, he chose to abandon it and teleport himself and his servants to safety. He wants us to find the chest and its contents, and return it to him in Stormwind.",objectivesText="Find Karnitol's Chest in Desolace .",rewardXP=1415,starts={{npcID=5638}},ends={{npcID=35251}},coords={x=0.662,y=0.096,source="quest_giver",zoneID=405},questType="standard"},
[1455] = {id=1455,name="The Karnitol Shipwreck",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=405,mapID=66,description="You take a few moments to figure out what pried the chest open, and you notice along the sides and top of the chest, long, deep scratches that reveal that something other than a man or giant took interest in it. The marks don't appear as if they were caused by dagger or sword. After going through the chest you find it to be completely empty. Not having another course of action, you close the chest and prepare to leave. Kreldig will be disappointed.",objectivesText="Return to Kreldig Ungor in Desolace .",rewardXP=710,starts={{npcID=35251}},ends={{npcID=5638}},coords={x=0.361,y=0.304,source="quest_giver",zoneID=405},questType="standard"},
[1456] = {id=1456,name="The Karnitol Shipwreck",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1,mapID=66,description="Intriguing. Well, we might not be without hope quite yet. Along that same coast, but to the north near Ranazjar Isle, there're night elf ruins at the bottom of the ocean. A tribe of naga, the Slitherblade, make that their home. I think that'd be our best bet. If a scouting party went that far south, then they must've been pretty powerful. If you're gonna find Karnitol's belongings, I'd start with the more powerful naga: the tidehunters or sea witches.",objectivesText="Find Karnitol's Satchel and return it to Kreldig Ungor in Desolace . Progress: No offense to whoever Nijel is, but this camp ain't the most comfortable place I've spent a night, if you know what I mean, <name>.",rewardXP=1415,rewardItems={55948,55949,55950,131231},rewardChoices={55949,55950,55948,131231},starts={{npcID=5638}},ends={{npcID=5638}},coords={x=0.662,y=0.096,source="quest_giver",zoneID=405},questType="standard"},
[1468] = {id=1468,name="Children's Week",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1519,mapID=84,description="You're willing to help us here at the orphanage? Bless you, friend; your aid during Children's Week will be invaluable. Take this whistle. You will only be able to use it for a short amount of time - typically not longer than Children's Week itself. When you use it, you will be able to talk with the child you've agreed to look after. Using it again will dismiss the child. By all means - use the whistle and meet your ward! I'm sure the child will be most eager to meet you.",objectivesText="Use the Human Orphan Whistle to talk with the child you will be looking after during Children's Week. Provided item:",starts={{npcID=51988}},ends={{npcID=51988}},coords={x=0.562,y=0.542,source="quest_giver",zoneID=1519},questType="standard"},
[1581] = {id=1581,name="Elixirs for the Bladeleafs",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="Our herb and alchemy shop is booming, but my husband spends so much time mixing potions that we never have time for each other. Can you help us? If you can bring me a supply of pre-made elixirs, then I would be happy to trade with you. I have some rare herbs that you might find useful.",objectivesText="Bring 6 Elixirs of Lion's Strength and 2 Elixirs of Minor Defense to Syral Bladeleaf in Dolanaar. Progress: Hello, <name>. Do you have the elixirs to trade?",rewardGold=105000,rewardXP=200,rewardItems={785,2449},starts={{npcID=2083}},ends={{npcID=2083}},coords={x=0.558,y=0.504,source="quest_giver",zoneID=141},questType="standard"},
[1618] = {id=1618,name="Gearing Redridge",level=7,requiredLevel=7,faction="alliance",expansion=0,zoneID=44,mapID=87,description="We dwarves aren't the only ones fighting. Our human allies have their hands full too! Redridge is under periodic attack from blackrock orcs, and their supply of equipment is always low. If you were to help them out, I'm sure their resident blacksmith, Verner Osgood , would teach you a trick or two.",objectivesText="Tormus Deepforge wants you to bring 4 Runed Copper Belts and 4 Heavy Copper Mauls to Verner Osgood in Redridge. Progress: I hope you're here with good news from Ironforge. Because I'm at my wit's end!",rewardXP=1010,rewardItems={6735},starts={{npcID=6031}},ends={{npcID=415}},coords={x=0.49,y=0.424,source="quest_giver",zoneID=1537},questType="standard"},
[1655] = {id=1655,name="Bailor's Ore Shipment",level=5,requiredLevel=5,faction="alliance",expansion=0,zoneID=38,mapID=48,description="Ach, ya startled me, ! Can't ya see I was lost in thought? What's that? Jordan's shipment... fer Ironforge. Ahhh, yeah, I know whatcha speak of. Mo'grosh ogres... dat's who took me ol' friend's ore shipment. Caravan was headin' here from the Wetlands and was ambushed. The guard who survived their attack just passed away a few days ago--healer couldn't get to 'em fast enough. If you want the shipment, you'll have to head northeast across the Loch. It's got to be there somewhere.",objectivesText="This quest may no longer be available. Bring Jordan's Ore Shipment to Bailor Stonehand in Loch Modan. Progress: So, any luck yet? Haha, those ogres didn't get the best of ya yet, did they?",rewardItems={6993},starts={{npcID=6241}},ends={{npcID=6241}},coords={x=0.36,y=0.448,source="quest_giver",zoneID=38},questType="group"},
[1789] = {id=1789,name="The Symbol of Life",level=7,requiredLevel=7,faction="alliance",expansion=0,zoneID=1537,mapID=87,rewardItems={6866},starts={{npcID=6179}},ends={{npcID=6179}},coords={x=0.274,y=0.122,source="quest_giver",mapID=87},questType="standard"},
[1790] = {id=1790,name="The Symbol of Life",level=7,requiredLevel=7,faction="alliance",expansion=0,zoneID=1519,mapID=84,rewardItems={6866},starts={{npcID=6171}},ends={{npcID=6171}},coords={x=0.506,y=0.474,source="quest_giver",mapID=84},questType="standard"},
[1918] = {id=1918,name="The Befouled Element",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,mapID=63,description="The slain elemental has produced an intensely glowing globe of water. The contents of the globe are, at best, disgusting. It would be safe to assume that whatever has befouled the water of Mystral Lake is most likely present in the water of the globe. It's not exactly common knowledge who might be interested in such a find; perhaps Mastok Wrilehiss at Splintertree Post, might have an idea.",objectivesText="Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale . Progress: Yeah, what do you need?",rewardXP=255,ends={{npcID=12737}},coords={mapID=63,source="quest_giver",x=0.74,y=0.606},questType="standard"},
[2039] = {id=2039,name="Find Bingles",level=5,requiredLevel=5,faction="alliance",expansion=0,zoneID=38,mapID=87,description="We've lost contact with Bingles! He was sent on a reconnaissance mission over Gnomeregan and hasn't reported back in over a week. I just know he's gone and blown himself up. He was last seen flying over the Loch. Perhaps you can investigate, .",objectivesText="Find Bingles Blastenheimer in Loch Modan.",rewardXP=185,starts={{npcID=6569}},ends={{npcID=6577}},coords={x=0.694,y=0.506,source="quest_giver",zoneID=1537},questType="standard"},
[2158] = {id=2158,name="Rest and Relaxation",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=6170,mapID=37,description="Every adventurer should rest when exhaustion sets in - and there is no finer place to get rest and relaxation than at the Lion's Pride Inn! My best friend, Innkeeper Farley , runs the Lion's Pride. If you tell him I sent you, he may give you the special discounted rates on food and drink. To find the Lion's Pride Inn, travel south along the road from here -- you can't miss it!",objectivesText="Speak with Innkeeper Farley at the Lion's Pride Inn.",rewardXP=25,rewardItems={57395,57396,57397,132094},rewardChoices={57395,57396,132094,57397},starts={{npcID=6774}},ends={{npcID=295}},coords={x=0.454,y=0.488,source="quest_giver",zoneID=12},questType="standard"},
[2159] = {id=2159,name="Dolanaar Delivery",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=6450,mapID=57,description="Greetings, young . Can you offer me aid? I have a package of herbs that I must deliver to the town of Dolanaar. But I still have business with the druids of Shadowglen and cannot yet leave. Can you deliver this package for me? It must be sent to Innkeeper Keldamyr , at the Dolanaar inn. It lies along the road, to the south.",objectivesText="Bring the Dolanaar Delivery to Innkeeper Keldamyr . Progress: How might I be of service to you, young one? Are you here to rest in the inn? Do you require a hearthstone?",rewardGold=26250,rewardXP=50,rewardItems={159,2070},rewardChoices={2070,159},starts={{npcID=6780}},ends={{npcID=6736}},coords={x=0.602,y=0.416,source="quest_giver",zoneID=141},questType="standard"},
[2206] = {id=2206,name="Snatch and Grab",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=84,description="Our operatives in the field are reporting heavy bandit activity south of Goldshire. The reports indicate that bandits have taken over Jerod's Landing and are now using it as a way to smuggle large quantities of contraband from Redridge to Westfall. I need you to infiltrate the dock house and get me that shipping schedule , . You will probably find it buried deep in the pockets of the Dockmaster. ...and , should you be discovered, SI:7 will disavow all knowledge of your existence.",objectivesText="Find the Dockmaster and recover the Shipping Schedule for Master Mathias Shaw . Progress: Your mortality wanes with every moment you waste loitering in the barracks, <class>.",rewardXP=200,rewardItems={7298},starts={{npcID=332}},ends={{npcID=332}},coords={x=0.812,y=0.632,source="quest_giver",zoneID=1519},questType="standard"},
[2278] = {id=2278,name="The Platinum Discs",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1337,description="The centerpieces of this treasure chamber are four huge platinum discs, each adorned with numerous sigils of an unknown origin. Touching them makes your hand tingle. Just after touching the discs, the visage of a large stone watcher springs forth. \"Salutations. I am a keeper of knowledge. The Creators' synthesis of the Earthen has been chronicled and stored here for this world in the Discs of Norgannon .\" You have uncovered a wealth of previously undiscovered worldly lore!",objectivesText="Speak with stone watcher and learn what ancient lore it keeps. Once you have learned what lore it has to offer, activate the Discs of Norgannon . Progress: The voice of the stone watcher seems to resonate within your very inner being: \"You must first satisfy the data assimilation prerequisite of Discs of Norgannon; once you fulfill this requirement, you will then be permitted to obtain a portable version of the stored data. Please be sure you have fully explored the information within this repository first.\"",rewardGold=89550,rewardXP=2090,starts={{npcID=131474}},ends={{npcID=131474}},questType="dungeon"},
[2280] = {id=2280,name="The Platinum Discs",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=1638,mapID=88,description="Touching the Discs of Norgannon once again makes your hand tingle. This time, however, a strange grinding noise is heard from inside the discs. Your backpack suddenly becomes heavier than it was before. Inside, you discover a miniature version of the discs! No doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth. Someone would sure be interested in this!",objectivesText="Take the miniature version of the Discs of Norgannon to someone very interested in them. Progress: What is that you have there? What did you learn from the discs?",rewardGold=105000,rewardXP=2090,rewardItems={65921,65947,65971},rewardChoices={65947,65971,65921},starts={{npcID=131474}},ends={{npcID=46234},{npcID=46236},{npcID=3978}},questType="dungeon"},
[2399] = {id=2399,name="The Sprouted Fronds",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,rewardXP=25,rewardItems={5205},starts={{npcID=7510}},ends={{npcID=7510}},coords={x=0.439,y=0.441,source="quest_giver",mapID=57},questType="standard"},
[2438] = {id=2438,name="The Emerald Dreamcatcher",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="I was once given an emerald dreamcatcher from Gaerolas Talvethen, the warden of the druids in the Ban'ethil Barrow Den. This powerful amulet is able to siphon energy from the Emerald Dream, bestowing luck upon those who carry it. Sadly, I have not been able to retrieve it from my dresser in Starbreeze Village... Although Starbreeze was once a tranquil place, it has now succumbed to the corruption of the furbolg that reside there. Perhaps you would be willing to recover my dreamcatcher, ?",objectivesText="Retrieve the Emerald Dreamcatcher . Progress: Please move swiftly. I can only hope that my emerald dreamcatcher has been unharmed by the furbolg. Have you recovered it yet, <name>?",rewardGold=78750,rewardXP=150,starts={{npcID=3567}},ends={{npcID=3567}},coords={x=0.556,y=0.5,source="quest_giver",zoneID=141},questType="standard"},
[2459] = {id=2459,name="Ferocitas the Dream Eater",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="The emerald... It is missing! My dreamcatcher has been damaged! There is a band of Gnarlpine mystics located to the north of Starbreeze. I have heard reports that their leader, Ferocitas the Dream Eater, has been wearing a necklace that glows green in the night. Now seeing my dreamcatcher, I am sure that he has stolen my emerald... He would never realize that its power is useless to him. Find this missing jewel, . And, while you're there, clear out some of the corrupted mystics as well.",objectivesText="Kill 7 Gnarlpine Mystics and find the missing jewel. Progress: Ferocitas and the Gnarlpine mystics must return what is mine. Please retrieve the emerald so that I may repair my emerald dreamcatcher.",rewardGold=210000,rewardXP=250,starts={{npcID=3567}},ends={{npcID=3567}},coords={x=0.556,y=0.5,source="quest_giver",zoneID=141},questType="standard"},
[2499] = {id=2499,name="Oakenscowl",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="I figured it out! I had to rush here to find you! It's so simple really... the corruption has spread from timberling to timberling, but there's but one that is the source. Oakenscowl, he's being poisoned by the largest tumor I have ever seen... I would call it gargantuan, even. Oakenscowl used to reside in a cave near my lake, but has since found his way to a nook to the northeast of here. , Hunt down Oakenscowl and collect the tumor; remove this source of corruption from my home.",objectivesText="Collect the Gargantuan Tumor from Oakenscowl. Progress: Have you located Oakenscowl yet, <race>?",rewardGold=22600,rewardXP=200,rewardItems={5458,5589},rewardChoices={5458,5589},starts={{npcID=2080}},ends={{npcID=2080}},coords={x=0.598,y=0.596,source="quest_giver",zoneID=141},questType="standard"},
[2518] = {id=2518,name="Tears of the Moon",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1657,mapID=57,description="Lady Sathrah was once beloved of Elune. Graceful and pure, the spider spun her silver threads through the moonlight, catching the evening mist. The silvery dew had strong healing powers and was kept at the nearby temple. But of late, Sathrah has descended into madness. Her future generations are now threatened as well. Find Lady Sathrah, , and end her suffering. She dwells northeast of here, near the river. Gather her silvery spinnerets and bring them back to me.",objectivesText="Recover Lady Sathrah's Silvery Spinnerets . Progress: I regret the task that I have asked you to carry out; but Lady Sathrah is beyond hope. It is our hope to offer the sacrifice of the spinnerets to Elune. With this sacrifice, Elune will bless Sathrah so that she might be reborn, and at peace.",rewardGold=210000,rewardXP=250,starts={{npcID=7313}},ends={{npcID=7313}},coords={x=0.392,y=0.298,source="quest_giver",zoneID=141},questType="standard"},
[2523] = {id=2523,name="Corrupted Songflower",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=361,objectivesText="Progress: You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.",starts={{npcID=164886}},ends={{npcID=164886}},coords={x=0.529,y=0.878,source="quest_giver",zoneID=361},questType="standard"},
[2541] = {id=2541,name="The Sleeping Druid",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=61,description="The Gnarlpine shaman that inhabit this place have discovered a way of separating a sleeping druid's spirit from the physical body. The furbolg have animated my physical form and are using it to attack anyone that attempts to explore the Ban'ethil Barrow Den. I am now trapped in the Emerald Dream, powerless to stop this. You must help me. The Gnarlpine shaman carry a strange charm which is used to perform this ritual, and I'd like to examine it. Please, , bring one to me.",objectivesText="Bring a Shaman Voodoo Charm to Oben Rageclaw in the Ban'ethil Barrow Den. Progress: If I can examine the charm, I may be able to figure out how to break the enchantment. Have you found one?",rewardXP=200,starts={{npcID=7317}},ends={{npcID=7317}},questType="standard"},
[2561] = {id=2561,name="Druid of the Claw",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=60,description="After examining this charm, , I see now what must be done. Please take it, and do as I ask. You are to approach the door to the nearby chamber. Inside, you will find my soulless body... Although I regret what I am about to tell you, I see no other way to free myself from the control of the Gnarlpine. In order for me to escape them, you must kill my physical form. Once that is done, use the voodoo charm on my fallen body. After you have completed this task, please return to me.",objectivesText="Kill the soulless body of Oben Rageclaw , and then use the Voodoo Charm . Progress: <name>, be wary when approaching my physical form; the enchantment it is under is quite powerful.",rewardGold=53500,rewardXP=250,rewardItems={9598,9602,18957},rewardChoices={9598,18957},starts={{npcID=7317}},ends={{npcID=7317}},questType="standard"},
[2751] = {id=2751,name="Barbaric Battlements",level=15,requiredLevel=15,faction="horde",expansion=0,zoneID=1637,mapID=85,description="Twenty generations of Omosh have held this hammer, . A hundred thousand tons of metal we have molded. Tragically, it all ends at Orokk, failure of the Omosh: Without kin and incapable of producing offspring. I cannot let the secret recipes of Omosh die with me! Someone must continue the legacy, Omosh or not! Prove to Orokk you are capable, . Bring for Orokk the following: Two patterned bronze bracers , two bronze greatswords , and two sharp claws . Bring them for Orokk and we shall continue.",objectivesText="Bring two Patterned Bronze Bracers , two Bronze Greatswords , and two Sharp Claws to Orokk Omosh in Orgrimmar. Progress: Bronze, <name>! More bronze!!",rewardXP=2090,rewardItems={7979},starts={{npcID=7790}},ends={{npcID=7790}},coords={x=0.762,y=0.374,source="quest_giver",zoneID=1637},questType="standard"},
[2752] = {id=2752,name="On Iron Pauldrons",level=15,requiredLevel=15,faction="horde",expansion=0,zoneID=1637,mapID=85,description="Orokk sees the eagerness in your eyes, . Like a sponge you soak in the wisdom of the Omosh. Three lessons I shall teach! Return to the anvil, soak in the heat of the forge, create for Orokk four bronze battleaxes and four bronze warhammers . Only then will you learn of the iron pauldron.",objectivesText="Bring four Bronze Battleaxes and four Bronze Warhammers to Orokk Omosh in Orgrimmar. Progress: Show me your dedication, <race>.",rewardXP=2090,rewardItems={7978},starts={{npcID=7790}},ends={{npcID=7790}},coords={x=0.762,y=0.374,source="quest_giver",zoneID=1637},questType="standard"},
[2753] = {id=2753,name="Trampled Under Foot",level=15,requiredLevel=15,faction="horde",expansion=0,zoneID=1637,mapID=85,description="Only two more lessons Orokk will teach, . Your muscles ache, I know, but continue on for the Omosh! Bring to Orokk four green iron helms , four green iron bracers , and two green iron leggings - for this you learn and your enemies suffer!",objectivesText="Bring four Green Iron Helms , four Green Iron Bracers , and two Green Iron Leggings to Orokk Omosh in Orgrimmar. Progress: Their skulls will crack under the pressure of your boots!",rewardXP=2090,rewardItems={7981},starts={{npcID=7790}},ends={{npcID=7790}},coords={x=0.762,y=0.374,source="quest_giver",zoneID=1637},questType="standard"},
[2754] = {id=2754,name="Horns of Frenzy",level=15,requiredLevel=15,faction="horde",expansion=0,zoneID=1637,mapID=85,description="The final lesson Orokk teaches you, . To the sacred anvil and forge you return! Bring for Orokk two solid iron mauls , two silvered bronze boots , and two silvered bronze gauntlets . See the fear in their eyes as you approach!",objectivesText="Bring two Solid Iron Mauls , two Silvered Bronze Boots , and two Silvered Bronze Gauntlets to Orokk Omosh in Orgrimmar. Progress: Show the iron who is in charge, <name>!",rewardXP=2090,rewardItems={7980},starts={{npcID=7790}},ends={{npcID=7790}},coords={x=0.762,y=0.374,source="quest_giver",zoneID=1637},questType="standard"},
[2755] = {id=2755,name="Joys of Omosh",level=15,requiredLevel=15,faction="horde",expansion=0,zoneID=1637,mapID=85,description="Orokk is not crying, . Soot is in eye. There is one last Omosh family secret Orokk will teach you. Orokk will die happy, thanks to . Learn Omosh dance of joy and then you learn fist of iron!",objectivesText="Watch and learn the Omosh Dance of Joy.",rewardXP=260,rewardItems={7982},starts={{npcID=7790}},ends={{npcID=7790}},coords={x=0.762,y=0.374,source="quest_giver",zoneID=1637},questType="standard"},
[2945] = {id=2945,name="Grime-Encrusted Ring",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5495,mapID=87,description="You have uncovered what appears to be a ring from the corpse of one of the Dark Iron dwarves. It is difficult to tell what kind of ring it is, however; dirt and hardened residue cake the item completely, making wearing it impossible. You think you can make out the slight luster of precious metal and maybe even the glint of a gem under the residue. If you are going to make use of this ring, you are going to need to find something to get the hardened residue off of it.",objectivesText="Figure out a way to remove the grime from the Grime-Encrusted Ring . Progress: The gnomish contraption before you bears a plaque calling it \" The Sparklematic 5200 \". The gist of the machine, from reading the instructions below the plaque, is to scrub away dirt that an item might have. The machine has a coin slot, accepting three silver coins to start the process once the item is placed inside it. It would seem as though the grime-encrusted ring you found earlier is just the thing to try in this machine!",rewardXP=2125,rewardItems={9362},questType="dungeon"},
[2947] = {id=2947,name="Return of the Ring",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1537,mapID=87,description="Opening the box produced by the Sparklematic 5200 reveals what you had suspected - a shiny ring! Wearing the ring, you feel magic power surge through you body. Inside the band is a small but nonetheless discernable imprint of the seal of Ironforge. Next to that, three small initials are engraved: \"TdK\". This may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter. Keep the ring... or return it to this person. Decisions, decisions...",objectivesText="You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band. Progress: Hey, easy there partner - I'm a very important businessman! I am sure that the courier is just simply late with the delivery of the rent... wait... you're not my landlord. Well, of course you aren't - silly me! You've come to me seeking the finest jeweler in all of Ironforge, one who does NOT make CURSED items! Yes! Um... what do you need?",rewardXP=1415,rewardItems={9362},ends={{npcID=6826}},coords={mapID=87,source="quest_giver",x=0.43,y=0.0805},questType="dungeon"},
[2948] = {id=2948,name="Gnome Improvement",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1537,mapID=87,description="Listen , that ring is yours, sure... but I can make you a better one! That design, like I said, is really simple. I am a lot more skilled now, and for the mere fee of thirty silver coins I'll spruce it up for you! Well, a little more than thirty, actually... I'm in a tight spot right now; all my material stock is all dried up. If you bring me a bar of silver and a moss agate , I'll add a silver and agate lattice to the ring that will give it a little more pizzazz! Trust me!",objectivesText="Bring the Brilliant Gold Ring , a Silver Bar , a Moss Agate , and 30 silver coins to Talvash del Kissel in Ironforge . Progress: Do you have the materials I need? I wouldn't ask you for them if I wasn't down on my luck...",rewardXP=1415,rewardItems={9538},starts={{npcID=6826}},ends={{npcID=6826}},coords={x=0.36,y=0.04,source="quest_giver",zoneID=1537},questType="dungeon"},
[2949] = {id=2949,name="Return of the Ring",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,mapID=85,description="Opening the box produced by the Sparklematic 5200 reveals a shiny ring! Donning the ring, you feel magic power surge through your body. Inside the band is a small but nonetheless discernable imprint of the seal of Orgrimmar. Engraved letters are next to it, but only the first three stand out even after cleaning: \"NOG...\" This may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter. Keep the ring... or find \"NOG\" - decisions, decisions...",objectivesText="You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band. Progress: You'd think that we would find a way on our own to outdo those filthy little gnomes. I would even wager that they stole that rig from us to begin with! Bah, those greasy, grimy... erm, yes? You need something?",rewardXP=1415,rewardItems={9362},ends={{npcID=3412}},coords={mapID=85,source="quest_giver",x=0.565,y=0.5655},questType="dungeon"},
[2950] = {id=2950,name="Nogg's Ring Redo",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,mapID=85,description="No, no, no - I'm not all of the sudden saying that the ring is mine. I normally don't do this, but your information about the Dark Irons was very useful. I'll improve your ring for you, better than whomever made this simple little thing could have ever done. Probably some gnome... If you bring me a bar of silver, a moss agate , and thirty silver coins for my trouble, I'll add a silver and agate lattice to the ring that will strengthen the magic inside of it. Interested?",objectivesText="Bring the Brilliant Gold Ring , a Silver Bar , a Moss Agate , and 30 silver coins to Nogg in Orgrimmar. Progress: Do you have the materials I need? I can't improve on this design without everything I asked for.",rewardXP=1415,rewardItems={9588},starts={{npcID=3412}},ends={{npcID=3412}},coords={x=0.564,y=0.564,source="quest_giver",zoneID=1637},questType="dungeon"},
[2951] = {id=2951,name="The Sparklematic 5200!",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5495,description="This contraption stands out amongst the gnomes holding out against the madness outside the room. A small plaque on the device reads \" The Sparklematic 5200 \", followed by some text: \"Grime and residue ruining your sparklies? The Sparklematic 5200 puts the shine back in shine-tastic! Insert the item you wish to clean and deposit three silver coins in the coin slot. Give The Sparklematic 5200 a moment for operation, and voila! Your valuables will emerge clean and shiny!\"",objectivesText="Insert a Grime-Encrusted Item into the Sparklematic 5200 , and be sure to have three silver coins to start the machine. Progress: It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working. So long as both are present, the Sparklematic 5200 should work...",questType="dungeon"},
[2952] = {id=2952,name="The Sparklematic 5200!",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5495,mapID=87,rewardXP=1415,rewardItems={9363},questType="dungeon"},
[2953] = {id=2953,name="More Sparklematic Action",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5495,objectivesText="Progress: The Sparklematic 5200 is empty, awaiting a grime-encrusted object to clean and three silver coins to start!",rewardItems={9363},questType="dungeon"},
[3361] = {id=3361,name="A Refugee's Quandary",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=6176,mapID=27,description="I was on my way to join my fellow gnomes at Gnomeregan, but then it all went so horribly wrong! I left Anvilmar, bags packed and wading through waist-deep snow. Then we had this ridiculous earthquake, and I got all turned around. I ended up here, and what's worse: the trolls stole all my stuff! , I've obviously proven myself to be quite incompetent over the last day and a half. Would you mind infiltrating the troll camps southwest of here and returning my stuff to me?",objectivesText="Obtain Felix's Box , Felix's Chest and Felix's Bucket of Bolts . Progress: Once I get my tools, I'm outta here.",rewardGold=565,rewardXP=200,starts={{npcID=8416}},ends={{npcID=8416}},coords={x=0.318,y=0.744,source="quest_giver",zoneID=1},questType="standard"},
[3363] = {id=3363,name="Corrupted Songflower",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=361,objectivesText="Progress: You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.",starts={{npcID=164886}},ends={{npcID=164886}},coords={x=0.529,y=0.878,source="quest_giver",zoneID=361},questType="standard"},
[4021] = {id=4021,name="Counterattack!",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="The Horde commends your successes against the Kolkar, but the Kolkar themselves are maddened. I have reports that a contingent of Kolkar has traveled to the Barrens from their home in Desolace, to seek vengeance. My latest report was that, even now, they move against these bunkers, from the west! Face the Kolkar invaders, and end their threat in the Barrens. Kill them until their leader, Warlord Krom'zar, appears. Defeat him and bring me a piece of his banner as proof. We're counting on you, .",objectivesText="Kill Kolkar centaur until Krom'zar appears, then slay him and take a Piece of Krom'zar's Banner . Progress: Do you have the banner?",rewardGold=210000,rewardXP=925,rewardItems={59591,59592,59593},rewardChoices={59591,59592,59593},starts={{npcID=3389}},ends={{npcID=3389}},coords={x=0.378,y=0.552,source="quest_giver",zoneID=17},questType="group"},
[4083] = {id=4083,name="The Spectral Chalice",level=20,requiredLevel=20,faction="both",expansion=0,zoneID=1584,objectivesText="Progress: The spectral chalice floats in the air, slowing rising and falling... as if to the beat of a dying heart.",rewardXP=2765,questType="dungeon"},
[4103] = {id=4103,name="Salve via Hunting",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=361,objectivesText="Progress: Possessing a Cenarion Beacon allows one to sea a corrupted soul shard on those tainted beasts that are put down for the greater good. I grind shards into a usable reagent that goes into making Cenarion plant salve . We will use that salve to turn corrupted plants into healthy ones again. In exchange for these shards, I will give you some Cenarion plant salves I have already prepared.",rewardItems={11516},starts={{npcID=9528}},ends={{npcID=9528}},questType="standard"},
[4104] = {id=4104,name="Salve via Mining",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=361,objectivesText="Progress: If you possess a Cenarion beacon while mining in Felwood , you will be able to see tainted vitriol that corrupts a vein of raw metal. I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve . You will then use that salve on plants you find in the wild that need saving. If you have collected any tainted vitriol , I'll give you some Cenarion plant salve I have already prepared.",rewardItems={11516},starts={{npcID=9528}},ends={{npcID=9528}},questType="standard"},
[4105] = {id=4105,name="Salve via Gathering",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=361,objectivesText="Progress: A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood 's corruption. My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve . When you gather herbs in Felwood , you should encounter the fel creep so long as you have the beacon. In exchange for what you bring to me, I will give you pre-made Cenarion plant salve .",rewardItems={11516},starts={{npcID=9528}},ends={{npcID=9528}},questType="standard"},
[4106] = {id=4106,name="Salve via Skinning",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=361,objectivesText="Progress: A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood . I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve . When you skin your kills here in Felwood , be sure to have a beacon on you! When you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.",rewardItems={11516},starts={{npcID=9528}},ends={{npcID=9528}},questType="standard"},
[4107] = {id=4107,name="Salve via Disenchanting",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=361,objectivesText="Progress: The power of a disenchanted magical item is felt by the essence it creates. I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve . You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work. I just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves . The essence is extremely potent - a little definitely goes a long way!",rewardItems={11516},starts={{npcID=9528}},ends={{npcID=9528}},questType="standard"},
[4108] = {id=4108,name="Salve via Hunting",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=361,objectivesText="Progress: Possessing a Cenarion Beacon allows one to sea a corrupted soul shard on those tainted beasts that are put down for the greater good. I grind shards into a usable reagent that goes into making Cenarion plant salve . We will use that salve to turn corrupted plants into healthy ones again. In exchange for these shards, I will give you some Cenarion plant salves I have already prepared.",rewardItems={11516},starts={{npcID=9529}},ends={{npcID=9529}},questType="standard"},
