[4117] = {id=4117,name="Corrupted Whipper Root",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=361,objectivesText="Progress: You have found a sickly, corrupted version of what appears to be a whipper root plant. The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant. It desperately needs some sort of attention if it is to be turned back to normal.",rewardItems={11951},starts={{npcID=164888}},ends={{npcID=164888}},coords={x=0.402,y=0.852,source="quest_giver",zoneID=361},questType="standard"},
[4119] = {id=4119,name="Corrupted Night Dragon",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=361,objectivesText="Progress: You have found a sickly, corrupted version of what appears to be a night dragon plant. The fruits that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.",rewardItems={11952},starts={{npcID=164885}},ends={{npcID=164885}},coords={x=0.351,y=0.59,source="quest_giver",zoneID=361},questType="standard"},
[4295] = {id=4295,name="Rocknot's Ale",level=20,requiredLevel=20,faction="both",expansion=0,zoneID=1584,objectivesText="Progress: Oh, ale! I would kill for some Dark Iron ale!! Quick, I'm getting sober! I know this because sobriety blurs my vision... and it's making you look like the <race> I slew last week!",starts={{npcID=9503}},questType="dungeon"},
[4443] = {id=4443,name="Corrupted Whipper Root",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=361,objectivesText="Progress: You have found a sickly, corrupted version of what appears to be a whipper root plant. The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant. It desperately needs some sort of attention if it is to be turned back to normal.",rewardItems={11951},starts={{npcID=164888}},ends={{npcID=164888}},coords={x=0.402,y=0.852,source="quest_giver",zoneID=361},questType="standard"},
[4447] = {id=4447,name="Corrupted Night Dragon",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=361,objectivesText="Progress: You have found a sickly, corrupted version of what appears to be a night dragon plant. The fruits that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.",rewardItems={11952},starts={{npcID=164885}},ends={{npcID=164885}},coords={x=0.351,y=0.59,source="quest_giver",zoneID=361},questType="standard"},
[4512] = {id=4512,name="A Little Slime Goes a Long Way",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=1537,mapID=87,description="But the thing I've studied most is ooze. I know it sounds odd, but they're all over! I helped a lady in Menethil find her bag not too long ago--it was eaten by oozes. I've seen members of the Royal Apothecary Society from Undercity collecting samples of the stuff. I want to know why! Where does it come from? I've heard of more in Felwood. What I need are samples of the oozes there so I can further my research. I'll give you containers, you use them to collect a sample from the deceased creatures.",objectivesText="Bring 6 Filled Cursed Ooze Jars and 6 Filled Tainted Ooze Jars to Laris Geardawdle in Ironforge . Progress: Some of the experiments I've done are fascinating. I think with a little more work, I'll be able to figure out the nature of these creatures and how they play into how life developed on Azeroth... if they even have anything to do with it to begin with. One of my biggest theories that isn't well liked is the idea that oozes and slimes are tied to the creation of this planet... almost like they're a secretion of it. But I can't prove or disprove it until I get more samples.",rewardGold=53500,rewardXP=2615,starts={{npcID=9616}},ends={{npcID=9616}},coords={x=0.754,y=0.234,source="quest_giver",zoneID=1537},questType="standard"},
[4513] = {id=4513,name="A Little Slime Goes a Long Way",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=1537,mapID=87,description="I'm going to need more samples, . But--and I don't know how to put this--they have to be pure samples. I know, I know. \"What does 'pure' mean, Laris?\" I'm not sure. I do know that these are corrupt... just like Felwood. Which is what makes my realization so important. The oozes seem to adapt... to take on the aspects of the area they're in. I'll need to find samples that haven't been polluted. But where? Where?! Bah! , take these containers just in case you find any on your own.",objectivesText="Bring 10 Filled Pure Sample Jars to Laris Geardawdle in Ironforge . If you have trouble finding them, perhaps try to get more clues from Laris. Progress: So many things to consider. But what does it mean? And how does it affect the lives of the people of Azeroth?",rewardGold=52500,rewardXP=2615,rewardItems={12050,12051},rewardChoices={12050,12051},starts={{npcID=9616}},ends={{npcID=9616}},coords={x=0.754,y=0.234,source="quest_giver",zoneID=1537},questType="standard"},
[4601] = {id=4601,name="The Sparklematic 5200!",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5495,description="This contraption stands out amongst the gnomes holding out against the madness outside the room. A small plaque on the device reads \" The Sparklematic 5200 \", followed by some text: \"Grime and residue ruining your sparklies? The Sparklematic 5200 puts the shine back in shine-tastic! Insert the item you wish to clean and deposit three silver coins in the coin slot. Give The Sparklematic 5200 a moment for operation, and voila! Your valuables will emerge clean and shiny!\"",objectivesText="Insert a Grime-Encrusted Item into the Sparklematic 5200 , and be sure to have three silver coins to start the machine. Progress: It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working. So long as both are present, the Sparklematic 5200 should work...",questType="dungeon"},
[4602] = {id=4602,name="The Sparklematic 5200!",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5495,description="This contraption stands out amongst the gnomes holding out against the madness outside the room. A small plaque on the device reads \" The Sparklematic 5200 \", followed by some text: \"Grime and residue ruining your sparklies? The Sparklematic 5200 puts the shine back in shine-tastic! Insert the item you wish to clean and deposit three silver coins in the coin slot. Give The Sparklematic 5200 a moment for operation, and voila! Your valuables will emerge clean and shiny!\"",objectivesText="Insert a Grime-Encrusted Item into the Sparklematic 5200 , and be sure to have three silver coins to start the machine. Progress: It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working. So long as both are present, the Sparklematic 5200 should work...",questType="dungeon"},
