[4621] = {id=4621,name="Avast Ye, Admiral!",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5287,mapID=210,description="Listen close, sea dawg... the powers of Booty Bay is what keeps us Bloodsail from sailing wheres we like and taking whats we want as rights o' plunder. Were ye to put a knife to Fleet Master Seahorn , we'd ne'er run afoul of a Booty Bay 's vessel. Were ye to put a knife to Baron Revilgaz , we'd ne'er face the law on their terms. If ye are to be an honorary admiral amongst us - yes, ADMIRAL, you'll puts a knife to both of 'em as I've says. Go now , and return to me once ye does the deeds.",objectivesText="Slay Fleet Master Seahorn and Baron Revilgaz of Booty Bay , and then return to Fleet Master Firallon aboard the Crimson Veil off the coast of Stranglethorn Vale. Progress: Yer back already, ya blasted tar! Haves ye done as I've ordered? Fail us, and ye will be walkin' the plank. Arrrrr...",rewardXP=2125,rewardItems={12185},rewardChoices={12185},starts={{npcID=2546}},ends={{npcID=2546}},coords={x=0.466,y=0.952,source="quest_giver",zoneID=5287},questType="standard"},
[4785] = {id=4785,name="Fine Gold Thread",level=15,requiredLevel=15,faction="none",expansion=0,rewardItems={12293},starts={{npcID=2670}},ends={{npcID=2670}},questType="standard"},
[5041] = {id=5041,name="Supplies for the Crossroads",level=5,requiredLevel=5,faction="horde",expansion=0,zoneID=17,mapID=10,description="Whatever has happened in Southern Barrens is causing some of the quilboar tribes to flee our direction. The displaced Razormane in particular grow desperate, and their attacks grow bolder. I've lost two caravans this week alone! Our warriors at the Crossroads desperately need those supplies, and I'm not about to let the quilboar grow fat off of their misdeeds. Find the missing supply crates and bring them to me. I'd search the quilboar hovel south of here, along the river.",objectivesText="Collect 5 Crossroads Supply Crates from inside the Razormane cave. Progress: How goes your search for the supplies, <name>? I trust the quilboar fall under your strength easily.",rewardGold=105000,rewardXP=740,starts={{npcID=34258}},ends={{npcID=3429},{npcID=34258}},coords={x=0.674,y=0.388,source="quest_giver",zoneID=17},questType="standard"},
[5421] = {id=5421,name="Fish in a Bucket",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=405,mapID=66,description="I'll reward anyone who makes my life a bit easier... I enjoy doing as little as possible, mon! Below the docks here in Shadowprey Village, I've many shellfish traps. If you're kind enough to do my work and collect me my shellfish , then I'll reward you with something you want... get my drift mon?",objectivesText="Jinar'Zillen wants you to collect 5 Shellfish from the traps near Shadowprey Village. Progress: Ya got mah shellfish , mon?",rewardGold=105000,rewardXP=1415,rewardItems={13546},starts={{npcID=11317}},ends={{npcID=11317}},coords={x=0.224,y=0.73,source="quest_giver",zoneID=405},questType="standard"},
[5501] = {id=5501,name="Bone Collector",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=405,mapID=66,description="We're sitting on a goldmine here, I tell you - a goldmine! Kodo bones will change the world forever... I have customers making furniture, music instruments, and even blasting powder out of them. There's a caravan that comes by and picks up my Kodo bones and then sells them at Shadowprey Village. If you can travel to the kodo graveyard south of here and bring me ten Kodo bones , I'll give you something in return. Is it a deal?",objectivesText="Bring 10 Kodo Bones from the Kodo Graveyard to Bibbly F'utzbuckle at Kormek's Hut. Progress: Do you have the bones? The caravan will be here any moment. I need just ten more kodo bones to reach a career high. A career high, I tell you!",rewardXP=1060,rewardItems={15690},starts={{npcID=11438}},ends={{npcID=11438}},coords={x=0.622,y=0.388,source="quest_giver",zoneID=405},questType="standard"},
[5502] = {id=5502,name="A Warden of the Horde",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=6738,mapID=85,description="You have been so very kind to me, . I never dreamed that I'd have so much fun during Children's Week. Thank you. I wish all the orphans were lucky enough to get to see all the stuff we did. Do you think we find Blax Bottlerocket again and get a foam sword rack from him? I think he's still pushing that cart up and down the main road in the Drag. That way, everyone else at the orphanage could do something fun too! After that, it'll be time for me to go home.",objectivesText="Purchase a Foam Sword Rack from Blax Bottlerocket in Orgrimmar's Drag. Then return your ward to the Orgrimmar orphanage by speaking with Orphan Matron Battlewail in The Drag. Progress: It is a pleasure to see you again, <name>. Have you attended to the duties you've volunteered for during Children's Week?",rewardXP=355,rewardItems={23002,23007,23015,23022,66073,116202,241215},rewardChoices={23007,23015,23002,66073,116202,23022,241215},starts={{npcID=14444}},ends={{npcID=14451},{npcID=51989}},questType="standard"},
[5545] = {id=5545,name="A Bundle of Trouble",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=12,mapID=37,description="I've got a real problem on my hands. I have a deadline looming for an order of lumber, and I'm running out of time. The wolves and bears north of here have chased my workers away from the bundles of wood that they've already chopped. I've already talked to Deputy Rainer about clearing the animals, but I need someone to go collect the wood for me. If you could collect eight bundles of wood for me I might just make my deadline.",objectivesText="Bring 8 Bundles of Wood to Raelen at the Eastvale Logging Camp. Progress: That deadline isn't getting any further away, <class>. Please hurry and collect those bundles of wood.",rewardGold=105000,rewardXP=200,starts={{npcID=10616}},ends={{npcID=10616}},coords={x=0.814,y=0.662,source="quest_giver",zoneID=12},questType="standard"},
[5561] = {id=5561,name="Kodo Roundup",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=405,mapID=66,description="Bibbly thinks he is the only goblin in Desolace who knows how to make money. Well, the only caravan brave enough to travel these parts relies on me. Ever since I learned how to rejuvenate and control aged kodos with my kodo kombobulator , the caravan owner Cork, Rigger, and I entered a partnership. Take the kombobulator and use it on any ancient or aged kodos; it will jolt the beast into a tamed kodo and force it to follow you. Once you have a kodo tamed, bring it back to me.",objectivesText="Bring 3 Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp. Progress: The caravan will be here shortly; do you have the newly tamed kodos I was asking for?",rewardXP=1060,rewardItems={15697,15698},starts={{npcID=11596}},ends={{npcID=11596}},coords={x=0.608,y=0.618,source="quest_giver",zoneID=405},questType="standard"},
[5581] = {id=5581,name="Portals of the Legion",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=405,mapID=66,description="Here it is - the Hand of Iruxos . Got it from one of the Burning Blade leaders myself. You must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do. With the demon threat increasing we must close these portals to stem the tide of demons to this world.",objectivesText="Banish 6 Portals at Mannoroc Coven and return to Felgur Twocuts at Ghost Walker Post.",rewardGold=105000,rewardXP=1770,rewardItems={16794,16873,55939,55940,55941,131233},rewardChoices={55940,55941,55939,131233},starts={{npcID=5395}},ends={{npcID=5395},{npcID=11624}},coords={x=0.562,y=0.594,source="quest_giver",zoneID=405},questType="standard"},
[5713] = {id=5713,name="One Shot. One Kill.",level=5,requiredLevel=5,faction="alliance",expansion=0,zoneID=331,mapID=62,description="I was traveling to Lor'danel with an important message when I was attacked by the furbolg Marosh and his trackers. During the attack I was poisoned, leaving me barely able to stand. I can make an antidote, but it will take time before it is ready. I would ask that you defend me until I can apply the antidote. I will aid you with my bow as best I can. Should we survive, I will be able to deliver my message to Lor'danel, while you speak with Onaeya at Maestra's Post to inform her of this incident.",objectivesText="Protect Sentinel Aynasha , then speak with Onaeya at Maestra's Post in Ashenvale.",rewardGold=210000,rewardXP=740,starts={{npcID=11711}},ends={{npcID=11806}},coords={x=0.476,y=0.888,source="quest_giver",zoneID=148},questType="standard"},
[5892] = {id=5892,name="Irondeep Supplies",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,description="Before the fighting started, we stored supplies for Dun Baldar in the Irondeep mine. The troggs that surfaced there weren't much of a problem when we had spare troops to guard the mine, but now that we're fighting with the Horde we can't maintain control of Irondeep. We need the supplies in Irondeep, . Enter the mine and bring me a load of them.",objectivesText="Bring 10 Irondeep Supplies to the Alliance Quartermaster in Dun Baldar. Progress: Do you have the supplies, <name>? We can never have enough!",rewardGold=170800,starts={{npcID=12096}},ends={{npcID=12096}},questType="pvp"},
[5893] = {id=5893,name="Coldtooth Supplies",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,description="The Coldtooth mine to the north was once an ideal place to store extra supplies, but now that the fighting with the Stormpikes grows fierce, we do not always have the spare warriors to station at the mine and protect it. And so, control of the mine often falls to the Alliance, or to underground denizens... But we still need our supplies, ! Go to the Coldtooth mine and bring me a load of them. And be wary of enemies as you go; the tides of battle shift quickly in that place...",objectivesText="Bring 10 Coldtooth Supplies to the Horde Quartermaster in Frostwolf Keep. Progress: Have you been to the Coldtooth mine, <name>? Do you have the supplies I asked for?",rewardGold=170800,starts={{npcID=12097}},ends={{npcID=12097}},coords={x=0.466,y=0.84,source="quest_giver",zoneID=2597},questType="pvp"},
[6031] = {id=6031,name="Runecloth",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=361,mapID=77,description="In Timbermaw, we are content. We do not like strangers. This is good for us, but it is bad for trade. Not long ago, a rare night elf friend came to Timbermaw and she wore a runecloth cloak. runecloth is rare among us, but the cloak was so fine my people want me to make more runecloth clothing. Will you bring me runecloth ? If you bring me enough, then I will give you something in trade.",objectivesText="Bring 30 Runecloth to Meilosh in Timbermaw Hold. Progress: Do you have the runecloth ? My people are eager for more items of runecloth !",rewardXP=2090,rewardItems={15822,15823},rewardChoices={15822,15823},starts={{npcID=11557}},ends={{npcID=11557}},coords={x=0.648,y=0.052,source="quest_giver",zoneID=361},questType="standard"},
[6032] = {id=6032,name="Sacred Cloth",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=361,mapID=77,description="Although the people of Timbermaw delight in the feel of runecloth, it is not sacred to us. But mooncloth is sacred. Bring me a small supply of this holy cloth, and I will teach you a secret fashioning technique.",objectivesText="Bring 2 Mooncloth to Meilosh in Timbermaw Hold. Progress: Have you brought the mooncloth , <name>?",rewardXP=2090,starts={{npcID=11557}},ends={{npcID=11557}},coords={x=0.648,y=0.052,source="quest_giver",zoneID=361},questType="standard"},
[6132] = {id=6132,name="Get Me Out of Here!",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=405,mapID=66,description="Get me out of here! I came up to the Valley of Spears to talk to the Maraudines. I thought I could do a little business with them... but they don't want to talk! I think they want to eat me! Get me out of here and my brother Hornizz will pay you big! He's at our camp next to the kodo graveyard, to the east. Let's hurry, . Not two minutes ago I heard some centaurs talking about getting wood for their cookpot...",objectivesText="Escort Melizza Brimbuzzle .",rewardGold=53500,rewardXP=1060,starts={{npcID=12277}},ends={{npcID=6019}},coords={x=0.338,y=0.534,source="quest_giver",zoneID=405},questType="standard"},
[6134] = {id=6134,name="Ghost-o-plasm Round Up",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=405,mapID=66,description="There's a valley to the southeast, the Valley of Bones, haunted by Magram ghosts. Sounds scary, doesn't it? Well think how scary it is to the Magram! If we captured ghost energy from that place, I bet it'd be worth plenty to those centaurs. Here, take this crate of ghost magnets . If you place one between the two big skeletons in the valley, the Dead Goliaths, then ghosts will wander to it. Distance yourself, take out the ghosts and get their ghost-o-plasm --that's what we'll sell to the Magram.",objectivesText="Collect 8 Ghost-o-plasms . Progress: Where's my ghost-o-plasm , <name>?",rewardGold=105000,rewardXP=1060,rewardItems={15864,15865},rewardChoices={15864,15865},starts={{npcID=6019}},ends={{npcID=6019}},coords={x=0.478,y=0.618,source="quest_giver",zoneID=405},questType="standard"},
[6321] = {id=6321,name="Supplying Brill",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=85,mapID=18,description="Executor Zygand asked me to take stock of our equipment here in Brill. With the Scourge, and worse, lurking in the woods, he doesn't want the Deathguards to lack gear they might need. I found that we are, in general, well stocked, but we do need more weapons to replace those lost in the field. Here is a requisition order of what is needed, for the weapon dealer Gordon Wendham in the Undercity. Take the order to Bat Handler Anette and speak with her about transport to the Undercity.",objectivesText="Bring Morris's Order to Bat Handler Anette. Progress: You appear to be on official business...",rewardXP=50,starts={{npcID=1745}},ends={{npcID=43124}},coords={x=0.602,y=0.524,source="quest_giver",zoneID=85},questType="standard"},
[6322] = {id=6322,name="Michael Garrett",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1497,mapID=90,description="I have placed Brill's supplies into this crate. If you have already visited Brill and spoken with their bat master, then you may ride a bat back to her. Speak with the Undercity's bat master, Michael Garrett . He can provide you with a bat to Brill.",objectivesText="Bring Gordon's Crate to Michael Garrett . Progress: If you must travel a long distance, then a bat is your best option.",rewardXP=50,starts={{npcID=4556}},ends={{npcID=4551}},coords={x=0.618,y=0.42,source="quest_giver",zoneID=1497},questType="standard"},
[6323] = {id=6323,name="Ride to the Undercity",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1497,mapID=18,description="One of my bats can take you to the Undercity. Normally these flights require a small fee, but the flight to Undercity is complimentary for a like you. Speak with me again when you are ready so that we may arrange your transport. You will find Gordon Wendham in the Trade Quarter of the Undercity. That is the same quarter where my bat will land.",objectivesText="Request a bat ride to the Undercity from the bat master Bat Handler Anette, then take Morris's Order to Gordon Wendham in the Undercity. Progress: I keep my weapons in top condition. They are cleaned and ready for use.",rewardGold=52500,rewardXP=100,starts={{npcID=43124}},ends={{npcID=4556}},coords={x=0.588,y=0.518,source="quest_giver",zoneID=85},questType="standard"},
[6324] = {id=6324,name="Return to Morris",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=85,mapID=90,description="The bat master in Brill is Bat Handler Anette. If you have already met her, then I can give you a bat to fly back to her. Our bats will always fly to the Undercity, but to travel to more remote locales their rider must first visit the area and speak with its bat master. You have met Anette in Brill, so you may now fly bats there. Speak with me again when you are ready.",objectivesText="Buy a bat ride to Brill from the bat master Michael Garrett , then bring Gordon's Crate to Deathguard Morris in Brill. Progress: <name>, you return. Do you have our supplies from the Undercity?",rewardGold=105000,rewardXP=200,starts={{npcID=4551}},ends={{npcID=1745}},coords={x=0.63,y=0.482,source="quest_giver",zoneID=1497},questType="standard"},
[6341] = {id=6341,name="To Darnassus",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1657,mapID=57,description="Everyone in Dolanaar is so proud of Sister Aquinne . I'm certain she'll be pleased to receive this thoughtful gift from Nyoma. When you're ready to travel to Darnassus, just speak to me again and for a few coins, you can hire a hippogryph to take you there. I'm told Sister Aquinne enjoys the solitude of a small plaza just south of the hippogryph master in Darnassus. Look for her there after you arrive.",objectivesText="Speak to Fidelio to purchase a flight to Darnassus, then bring the Dolanaar Recipe Book to Sister Aquinne in Darnassus. Progress: How may I help you?",rewardXP=50,starts={{npcID=40553}},ends={{npcID=7316}},coords={x=0.554,y=0.504,source="quest_giver",zoneID=141},questType="standard"},
[6342] = {id=6342,name="An Unexpected Gift",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1657,mapID=89,description="This is wonderful! It's just the kind of thing I need to remind me of home while I continue my studies in the Temple of the Moon. I'll try out one of the recipes tonight. I can't wait! Would you take this short note of thanks back to Nyoma? You can hire a hippogryph to take you back to Dolanaar. Just visit our hippogryph master, Leora , when you're ready to leave. She'll help you get a ride back to Dolanaar.",objectivesText="Bring Sister Aquinne's Note to Leora , the hippogryph master in Darnassus. Progress: Are you ready to return to Dolanaar?",rewardXP=100,starts={{npcID=7316}},ends={{npcID=40552}},coords={x=0.362,y=0.532,source="quest_giver",zoneID=1657},questType="standard"},
[6343] = {id=6343,name="Return to Nyoma",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=89,description="It will be easy to get you a flight back to Dolanaar. Since you already know Fidelio in Dolanaar, you'll be able to fly back there without any problems. Whenever you arrive in a new town, you should remember to speak to the flight master so that you can fly to and from the new location. Speak with me when you're ready to hire a hippogryph to return to Dolanaar.",objectivesText="Speak to Leora to hire a hippogryph to take you back to Dolanaar. Once you've arrived in Dolanaar, take Sister Aquinne's Note to Nyoma . Progress: <name>, you're back from Darnassus?",rewardGold=40125,rewardXP=200,starts={{npcID=40552}},ends={{npcID=4265}},coords={x=0.366,y=0.48,source="quest_giver",zoneID=1657},questType="standard"},
[6344] = {id=6344,name="Reminders of Home",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="A friend of mine, Sister Aquinne, is training to be a priestess of the moon in Darnassus. She left Dolanaar to study in the temple last year. Her letters say she is doing well and learning much, but she misses home and her old friends. I've put together a book of her favorite recipes from Dolanaar. If you have time, would you take them to her in Darnassus? You can rent a hippogryph from Fidelio . He's in the center of town, just across from the inn.",objectivesText="Bring the Dolanaar Recipe Book to Fidelio in Dolanaar. Progress: How can I help you?",rewardXP=50,starts={{npcID=4265}},ends={{npcID=40553}},coords={x=0.566,y=0.534,source="quest_giver",zoneID=141},questType="standard"},
[6361] = {id=6361,name="A Bundle of Hides",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=215,mapID=7,description="I have a bundle of hides from the animals of Mulgore , and must get them to Thunder Bluff. A colleague there, Ahanu, will use the hides to create leather goods. Will you take the hides to him for me? The quickest way to Thunder Bluff is on the back of a wind rider. Bring the bundle of hides to Tak , our wind rider master in Bloodhoof Village, and speak to him about transport to Thunder Bluff.",objectivesText="Bring the Bundle of Hides to the wind rider master Tak in Bloodhoof Village. Progress: Are you here for a wind rider? You have something to transport?",rewardXP=50,starts={{npcID=3079}},ends={{npcID=40809}},coords={x=0.46,y=0.582,source="quest_giver",zoneID=215},questType="standard"},
[6362] = {id=6362,name="Ride to Thunder Bluff",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1638,mapID=7,description="For a small fee, I will give you a wind rider to Thunder Bluff. There's no faster way to the city! If that is acceptable, speak to me again when you are ready to go. If you're taking those hides to Ahanu , then I think he's at Hewa's Armory, at the base of the wind rider tower in Thunder Bluff. And that's right where you'll land!",objectivesText="Buy a wind rider to Thunder Bluff from the wind rider master Tak , then bring the Bundle of Hides to Ahanu in Thunder Bluff. Progress: There is dust on your shoulders that must be from Mulgore . You have spoken with my friend Varg?",rewardGold=52500,rewardXP=100,starts={{npcID=40809}},ends={{npcID=8359}},coords={x=0.474,y=0.586,source="quest_giver",zoneID=215},questType="standard"},
[6363] = {id=6363,name="Tal the Wind Rider Master",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1638,mapID=88,description="I have prepared leather goods for Varg to sell at the Bloodhoof Village. Will you bring them to him? If you have already been to Bloodhoof Village and spoken to their wind rider master, then you can fly one of our Thunder Bluff wind riders back to him. Take the leather goods to Tal , our wind rider master in Thunder Bluff, and speak with him to arrange transport to Bloodhoof Village.",objectivesText="Bring Ahanu's Leather Goods to Tal in Thunder Bluff. Progress: Greetings, <class>. What can I do for you?",rewardXP=50,starts={{npcID=8359}},ends={{npcID=2995}},coords={x=0.454,y=0.558,source="quest_giver",zoneID=1638},questType="standard"},
[6364] = {id=6364,name="Return to Varg",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=215,mapID=88,description="In order to fly to a town, you must have already been there and spoken with the wind rider master of that town. You have been to the Bloodhoof Village and spoken to their wind rider master Tak, so for a small fee you can take a wind rider to him from here. Speak with me again when you are ready. Once at Bloodhoof Village, you can then deliver the leather goods to Varg Windwhisper .",objectivesText="Buy a wind rider to Bloodhoof Village from the wind rider master Tal , then bring Ahanu's Leather Goods to Varg Windwhisper . Progress: <name>, you are back from Thunder Bluff? Did you deliver the hides to Ahanu?",rewardGold=800,rewardXP=200,starts={{npcID=2995}},ends={{npcID=3079}},coords={x=0.468,y=0.498,source="quest_giver",zoneID=1638},questType="standard"},
[6384] = {id=6384,name="Ride to Orgrimmar",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1637,mapID=10,description="For just a few coins I will have a wind rider bring you to Orgrimmar. When you get there, you can take Grimtak's meats to Gryshka. Her inn is in the Valley of Strength. Speak with me again when you are ready for the journey.",objectivesText="Buy a wind rider to Orgrimmar from the wind rider master Burok , then bring Grimtak's Meats to Gryshka in Orgrimmar. Progress: Something smells good! You don't have raw meat on you, do you?",rewardGold=52500,rewardXP=100,starts={{npcID=3615},{npcID=41140}},ends={{npcID=6929}},coords={x=0.486,y=0.586,source="quest_giver",zoneID=17},questType="standard"},
[6385] = {id=6385,name="Doras the Wind Rider Master",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1637,mapID=85,description="I've written a letter of thanks to Grimtak. Will you deliver it for me? If you've already been to the Razor Hill and spoken with their wind rider master, then you can fly a wind rider back there. Take my letter to Doras , the wind rider master of Orgrimmar, and speak with him about transport to Razor Hill.",objectivesText="Bring Gryshka's Letter to Doras in Orgrimmar. Progress: Do you need one of my wind riders?",rewardXP=50,starts={{npcID=6929}},ends={{npcID=3310}},coords={x=0.534,y=0.788,source="quest_giver",zoneID=1637},questType="standard"},
[6386] = {id=6386,name="Return to Razor Hill",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=14,mapID=85,description="My wind riders are trained to fly to many different places, as long as you have already been to that place and spoken with the wind rider master there. You have been to Razor Hill and spoken to their wind rider master Burok, so now you can fly directly to him from here. Once you're at Razor Hill, you can deliver Gryshka's letter to Grimtak . Speak with me when you are ready to go.",objectivesText="Buy a wind rider to Razor Hill from the wind rider master Doras , then bring Gryshka's Letter to Grimtak at Razor Hill. Progress: Have you returned from Orgrimmar? Did Gryshka like the meat I sent her?",rewardGold=105000,rewardXP=200,starts={{npcID=3310}},ends={{npcID=3489},{npcID=3881}},coords={x=0.494,y=0.592,source="quest_giver",zoneID=1637},questType="standard"},
[6387] = {id=6387,name="Honor Students",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1,mapID=27,description="I see a lot of young dwarves at my door, eager to learn the trade of cooking. And if there's one thing a cook needs more than anything, it's a cleaver! I have a list of students who scored high in their lessons and earned an honorary cleaver. Take my list to Golnir Bouldertoe in Ironforge. He'll get the cleavers ready. The fastest way to Ironforge is on a gryphon, so bring the list to our gryphon master, Brolan Galebeard , and speak with him about transport to Ironforge.",objectivesText="Bring Gremlock's List to Brolan Galebeard in Kharanos. Progress: Have you had your fill of Kharanos so soon? Are you ready to leave for another city?",rewardXP=150,starts={{npcID=1699}},ends={{npcID=43701}},coords={x=0.546,y=0.506,source="quest_giver",zoneID=1},questType="standard"},
[6388] = {id=6388,name="Gryth Thurden",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1537,mapID=87,description="Here are the honorary cleavers for Gremlock's students. If you've already been to Kharanos, then you should fly a gryphon back there! Take the cleavers to our gryphon master, Gryth Thurden , and speak with him about a ride back to Kharanos.",objectivesText="Bring the Honorary Cleavers to Gryth Thurden in Ironforge. Progress: You look like you have somewhere to go. Need one of my gryphons?",rewardXP=150,starts={{npcID=4256}},ends={{npcID=1573}},coords={x=0.51,y=0.262,source="quest_giver",zoneID=1537},questType="standard"},
[6391] = {id=6391,name="Ride to Ironforge",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1537,mapID=27,description="For just a few coins, one of my gryphons will take you to Ironforge. From there, deliver Gremlock's list to Golnir Bouldertoe . You'll find him in the Deep Mountain Mining Guild. That's in the Great Forge District of Ironforge, which is right where my gryphon will drop you off! Speak to me again when you're ready for the journey.",objectivesText="Buy a gryphon to Ironforge from the gryphon master Brolan Galebeard , then bring Gremlock's List to Golnir Bouldertoe in Ironforge. Progress: What can I do for you, sir?",rewardGold=735,rewardXP=150,starts={{npcID=43701}},ends={{npcID=4256}},coords={x=0.538,y=0.526,source="quest_giver",zoneID=1},questType="standard"},
[6392] = {id=6392,name="Return to Gremlock",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1,mapID=87,description="For a small fee you can buy a gryphon ride to Kharanos... as long as you've already been there. Gryphons will only fly you to places you've already been, so be sure to speak with every gryphon master you see so you can fly to him later. You've already been to Brolan, the gryphon master of Kharanos, so now you can return to him. And once in Kharanos, you can deliver the cleavers to Gremlock Pilsnor . Speak with me when you're ready to go.",objectivesText="Buy a gryphon to Kharanos from the gryphon master Gryth Thurden , then bring the Honorary Cleavers to Gremlock Pilsnor in Kharanos. Progress: Ah, <name>. Have you returned from Ironforge?",rewardGold=105000,rewardXP=200,starts={{npcID=1573}},ends={{npcID=1699}},coords={x=0.558,y=0.478,source="quest_giver",zoneID=1537},questType="standard"},
[6441] = {id=6441,name="Satyr Horns",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,mapID=63,description="Heya! I've been traveling through Ashenvale , heading towards Ratchet, and decided to make a stop here at Splintertree. I'm always looking for an opportunity, and it seems that satyr horns are in high demand in Ratchet these days. After asking around here, it seems that the satyrs in Night Run, Satyrnaar, and Xavian all have the type of horns I am looking for. I'm no match for those satyrs... but you look like you might be! Tell you what, you collect the horns for me and I'll make it worth your time.",objectivesText="Collect 16 Satyr Horns for Pixel in Splintertree Post. Progress: I hope you can be quick about getting those horns, <name>. I'm heading back to Ratchet soon!",rewardGold=105000,rewardXP=1010,starts={{npcID=12724}},ends={{npcID=12724}},coords={x=0.738,y=0.624,source="quest_giver",zoneID=331},questType="standard"},
[6442] = {id=6442,name="Naga at the Zoram Strand",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=719,mapID=63,description="There is evil lurking here along the coast, . It is the resting place of the doomed city of Zoram, long destroyed and submerged beneath the seas. Lost, and nearly forgotten. Now, the naga have returned, and for what reason we do not know. But reason matters little; we must defend the land we have worked so hard to claim as our own. Return to me with 20 of their heads! Throw the naga back to the depths!",objectivesText="Bring 20 Wrathtail Heads to Marukai along the Zoram Strand. Progress: The naga increase in numbers, <name>. Please complete this task for me.",rewardXP=1010,starts={{npcID=12719}},ends={{npcID=12719}},coords={x=0.126,y=0.352,source="quest_giver",zoneID=331},questType="standard"},
[6462] = {id=6462,name="Troll Charm",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=1,mapID=63,description="My kinfolk were traveling here with many sacred troll charms , but the Thistlefur furbolgs attacked and killed them before they reached Zoram'gar! Those vile furbolgs! I miss my brothers and sisters who were killed, but we will meet again in the afterlife. However, their troll charms hold great value in this world. It is an outrage that the furbolgs have them! , you must retrieve the charms! They are in chests in Thistlefur Hold, a cave at the end of Thistlefur Village, north of Astranaar.",objectivesText="Bring 8 Troll Charms to Mitsuwa at Hellscream's Watch. Progress: Did you find the charms, <name>? Every moment the furbolgs possess those sacred items, my blood boils with rage!",rewardGold=105000,rewardXP=1010,starts={{npcID=12721}},ends={{npcID=12721}},coords={x=0.388,y=0.424,source="quest_giver",zoneID=331},questType="standard"},
[6482] = {id=6482,name="Freedom to Ruul",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,mapID=63,description="Eh? Who are you? ? You're no furbolg. They are cursed! They thought I was a bear and captured me, and now they starve me! My strength is failing... Help me escape, then speak with my sister Yama at the Splintertree Post to the east. ! I must escape!",objectivesText="Escort Ruul, then speak with Yama Snowhoof in Splintertree Post.",rewardGold=53500,rewardXP=1265,starts={{npcID=12818}},ends={{npcID=12837}},coords={x=0.414,y=0.346,source="quest_giver",zoneID=331},questType="standard"},
[6503] = {id=6503,name="Ashenvale Outrunners",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,mapID=63,description="Blasted elves! Dey knew right where to hit us! It was dem outrunners... I tried to warn 'em that we were being spied on, but no one listened. Now look at us - cooped up here like chickens! Never too late for vengeance, mon! Hunt 'em down and make 'em pay for what they done!",objectivesText="Kill 9 Ashenvale Outrunners .",rewardGold=53500,rewardXP=1010,starts={{npcID=12867}},ends={{npcID=12867}},coords={x=0.734,y=0.608,source="quest_giver",zoneID=331},questType="standard"},
[6544] = {id=6544,name="Torek's Assault",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,mapID=63,description="Hey! ! Come here! My raiders and I are about to attack the Silverwing Outpost to the west. Our target is its leader, Duriel Moonfire. Scouts report the outpost is defended heavily with sentinels and warriors. The battle will be glorious! Do you want to share in the glory, , and aid us? If so, then when it's over you can report our success to my superior, Ertog Ragetusk in Splintertree. What do you say. Are you with us?",objectivesText="Escort Torek on his attack against Silverwing Outpost and Duriel Moonfire, then report to Ertog Ragetusk at Splintertree Post.",rewardGold=53500,rewardXP=1265,rewardItems={16889,16890,156956},rewardChoices={16889,16890,156956},starts={{npcID=12858}},ends={{npcID=12877}},coords={x=0.684,y=0.752,source="quest_giver",zoneID=331},questType="standard"},
[6607] = {id=6607,name="Nat Pagle, Angler Extreme",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=15,mapID=70,description="Can't say I really enjoy fishin' much. Figure I been at it for a good 20 or 30 years now. I reckon people are driven to do what they do for different reasons. Now, I'm not saying you need to fish for 30 years or catch every fish in the sea to become a master fisherman. I reckon you just need to be determined - determined enough to sit on your duff for hours at a time, doin' nothin'. I'll tell you what, catch me a few rare fish and I'll teach you a thing or two. Here's a list:",objectivesText="Nat Pagle wants you to catch the following fish: Misty Reed Mahi Mahi from the Misty Reed Strand in the Swamp of Sorrows. A Sar'theris Striker from the Sar'theris Strand in Desolace. Feralas Ahi from the Verdantis River of Feralas. Savage Coast Blue Sailfin from the Savage Coast of Stranglethorn Vale. Return to Nat Pagle when you have reeled them all in! Progress: Anything bitin' today?",rewardXP=2090,rewardItems={45858},starts={{npcID=12919}},ends={{npcID=12919}},coords={x=0.586,y=0.602,source="quest_giver",zoneID=15},questType="standard"},
[6610] = {id=6610,name="Clamlette Surprise",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=440,mapID=71,description="Ever heard of a clamlette? Of course you haven't! It's my latest and greatest culinary masterpiece. Oh, , just thinking about a clamlette makes my mouth water. Unfortunately, I'm all out of supplies to make any! How about I make you a deal? You gather the supplies I need to make a clamlette and I'll teach you the finer points of exotic cuisine and I'll even throw in a couple of clamlettes to boot! Deal?? Here's what I need:",objectivesText="Dirge Quikcleave wants you to get the following items: 10 Giant Eggs . You will find those on the Rocs wandering Tanaris or any other species of large bird. 10 pieces of Zesty Clam Meat . You can find those in clams, naturally! 20 pieces of Fine Aged Cheddar . Get thee to a cheesery! Gather all of the items and return to Dirge. Progress: My cravings are going to be the end of me! Hurry, <name> - before I dip into my own supply.",rewardXP=2090,rewardItems={16971},starts={{npcID=40589}},ends={{npcID=40589}},coords={x=0.524,y=0.29,source="quest_giver",zoneID=440},questType="standard"},
[6611] = {id=6611,name="To Gadgetzan You Go!",level=15,requiredLevel=15,faction="horde",expansion=0,zoneID=440,mapID=85,description="How you expect Zamja teach you anything? You got all of Zamja 's cooking mojo and still you crave more! Zamja can't help. Fat needs to go to Gadgetzan. You find a little goblin named Dirge there - he help you, fatty. When you become big cook on the block, you come back and teach Zamja , ok? Now go!",objectivesText="Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.",rewardXP=525,starts={{npcID=3399}},ends={{npcID=40589}},coords={x=0.322,y=0.694,source="quest_giver",zoneID=1637},questType="standard"},
[6621] = {id=6621,name="King of the Foulweald",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,mapID=63,description="My research has paid off. I believe that with a show of force, we can diminish the furbolgs' aggressiveness. Take this banner a short ways northeast and place it on their totem mound. They will try to destroy the banner, but hold your ground until their chief, Murgut, appears to save face for the tribe. Bring me the totem he carries. Gather your allies, . This is no task for a single .",objectivesText="Place Senani's Banner on the Foulweald Totem Mound. Do not let the furbolgs destroy the banner. Defeat Chief Murgut and bring Murgut's Totem to Senani at Silverwind Refuge. Progress: Did you defeat Chief Murgut, <name>? Did you retrieve his foulweald totem?",rewardGold=53500,rewardXP=1265,rewardItems={17005,17006,131234},rewardChoices={17005,17006,131234},starts={{npcID=12696}},ends={{npcID=12696}},coords={x=0.498,y=0.652,source="quest_giver",zoneID=331},questType="standard"},
[6622] = {id=6622,name="Triage",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=45,mapID=14,description="Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Horde Trauma. Now pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage. Triage bandages will be supplied. Good luck, doctor.",objectivesText="Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries. Remember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged.",rewardXP=1770,rewardItems={14530,49192},starts={{npcID=12920}},ends={{npcID=12920}},coords={x=0.684,y=0.378,source="quest_giver",zoneID=45},questType="standard"},
[6623] = {id=6623,name="Horde Trauma",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=45,mapID=85,description="Doctor , I presume. It is a pleasure to see you again. I have some wonderful news for you! Doctor Gregory Victor , chief physician of Horde Trauma has made a personal request for you to join him at Hammerfall. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great Doctor Gregory Victor ! Do not squander this opportunity!",objectivesText="Travel to Hammerfall in the Arathi Highlands and speak with Doctor Gregory Victor about joining the ranks of Horde Trauma.",rewardXP=355,starts={{npcID=45540}},ends={{npcID=12920}},coords={x=0.37,y=0.872,source="quest_giver",zoneID=1637},questType="standard"},
[6624] = {id=6624,name="Triage",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=6040,mapID=70,description="Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Alliance Trauma. Now pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage. Good luck, doctor.",objectivesText="Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries. Remember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged.",rewardXP=2615,rewardItems={14530,49193},starts={{npcID=12939}},ends={{npcID=12939}},coords={x=0.676,y=0.488,source="quest_giver",zoneID=15},questType="standard"},
[6625] = {id=6625,name="Alliance Trauma",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=15,mapID=87,description="Doctor , I presume. It is a pleasure to see you. I have some wonderful news for you! Gustaf VanHowzen, chief physician of Alliance Trauma has made a personal request for you to join him at Theramore. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great doctor, Gustaf VanHowzen! Do not squander this opportunity, doctor!",objectivesText="Travel to Theramore in the Dustwallow Marsh and speak with Doctor Gustaf VanHowzen about joining the ranks of Alliance Trauma.",rewardXP=525,starts={{npcID=5150}},ends={{npcID=12939}},coords={x=0.548,y=0.586,source="quest_giver",zoneID=1537},questType="standard"},
[6641] = {id=6641,name="Vorsha the Lasher",level=7,requiredLevel=7,faction="horde",expansion=0,zoneID=331,mapID=63,description="Vorsha the Lasher... the fiendish hydra that roams the seas... She has attacked our outpost, each time unprovoked, laying waste to anything that falls in her path. But I am ready, . I have prepared to best the hydra and end these attacks on Zoram'gar. The naga honor the wicked nature of this beast with a brazier that remains lit on an island just off the coast. I believe that if we put it out, Vorsha will appear in anger. We will need help, so be sure to bring some strong allies.",objectivesText="Defeat Vorsha the Lasher.",rewardXP=1265,rewardItems={17692},rewardChoices={17692},starts={{npcID=12717}},ends={{npcID=12863}},coords={x=0.126,y=0.342,source="quest_giver",zoneID=331},questType="group"},
[6642] = {id=6642,name="Favor Amongst the Brotherhood, Dark Iron Ore",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=1584,objectivesText="Progress: Dark Iron, while plentiful in the Depths, is still a valued commodity amongst the Brotherhood. The sacred arms and armaments of Ragnaros favor Dark Iron. For every 10 pieces of Dark Iron Ore you offer, favor amongst the Brotherhood you will gain.",starts={{npcID=12944}},questType="dungeon"},
[6643] = {id=6643,name="Favor Amongst the Brotherhood, Fiery Core",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=1584,objectivesText="Progress: Woe unto those that tempt fate inside the Molten Core . Death comes swiftly - the punishment dealt without mercy. Many of the Brotherhood have been lost in their search for Fiery Cores . Offer 1 Fiery Core and you shall be granted favor amongst the Brotherhood.",starts={{npcID=12944}},questType="dungeon"},
[6644] = {id=6644,name="Favor Amongst the Brotherhood, Lava Core",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=1584,objectivesText="Progress: The Thorium Brotherhood sympathizes with your plight, <race>. This is why Lokthos has been empowered to bargain. Offer 1 Lava Core and you shall be granted favor amongst the Brotherhood.",starts={{npcID=12944}},questType="dungeon"},
[6645] = {id=6645,name="Favor Amongst the Brotherhood, Core Leather",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=1584,objectivesText="Progress: Many of the sacred recipes require the skin from Ragnaros' chosen pets. Offer 2 Core Leather , skinned from the smoldering corpses of the Core Hounds of the Molten Core and you shall be granted favor amongst the Brotherhood.",starts={{npcID=12944}},questType="dungeon"},
[6646] = {id=6646,name="Favor Amongst the Brotherhood, Blood of the Mountain",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=2717,objectivesText="Progress: The tears of the Fire Lord are a rare find indeed. Offer 1 Blood of the Mountain and you shall be granted favor amongst the Brotherhood.",starts={{npcID=12944}},questType="dungeon"},
[6661] = {id=6661,name="Deeprun Rat Roundup",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=2257,description="Avast ye scallywag. Arrrr... Arrrr ye looking fer work? We gots a serious rat problem down here an' not enough hands on the poop deck. What do ye say? All ye needs to do is take this here rat catchin' flute and play the melody around the vermin. They'll follow ye to the ends of the world! Just capture five of the little buggers and bring em back here. We needs em alive. Arrrrr...",objectivesText="Capture 5 Deeprun Rats by using the Rat Catcher's Flute . Lead the rats back to Monty . Progress: Yarrr... Swabby, what be takin' ye so long?",rewardXP=200,starts={{npcID=12997}},questType="standard"},
[6662] = {id=6662,name="Me Brother, Nipsy",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=2257,description="Me brother, Nipsy , runs a rat kabob operation on the other side of Deeprun. Ye needs to take this here crate o' rats to him before they go bad. Get a move on! Ye have ridden a tram before, aye? It's easy. Just step aboard when she arrives and enjoy the ride. An' keep yer arms and legs inside durin' the ride, lest ye be peglegged fer life.",objectivesText="Take the Carton of Mystery Meat to Nipsy at the Stormwind Deeprun Tram Depot. Progress: < Nipsy puts his index finger through one of the air holes in the carton.> Alive and kicking... and just in time!",rewardGold=53500,rewardXP=25,rewardItems={17119},starts={{npcID=12997}},questType="standard"},
[6701] = {id=6701,name="Syndicate Emblems",level=10,requiredLevel=10,faction="both",expansion=0,objectivesText="Progress: We have been entrenched in a battle with the Syndicate for years. What they lack in skill they make up for in numbers. It's impossible to kill them off fast enough to have any noticeable impact on their population! We've found that the best way to deal with their size is to pilfer their emblems. Once an emblem is stolen the shamed member is 'dealt' with internally. Pick their pockets clean and turn the emblems in to me or one of the other guards. Start at Durnholde, south of here.",starts={{npcID=6766}},ends={{npcID=6766}},questType="standard"},
[6741] = {id=6741,name="More Booty!",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,objectivesText="Progress: I need more armor scraps , <name>! Do you have any?",starts={{npcID=13176}},ends={{npcID=13176}},coords={x=0.496,y=0.826,source="quest_giver",zoneID=2597},questType="standard"},
[6781] = {id=6781,name="More Armor Scraps",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,objectivesText="Progress: <name>, we need more armor scraps to supply our troops!",starts={{npcID=13257}},ends={{npcID=13257}},questType="pvp"},
[6801] = {id=6801,name="Lokholar the Ice Lord",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,objectivesText="Progress: I come from Thunder Bluff, <race>. Cairne himself has seen to it that I assist the Frostwolf Clan in these dire times. But let us not waste any more time. You must strike down our enemies and bring to me their blood. Once enough blood has been gathered, the ritual of summoning may begin. Victory will be assured when the elemental lord is loosed upon the Stormpike army.",starts={{npcID=13236}},ends={{npcID=13236}},questType="pvp"},
[6825] = {id=6825,name="Call of Air - Guse's Fleet",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,objectivesText="Progress: We must prepare the new fleet of War Riders, <race>! My riders are set to make a strike on the central battlefield; but first, I must wet their appetites - preparing them for the assault. I need enough Stormpike Soldier Flesh to feed a fleet! Hundreds of pounds! Surely you can handle that, yes? Get going!",starts={{npcID=13179}},ends={{npcID=13179}},questType="pvp"},
[6826] = {id=6826,name="Call of Air - Jeztor's Fleet",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,objectivesText="Progress: You've worked hard, <name>, but we have only just begun! My War Riders must taste in the flesh of their targets. This will ensure a surgical strike against our enemies! My fleet is the second most powerful in our air command. Thusly, they will strike at the more powerful of our adversaries. For this, then, they need the flesh of the Stormpike Lieutenants. Make haste, soldier!",starts={{npcID=13180}},ends={{npcID=13180}},questType="pvp"},
[6827] = {id=6827,name="Call of Air - Mulverick's Fleet",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,objectivesText="Progress: I was locked up in a dwarven hellhole for days. You better believe I want revenge! We must plan carefully. First, my war riders need targets to gun for - high priority targets. I'm going to need to feed them the flesh of Stormpike Commanders. Unfortunately, those little buggers are entrenched deep behind enemy lines! You've definitely got your work cut out for you.",starts={{npcID=13181}},ends={{npcID=13181}},questType="pvp"},
[6847] = {id=6847,name="Master Ryson's All Seeing Eye",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=2597,description="Your war in the heart of Alterac means nothing to the Syndicate, . We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike. That, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region. Recover the Eye and our services shall be yours - for whatever time remains for your side. Return to me once you acquire the eye so that I may examine you.",objectivesText="Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson. Be warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!",starts={{npcID=13151}},questType="pvp"},
[6881] = {id=6881,name="Ivus the Forest Lord",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,objectivesText="Progress: The Frostwolf Clan is protected by a taint of elemental energy. Their shaman meddle in powers that will surely destroy us all if left unchecked. The damage has grown too great for the Circle to control! Ivus must be called to our aid. The Frostwolf soldiers carry elemental charms called storm crystals . We can use the charms to conjure Ivus. Venture forth and claim the crystals, <name>!",starts={{npcID=13442}},ends={{npcID=13442}},questType="pvp"},
[6941] = {id=6941,name="Call of Air - Vipore's Fleet",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,objectivesText="Progress: The elite Frostwolf units that guard the lines must be dealt with, soldier! I'm tasking you with thinning out that herd of savages. Return to me with medals from their lieutenants and legionnaires. When I feel that enough of the riff-raff has been dealt with, I'll deploy the air strike.",starts={{npcID=13439}},ends={{npcID=13439}},questType="pvp"},
[6942] = {id=6942,name="Call of Air - Slidore's Fleet",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,objectivesText="Progress: My gryphons are poised to strike at the front lines but cannot make the attack until the lines are thinned out. The Frostwolf warriors charged with holding the front lines wear medals of service proudly upon their chests. Rip those medals off their rotten corpses and bring them back here. Once the front line is sufficiently thinned out, I will make the call to air! Death from above!",starts={{npcID=13438}},ends={{npcID=13438}},questType="pvp"},
[6943] = {id=6943,name="Call of Air - Ichman's Fleet",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,objectivesText="Progress: Their spirits are low, soldier. After our last failed air strike against the Horde, they refuse to fly! It is up to you to bolster their morale. Return to the battlefield and strike at the heart of the Frostwolf's command. Take down their commanders and guardians. Return to me with as many of their medals as you can stuff in your pack! I promise you, when my gryphons see the bounty and smell the blood of our enemies, they will fly again! Go now!",starts={{npcID=13437}},ends={{npcID=13437}},coords={x=0.484,y=0.846,source="quest_giver",zoneID=2597},questType="pvp"},
[6961] = {id=6961,name="Great-father Winter is Here!",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,mapID=85,description="Have a wondrous Winter Veil, friend! Be sure to say hello to Great-father Winter ! If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil. Be sure to tell him what you hope to get this year! Also, be sure to stock up on treats to give those who've been nice this year. We have a great selection to choose from. Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!",objectivesText="Speak with Great-father Winter ; he is located near the Smokywood Pastures vendor area in Orgrimmar.",rewardXP=175,starts={{npcID=13418}},ends={{npcID=13445}},coords={x=0.524,y=0.77,source="quest_giver",zoneID=1637},questType="standard"},
[6962] = {id=6962,name="Treats for Great-father Winter",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,mapID=85,description="Hey, can you do Great-father Winter a favor, um, little ? Not to needlessly talk about myself in the third person, but Great-father Winter has been at this all day and he could use a treat himself. Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot. Think you could be a friend to the Great-father and fetch some for me?",objectivesText="Bring 5 Gingerbread Cookies and an Ice Cold Milk to Great-father Winter in Orgrimmar. Progress: All this talk of treats has given me a hankering for some myself. Mmmm... gingerbread cookies and milk...",rewardXP=355,rewardItems={17344,17404,17406,17407,17685,17727,21215,128647,128768},starts={{npcID=13445}},ends={{npcID=13445}},coords={x=0.498,y=0.78,source="quest_giver",zoneID=1637},questType="standard"},
[6964] = {id=6964,name="The Reason for the Season",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,mapID=85,description="Gifts, treats, presents... bah, I say! Those goblins pollute the true meaning of this season - the Feast of Winter Veil. This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit! If you're interested in learning what the Feast is all about for yourself, ask Sagorne Creststrider . I'm sure he'll be surprised that someone cares about history rather than getting presents.",objectivesText="Speak with Sagorne Creststrider in the Valley of Wisdom of Orgrimmar about the Feast of Winter Veil.",rewardXP=175,rewardItems={17735},starts={{npcID=9550}},ends={{npcID=13417}},coords={x=0.51,y=0.712,source="quest_giver",zoneID=1637},questType="standard"},
[6982] = {id=6982,name="Coldtooth Supplies",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,description="The Coldtooth mine is a storage depot for the Horde. I can't stomach the food they give their troops, and the state of their arms and armor is atrocious! But... in times like these when supplies are so important, we can use what they have. Enter the Coldtooth mine and bring me back their supplies. That will help keep the Alliance in fighting shape, and remove much needed equipment from the Horde's warriors. Good luck, . The mine is to the distant south, deep in Horde territory.",objectivesText="Bring 10 Coldtooth Supplies to the Alliance Quartermaster in Dun Baldar. Progress: Did you enter the Coldtooth mine in Horde territory, <name>? Did you raid their supplies?",rewardGold=341600,starts={{npcID=12096}},ends={{npcID=12096}},questType="pvp"},
[6983] = {id=6983,name="You're a Mean One...",level=30,requiredLevel=30,faction="horde",expansion=0,zoneID=17,mapID=85,description="A creature called \"The Abominable Greench\" stole our shipment of treats, . Be careful though! He's vicious and a bunch of those little green gnomes do his bidding! You're gonna need some help in facing him. Rumor has it he's holding our treats and our beloved Metzen the Reindeer at Growless Cave in the Hillsbrad Foothills! Find the treats and bring them back before the celebration is ruined and all the children of Orgrimmar are disappointed!",objectivesText="Recover the Stolen Treats and free Metzen the Reindeer after defeating the Abominable Greench, who is hiding out near Growless Cave in the Hillsbrad Foothills. Progress: <name> - our Feast of Winter Veil will be ruined without those treats to restock! Graccu himself will miss out on sharing his delicious meat pies with all the good boys and girls this season...",rewardXP=8230,rewardItems={17662,34425,37710,44606,45057,46709,46725,54343,54436,54437,54438,66540,73792,73797,90883,90888,93625,93626,104317,104318,108632,116456,116689,116690,116691,116692,116762,116763,117371,128636,128776,139337,143898,149503,151343,151344,151348,151349,151351,162642,162643,162973,172219,172222,172223,178530,178533,187422,188680,191925,191937,208825,209859,210656,232531},rewardCurrencies={{id=3100,amount=1},{id=3100,amount=5}},starts={{npcID=13418},{npcID=13636}},ends={{npcID=13418}},coords={x=0.524,y=0.77,source="quest_giver",zoneID=1637},questType="group"},
[6984] = {id=6984,name="A Smokywood Pastures' Thank You!",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,mapID=85,description="We at Smokywood Pastures appreciate the recovery of the stolen treats, . For that, we'd like to offer you a special gift... presented by none other than Great-father Winter himself! Please, speak with Great-father Winter , and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures. From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!",objectivesText="Speak with Great-father Winter in Orgrimmar.",rewardXP=1060,rewardItems={17706,17709,17720,17722,17724,17725,17726},rewardCurrencies={{id=1877,amount=1}},starts={{npcID=13418}},ends={{npcID=13445}},coords={x=0.524,y=0.77,source="quest_giver",zoneID=1637},questType="standard"},
[6985] = {id=6985,name="Irondeep Supplies",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,description="The Stormpike dwarves are using the Irondeep mine as a storage depot. I want you to raid that mine and bring me its supplies. This will curtail the Stormpikes' efforts in Alterac Valley , and will provide us with needed equipment! Be wary, . The Irondeep mine is deep in Alliance territory, and control of the mine is as shifting as the snows of Alterac.",objectivesText="Bring 10 Irondeep Supplies to the Horde Quartermaster in Frostwolf Keep. Progress: Did you enter the Irondeep mine, <name>? Did you raid its supplies?",rewardGold=341600,starts={{npcID=12097}},ends={{npcID=12097}},coords={x=0.466,y=0.84,source="quest_giver",zoneID=2597},questType="pvp"},
[7001] = {id=7001,name="Empty Stables",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=2597,description="The war in the valley has taken its toll on our soldiers. We must revitalize our forces! If we can fill up the stables, the Wolf Riders will once more be able to ride out into the field of battle. Take this muzzle and track down the frostwolves that inhabit the nearby forest. Once you find a wolf, use the muzzle to tame the beast. Bring the tamed beast back to me so that I may place it in the stable. When we have enough wolves stabled, the Wolf Riders will rejoin their patrol on our front lines.",objectivesText="Locate a Frostwolf in Alterac Valley . Use the Frostwolf Muzzle when you are near the Frostwolf to 'tame' the beast. Once tamed, the Frostwolf will follow you back to the Frostwolf Stable Master . Speak with the Frostwolf Stable Master to earn credit for the capture.",starts={{npcID=13616}},ends={{npcID=13616}},questType="standard"},
[7002] = {id=7002,name="Ram Hide Harnesses",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,objectivesText="Progress: While some of our soldiers are busy capturing wolves for the stable master, others must provide for the simple necessities that riding requires. I am speaking of riding harnesses, of course. You must strike at the indigenous rams of the region. The very same rams that the Stormpike cavalry uses as mounts! Slay them and return to me with their hides. Once we have gathered enough hides, we will fashion harnesses for the riders. The Frostwolf Wolf Riders will ride once more!",starts={{npcID=13441}},ends={{npcID=13441}},questType="pvp"},
[7021] = {id=7021,name="Great-father Winter is Here!",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,mapID=88,description="Have a wondrous Winter Veil, friend! Be sure to say hello to Great-father Winter , who's currently in Orgrimmar! If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil. Be sure to tell him what you hope to get this year! Also, be sure to stock up on treats to give those who've been nice this year. We have a great selection to choose from. Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!",objectivesText="Speak with Great-father Winter ; he is located near the Smokywood Pastures vendor area in Orgrimmar.",rewardXP=175,starts={{npcID=13431}},ends={{npcID=13445}},coords={x=0.424,y=0.556,source="quest_giver",zoneID=1638},questType="standard"},
[7022] = {id=7022,name="Greatfather Winter is Here!",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1537,mapID=87,description="Have a wondrous Winter Veil, friend! Be sure to say hello to Greatfather Winter ! If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil. Be sure to tell him what you hope to get this year! Also, be sure to stock up on treats to give those who've been nice this year. We have a great selection to choose from. Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!",objectivesText="Speak with Greatfather Winter ; he is located near the Smokywood Pastures vendor area in Ironforge.",rewardXP=175,starts={{npcID=13433}},ends={{npcID=13444}},coords={x=0.332,y=0.678,source="quest_giver",zoneID=1537},questType="standard"},
[7023] = {id=7023,name="Greatfather Winter is Here!",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1537,mapID=84,description="Have a wondrous Winter Veil, friend! Be sure to say hello to Greatfather Winter , who's currently in Ironforge! If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil. Be sure to tell him what you hope to get this year! Also, be sure to stock up on treats to give those who've been nice this year. We have a great selection to choose from. Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!",objectivesText="Speak with Greatfather Winter ; he is located near the Smokywood Pastures vendor area in Ironforge.",rewardXP=175,starts={{npcID=13435},{npcID=23010},{npcID=96304}},ends={{npcID=13444}},coords={x=0.628,y=0.702,source="quest_giver",zoneID=1519},questType="standard"},
[7024] = {id=7024,name="Great-father Winter is Here!",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,mapID=90,description="Have a wondrous Winter Veil, friend! Be sure to say hello to Great-father Winter , who's currently in Orgrimmar! If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil. Be sure to tell him what you hope to get this year! Also, be sure to stock up on treats to give those who've been nice this year. We have a great selection to choose from. Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!",objectivesText="Speak with Great-father Winter ; he is located near the Smokywood Pastures vendor area in Orgrimmar.",rewardXP=175,starts={{npcID=13429}},ends={{npcID=13445}},coords={x=0.678,y=0.388,source="quest_giver",zoneID=1497},questType="standard"},
[7025] = {id=7025,name="Treats for Greatfather Winter",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1537,mapID=87,description="Hey, can you do Greatfather Winter a favor, um, little ? Not to needlessly talk about myself in the third person, but Greatfather Winter has been at this all day and he could use a treat himself. Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot. Think you could be a friend to the Greatfather and fetch some for me?",objectivesText="Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Ironforge. Progress: All this talk of treats has given me a hankering for some myself. Mmmm... gingerbread cookies and milk...",rewardXP=355,rewardItems={17344,17404,17406,17407,17685,17727,21215,128647,128768},starts={{npcID=13444}},ends={{npcID=13444}},coords={x=0.332,y=0.658,source="quest_giver",zoneID=1537},questType="standard"},
[7026] = {id=7026,name="Ram Riding Harnesses",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,objectivesText="Progress: The Stormpike Brigade cannot charge into battle bareback! We require harnesses for our mounts, after all, we are not savages. While we could easily slay the rams that roam near our base for the leather required to fashion a harness, doing so would be idiotic. We need those rams for mounts. You must strike at our enemy's base, slaying the frostwolves they use as mounts and taking their hides. Return their hides to me so that harnesses may be made for the cavalry. Go!",starts={{npcID=13577}},ends={{npcID=13577}},questType="pvp"},
[7027] = {id=7027,name="Empty Stables",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=2597,description="Just look at the stables, ! Empty! The Stormpike Brigade has no rams to ride - the cavalry is defunct. You must help us, soldier. Take this training collar and enter the wilds of this valley. Locate the Alterac rams that roam throughout the area and use the collar to snare one. When you have captured a ram, return it to me and I shall place it in our stable. When we have enough rams, the ram rider commander will be notifed. With your help, the cavalry will be reborn!",objectivesText="Locate an Alterac Ram in Alterac Valley . Use the Stormpike Training Collar when you are near the Alterac Ram to 'tame' the beast. Once tamed, the Alterac Ram will follow you back to the Stable Master. Speak with the Stable Master to earn credit for the capture. Progress: Without your help, the Stormpike Ram Riders would not have mounts to ride into battle. You do us a great service!",starts={{npcID=13617}},ends={{npcID=13617}},questType="standard"},
[7043] = {id=7043,name="You're a Mean One...",level=30,requiredLevel=30,faction="alliance",expansion=0,zoneID=17,mapID=87,description="A creature called \"The Abominable Greench\" stole our shipment of treats, . Be careful though! He's vicious and a bunch of those little green gnomes do his bidding! You're gonna need some help in facing him. Rumor has it he's holding our treats and our beloved Metzen the Reindeer at Growless Cave in the Hillsbrad Foothills! Find the treats and bring them back before the celebration is ruined and all the children of Stormwind are disappointed!",objectivesText="Recover the Stolen Treats and free Metzen the Reindeer after defeating the Abominable Greench, who is hiding out near Growless Cave in the Hillsbrad Foothills. Progress: <name> - our Feast of Winter Veil will be ruined without those treats to restock! Graccu himself will miss out on sharing his delicious meat pies with all the good boys and girls this season...",rewardXP=8230,rewardItems={17662,34425,37710,44606,45057,46709,46725,54343,54436,54437,54438,66540,73792,73797,90883,90888,93625,93626,104317,104318,108632,116456,116689,116690,116691,116692,116762,116763,117371,128636,128776,139337,143898,149503,151343,151344,151348,151349,151351,162642,162643,162973,172219,172222,172223,178530,178533,187422,188680,191925,191937,208825,209859,210656,232531},rewardCurrencies={{id=3100,amount=1},{id=3100,amount=5}},starts={{npcID=13433},{npcID=13636}},ends={{npcID=13433}},coords={x=0.332,y=0.678,source="quest_giver",zoneID=1537},questType="group"},
[7045] = {id=7045,name="A Smokywood Pastures' Thank You!",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1537,mapID=87,description="We at Smokywood Pastures appreciate the recovery of the stolen treats, . For that, we'd like to offer you a special gift... presented by none other than Greatfather Winter himself! Please, speak with Greatfather Winter , and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures. From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!",objectivesText="Speak with Greatfather Winter in Ironforge.",rewardXP=1060,rewardItems={17706,17709,17720,17722,17724,17725,17726},rewardCurrencies={{id=1877,amount=1}},starts={{npcID=13433}},ends={{npcID=13444}},coords={x=0.332,y=0.678,source="quest_giver",zoneID=1537},questType="standard"},
[7061] = {id=7061,name="The Feast of Winter Veil",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,mapID=85,description="Here - if you are interested in learning more about the Feast of Winter Veil , read this book. While I think our recognition of the legend is the appropriate one, I'm enough of a student of legends to appreciate the collection of all information into a single source. When you're done, take the book to Baine Bloodhoof in Thunder Bluff. I know for a fact he'd be interested in hearing that others have taken an interest in the lore of our people.",objectivesText="Feel free to read the book, \" The Feast of Winter Veil \", to learn more about the holiday. When you are finished with the book, deliver it to Baine Bloodhoof in Thunder Bluff. Progress: I bid you welcome to Mulgore and our humble community of Thunder Bluff, friend. I always take an interest in those who choose to take an interest in the kingdom, its people, and its lore. Is this why you are standing before me?",rewardXP=175,starts={{npcID=13417}},ends={{npcID=13417}},coords={x=0.396,y=0.474,source="quest_giver",zoneID=1637},questType="standard"},
[7062] = {id=7062,name="The Reason for the Season",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1537,mapID=87,description="Gifts, treats, presents... bah, I say! Those goblins pollute the true meaning of this season - the Feast of Winter Veil. This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit! If you're interested in learning what the Feast is all about for yourself, ask Historian Karnik at the Explorers' League. I'm sure he'll be surprised that someone cares about history rather than getting presents.",objectivesText="Speak with Historian Karnik at the Explorers' League in Ironforge about the Feast of Winter Veil.",rewardXP=175,rewardItems={17735},starts={{npcID=1365}},ends={{npcID=2916}},coords={x=0.302,y=0.598,source="quest_giver",zoneID=1537},questType="standard"},
[7063] = {id=7063,name="The Feast of Winter Veil",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1537,mapID=87,description="Here - if you are interested in learning more about the Feast of Winter Veil , read this book. While I think our recognition of the legend is the appropriate one, I'm enough of a scholar to appreciate the collection of all information into a single source. When you're done, take the book to Muradin Bronzebeard . I know for a fact he'd be interested in hearing that others have taken an interest in the older legends.",objectivesText="Feel free to read the book, \" The Feast of Winter Veil \", to learn more about the holiday. When you are finished with the book, deliver it to Muradin Bronzebeard in Ironforge. Progress: I bid you welcome to the Kingdom of Ironforge, friend. I always take an interest in those who choose to take an interest in the kingdom, its people, and its lore. Is this why you are standing before me?",rewardXP=175,starts={{npcID=2916}},ends={{npcID=42928}},coords={x=0.77,y=0.118,source="quest_giver",zoneID=1537},questType="standard"},
[7081] = {id=7081,name="Alterac Valley Graveyards",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=267,mapID=25,description="The graveyards in Alterac Valley are prized territories. Both the Horde and the Alliance fight savagely for these sacred grounds. Are you, , ready to join that fight? I want you to assault an enemy graveyard. Find a graveyard with a Horde banner in its midst, and pull it from the ground! Do that, and your task will be complete.... But if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.",objectivesText="Assault a graveyard, then return to Sergeant Durgen Stormpike in the Alterac Mountains.",rewardGold=315900,rewardXP=200,starts={{npcID=13777}},ends={{npcID=13777}},coords={x=0.43,y=0.438,source="quest_giver",zoneID=267},questType="pvp"},
[7082] = {id=7082,name="The Graveyards of Alterac",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=2597,description="The battle lines of Alterac Valley are ever shifting. Territories swing back and forth as we meet our opponents in deadly combat. And graveyards, , are where battles rage most fierce. I want you to attack an Alliance held graveyard! Find a graveyard with an Alliance banner in its midst and pull it from the ground. Do that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.",objectivesText="Assault a graveyard, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.",rewardGold=341600,rewardXP=200,starts={{npcID=13776}},ends={{npcID=13776}},questType="pvp"},
[7101] = {id=7101,name="Towers and Bunkers",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=2597,description="Towers and bunkers are important positions, and we must capture and hold them all! So to that end, I want you to attack a bunker that is controlled by the enemy. To do that, enter one with an Alliance banner. You will see another banner inside. Pull out that banner, and a white Horde banner will appear in its place. Well done! At that point your task for me will be complete, but if you hold the place long enough, and if the Alliance doesn't take it back, then it will be destroyed!",objectivesText="Capture an enemy tower, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.",rewardGold=341600,rewardXP=200,starts={{npcID=13776}},ends={{npcID=13776}},questType="pvp"},
[7102] = {id=7102,name="Towers and Bunkers",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=267,mapID=25,description="Towers and bunkers are key defensive positions, and so we must hold as many as possible! I want you to attack a tower or a bunker in Alterac Valley . To do that, enter a tower with a Horde banner atop it. You will see another enemy banner inside. Pull out that banner, and a white Alliance banner will appear in its place. Well done! At that point your mission for me will be complete, but hold the area long enough, and if the Horde doesn't take it back, then it will be destroyed!",objectivesText="Destroy the banner at an enemy tower or bunker, then return to Sergeant Durgen Stormpike in the Alterac Mountains.",rewardGold=32900,rewardXP=200,starts={{npcID=13777}},ends={{npcID=13777}},coords={x=0.43,y=0.438,source="quest_giver",zoneID=267},questType="pvp"},
[7121] = {id=7121,name="The Quartermaster",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,description=", our quartermaster charged me to direct new recruits to him. He needs supplies from caches stored in the mines of Alterac, and he'll probably send you to get them. Follow the road. You'll find our quartermaster to the west.",objectivesText="Speak with the Stormpike Quartermaster .",rewardXP=25,starts={{npcID=13797}},ends={{npcID=12096}},questType="pvp"},
[7122] = {id=7122,name="Capture a Mine",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=267,mapID=25,description="The mines in Alterac Valley hold more than just minerals. Both the Frostwolf and Stormpike have cached excess supplies in the Irondeep and Coldtooth mines... that's not a bad idea, if we could only maintain control of them! Capture a mine, then return to me. To capture a mine, enter one that we do not control and kill its leader. When you do that, the mine will be ours, and we'll send troops to protect it!",objectivesText="Capture a mine that the Stormpike does not control, then return to Sergeant Durgen Stormpike in the Alterac Mountains.",rewardGold=53500,rewardXP=200,starts={{npcID=13777}},ends={{npcID=13777}},coords={x=0.43,y=0.438,source="quest_giver",zoneID=267},questType="pvp"},
[7123] = {id=7123,name="Speak with our Quartermaster",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,description=", the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley . Speak with him; he will tell you more. Follow the road west into the bunker, then take the west exit and you'll find our quartermaster.",objectivesText="Speak with the Frostwolf Quartermaster .",rewardXP=25,starts={{npcID=13798}},ends={{npcID=12097}},questType="pvp"},
[7124] = {id=7124,name="Capture a Mine",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,description="As battle rages over the landscape of Alterac Valley , so too does it rage through the Coldtooth and Irondeep mines. Both are rich sources of minerals and both are used to store supplies; it's no wonder they are so highly valued! Help our war effort, ! Capture one of the mines for the Horde! To capture a mine, enter one that we do not control and kill its leader. When that is done, the mine will be ours and we'll send troops to protect it!",objectivesText="Capture a mine, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.",rewardGold=683200,rewardXP=200,starts={{npcID=12097}},ends={{npcID=12097}},coords={x=0.466,y=0.84,source="quest_giver",zoneID=2597},questType="pvp"},
[7141] = {id=7141,name="The Battle of Alterac",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=2597,mapID=25,description="The Explorers' League believes there are artifacts in Alterac Valley , but the Frostwolf orcs won't let us explore. We can't allow the Horde to stop our scholarly pursuits! Defeat the Frostwolf general, Drek'Thar. With him dead, the orcs will lose their edge. Drek'Thar is in Frostwolf Keep, in the south of Alterac Valley . Vanquish him, and then return to me.",objectivesText="Enter Alterac Valley , defeat the Horde general Drek'thar, and then return to Prospector Stonehewer in the Alterac Mountains.",rewardGold=1024800,rewardXP=300,starts={{npcID=13816}},ends={{npcID=13816}},coords={x=0.452,y=0.452,source="quest_giver",zoneID=267},questType="pvp"},
[7142] = {id=7142,name="The Battle for Alterac",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=2597,mapID=25,description="The Stormpike dwarves and their allies have invaded Alterac Valley , and we must drive them out! To win the battle for Alterac, we must defeat their general, Vanndar Stormpike! You will find Vanndar in Dun Baldar, in the north of Alterac Valley . Destroy him, , and then return to me.",objectivesText="Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike. Then, return to Voggah Deathgrip in the Alterac Mountains.",rewardGold=995100,rewardXP=300,starts={{npcID=13817}},ends={{npcID=13817}},coords={x=0.586,y=0.342,source="quest_giver",zoneID=267},questType="pvp"},
[7161] = {id=7161,name="Proving Grounds",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=267,mapID=25,description="Hail, . It has been a long time since we have had the chance to answer the call of battle. The old feelings are slow to rise but once awakened, the blood does rush. The battle rage returns... All newcomers to the Valley must first complete the rite of battle. Deep within the Wildpaw gnoll cave is a banner of the Frostwolf. Venture forth and recover the banner. Return it to me and I shall grant you the Frostwolf initiate's insignia.",objectivesText="Travel to the Wildpaw cavern located southeast of the main base in Alterac Valley and find the Frostwolf Banner . Return the Frostwolf Banner to Warmaster Laggrond . Progress: Wake up! Wake up, <name>! This is not a dream. You really are entrenched in the midst of a raging battle!",rewardXP=200,rewardItems={17690,19483},starts={{npcID=13840}},ends={{npcID=13840}},coords={x=0.578,y=0.334,source="quest_giver",zoneID=267},questType="standard"},
[7162] = {id=7162,name="Proving Grounds",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=267,mapID=25,description="You've arrived just in time, . These Frostwolf savages just won't give up! We must show them the might of the Stormpike. They must bow to our superiority. Before you make your way to the field of battle, you will want to join the rank of Stormpike. Southwest of Dun Baldar, you will find the Icewing Caverns. Planted deep within the caverns is a Stormpike Banner . Venture forth and recover that banner. Return it to me, and you will have earned a Stormpike initiate's insignia.",objectivesText="Travel to the Icewing Caverns located southwest of Dun Baldar in Alterac Valley and recover the Stormpike Banner . Return the Stormpike Banner to Lieutenant Haggerdin in the Alterac Mountains. Progress: Beware the harpies of the region, <class>. They'll not think twice to rip out your throat!",rewardXP=200,rewardItems={17691,19484},starts={{npcID=13841}},ends={{npcID=13841}},coords={x=0.446,y=0.462,source="quest_giver",zoneID=267},questType="standard"},
[7163] = {id=7163,name="Rise and Be Recognized",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=267,mapID=25,objectivesText="Progress: < Warmaster Laggrond salutes you.> It is your time, <name>. You have done much for the Frostwolf Clan and in doing so, earned a place as not only a soldier of Frostwolf but also as a friend. Well done! Present your initiate's insignia.",rewardXP=200,rewardItems={17905},starts={{npcID=13840}},ends={{npcID=13840}},coords={x=0.578,y=0.334,source="quest_giver",zoneID=267},questType="standard"},
[7164] = {id=7164,name="Honored Amongst the Clan",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=267,mapID=25,objectivesText="Progress: It is good to see you again, <class>. I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf. Your time has come again, <name>. You have earned a new ranking and as such, a new insignia denoting this rise in stature. Present your insignia.",rewardXP=200,rewardItems={17906},starts={{npcID=13840}},ends={{npcID=13840}},coords={x=0.578,y=0.334,source="quest_giver",zoneID=267},questType="standard"},
[7165] = {id=7165,name="Earned Reverence",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=267,mapID=25,objectivesText="Progress: So many slain. Blood drenches the fields. Yet... You live... You have persevered. You have led our armies to many victories. For this, then, soldier, you have earned a new rank. Present your insignia.",rewardXP=250,rewardItems={17907},starts={{npcID=13840}},ends={{npcID=13840}},coords={x=0.578,y=0.334,source="quest_giver",zoneID=267},questType="standard"},
[7166] = {id=7166,name="Legendary Heroes",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=267,mapID=25,objectivesText="Progress: Your radiate command and power, <class>. Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name. Rise, Hero of Frostwolf. Rise and be honored! Present your insignia.",rewardXP=300,rewardItems={17908},starts={{npcID=13840}},ends={{npcID=13840}},coords={x=0.578,y=0.334,source="quest_giver",zoneID=267},questType="standard"},
[7167] = {id=7167,name="The Eye of Command",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=267,mapID=25,objectivesText="Progress: Drek'Thar sings your praises. Kalimdor is abuzz with tales of your heroics. The Warchief glows - your stalwart defense of our clan has pleased him greatly. You have earned the Eye of Command. Present your insignia, Commander <name>.",rewardXP=300,rewardItems={17909},starts={{npcID=13840}},ends={{npcID=13840}},coords={x=0.578,y=0.334,source="quest_giver",zoneID=267},questType="standard"},
[7168] = {id=7168,name="Rise and Be Recognized",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=267,mapID=25,objectivesText="Progress: Most do not live long enough to rise above their own mediocrity. You have proven yourself to be an exemplary soldier, <class>. The time has come. Present your insignia.",rewardXP=200,rewardItems={17900},starts={{npcID=13841}},ends={{npcID=13841}},coords={x=0.446,y=0.462,source="quest_giver",zoneID=267},questType="standard"},
[7169] = {id=7169,name="Honored Amongst the Guard",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=267,mapID=25,objectivesText="Progress: The base buzzes with news of your exploits in the Field of Strife! You have struck mighty blows against our enemy - crushing their morale! For this, you have earned a rank of honor among the Stormpike. Present your insignia.",rewardXP=200,rewardItems={17901},starts={{npcID=13841}},ends={{npcID=13841}},coords={x=0.446,y=0.462,source="quest_giver",zoneID=267},questType="standard"},
[7170] = {id=7170,name="Earned Reverence",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=267,mapID=25,objectivesText="Progress: I must know, <name>. When you look directly into the eyes of the enemy, do you see fear? Do they now cower in your presence? They must realize that they are defeated! You have earned reverence among the Guard. Present your insignia!",rewardXP=250,rewardItems={17902},starts={{npcID=13841}},ends={{npcID=13841}},coords={x=0.446,y=0.462,source="quest_giver",zoneID=267},questType="standard"},
[7171] = {id=7171,name="Legendary Heroes",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=267,mapID=25,objectivesText="Progress: Before me stands an exalted hero of the Alliance. < Lieutenant Haggerdin salutes.> Few have earned such a rank among the Stormpike. I have watched the enemy fall before you. I have seen their resolve crumble in your presence. When you enter the fray, you become the beacon of hope for our forces! Present your insignia.",rewardXP=300,rewardItems={17903},starts={{npcID=13841}},ends={{npcID=13841}},coords={x=0.446,y=0.462,source="quest_giver",zoneID=267},questType="standard"},
[7172] = {id=7172,name="The Eye of Command",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=267,mapID=25,objectivesText="Progress: Let them hear your voice, Commander <name>! Let them know fear. Show them what power the Stormpike holds in their rank! Present your insignia.",rewardXP=300,rewardItems={17904},starts={{npcID=13841}},ends={{npcID=13841}},coords={x=0.446,y=0.462,source="quest_giver",zoneID=267},questType="standard"},
[7223] = {id=7223,name="Armor Scraps",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,description="Battles rage constantly in Alterac Valley , and the supplies we get from Ironforge are not enough to outfit our experienced troops. If you find armor scraps from the battlefield, aid the war effort and bring those scraps to me!",objectivesText="Bring 20 Armor Scraps to Murgot Deepforge in Dun Baldar. Progress: Did you bring any armor scraps , <name>?",rewardXP=200,starts={{npcID=13257}},ends={{npcID=13257}},questType="pvp"},
[7224] = {id=7224,name="Enemy Booty",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,description="When you fight the enemy, gather the scraps of their armor and bring them to me. I'll use those scraps to make armor for our own troops!",objectivesText="Bring 20 Armor Scraps to Smith Regzar in Frostwolf Village. Progress: How goes the hunting, <name>. Do you have any armor scraps for me?",rewardXP=200,starts={{npcID=13176}},ends={{npcID=13176}},coords={x=0.496,y=0.826,source="quest_giver",zoneID=2597},questType="pvp"},
[7281] = {id=7281,name="Brotherly Love",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,description="Tragic... My brother faces me on the field of battle: A commander for the Stormpike. Of the four Stormpike Commanders, he is undoubtedly the most dangerous. Perhaps if he is slain, the Banshee Queen could turn him as she did me - show him the error of his ways... Deep within enemy territory you will find my brother. Slay him and return to me. I trust that you are capable of completing this mission, soldier. And soldier, do not go alone.",objectivesText="Travel into Stormpike territory and slay Commander Karl Philips . Return to Commander Louis Philips when the task is complete.",rewardXP=200,starts={{npcID=13154}},ends={{npcID=13154}},questType="pvp"},
[7282] = {id=7282,name="Brotherly Love",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,description="He must be put out of his misery, soldier! He knows not what he does. He has become a mindless servant of the dreaded Banshee Queen. Venture forth, across the Field of Strife, to the depths of Frostwolf territory. Find my brother and destroy him. His torment must come to an end.",objectivesText="Travel into Frostwolf territory and slay Commander Louis Philips . Return to Commander Karl Philips when the task is complete.",rewardXP=200,starts={{npcID=13320}},ends={{npcID=13320}},questType="pvp"},
[7301] = {id=7301,name="Fallen Sky Lords",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,description="We got them held prisoner, . I'm talking about their Wing Commanders. It was a furious battle in the skies but they finally fell! Unfortunately, our best pilots were shot down in a counterattack against Frostwolf Keep. You gotta find out what happened to them. Search Tower Point West and Frostwolf Keep. These were their last known locations. Search these areas thoroughly.",objectivesText="Travel to Frostwolf territory and search for Wing Commander Slidore, Wing Commander Vipore, and Wing Commander Ichman. Return to Commander Duffy should you complete your mission.",rewardXP=200,starts={{npcID=13319}},ends={{npcID=13319}},questType="pvp"},
[7302] = {id=7302,name="Fallen Sky Lords",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,description="Our air support is in shambles, . The Wing Commanders were shot down over enemy territory. You must find out what became of them so that we can attempt a rescue! Guse was last seen flying over the Icewing Bunker. Jeztor's War Rider was spotted near the Stormpike lumber mill. Mulverick... that reckless fool was seen crashing near the Dun'Baldar North Bunker. That's all the information I have. Move out! Search through the areas thoroughly.",objectivesText="Find out what became of Wing Commander Guse, Wing Commander Jeztor, and Wing Commander Mulverick. Return to Commander Mulfort should you complete your mission.",rewardXP=200,starts={{npcID=13153}},ends={{npcID=13153}},questType="pvp"},
[7383] = {id=7383,name="Teldrassil: The Burden of the Kaldorei",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=141,mapID=57,description="You must now visit the moonwell that rests under the boughs of the Oracle Tree, far to the northwest. The first and most powerful of our wells, its waters are said to possess the very essence of Elune's Powers. Retrieve a phial of its water and return to me. I will meet you at the crossroads in front of Darnassus when your task is complete.",objectivesText="Fill the Amethyst Phial . Progress: To be in the presence of the Oracle Tree... it is almost to feel wisdom take form.",rewardXP=200,starts={{npcID=3515}},ends={{npcID=3515}},coords={x=0.558,y=0.538,source="quest_giver",zoneID=141},questType="standard"},
[7385] = {id=7385,name="A Gallon of Blood",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=10458,objectivesText="Progress: You have the option of offering larger quantities of the blood taken from our enemies. I will be glad to accept gallon sized offerings, <name>.",starts={{npcID=13236}},ends={{npcID=13236}},questType="pvp"},
[7386] = {id=7386,name="Crystal Cluster",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=10458,objectivesText="Progress: There are times which you may be entrenched in battle for days or weeks on end. During those longer periods of activity you may end up collecting large clusters of the Frostwolf's storm crystals . The Circle accepts such offerings, <name>.",starts={{npcID=13442}},ends={{npcID=13442}},questType="pvp"},
[7493] = {id=7493,name="The Journey Has Just Begun",level=30,requiredLevel=30,faction="horde",expansion=0,zoneID=1637,mapID=85,rewardItems={15769},starts={{npcID=14392}},ends={{npcID=14392}},coords={x=0.514,y=0.83,source="quest_giver",mapID=85},questType="standard"},
[7497] = {id=7497,name="The Journey Has Just Begun",level=30,requiredLevel=30,faction="alliance",expansion=0,zoneID=1519,mapID=84,rewardItems={15769},starts={{npcID=14394}},ends={{npcID=14394}},coords={x=0.672,y=0.852,source="quest_giver",mapID=84},questType="standard"},
[7604] = {id=7604,name="A Binding Contract",level=20,requiredLevel=20,faction="both",expansion=0,zoneID=2717,description="The undersigned hereby declares that the Sulfuron ingot they are delivering to the Thorium Brotherhood (TB Ltd.) is genuine and not a facsimile thereof. The undersigned also acknowledges that any harm that should come to as a result of attempting to build, forge, find, create, sell, or eat Sulfuras, is not the responsibility or fault of TB Ltd. By signing this contract, you are agreeing to all terms listed herein. _________________ Signature",objectivesText="Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron. Progress: Do we have a deal?",rewardXP=2765,rewardItems={18592,256673},questType="dungeon"},
[7673] = {id=7673,name="Frost Ram Exchange",level=20,requiredLevel=20,faction="alliance",expansion=0,zoneID=1,mapID=27,rewardChoices={18786,18787,18785},starts={{npcID=1261}},ends={{npcID=1261}},coords={x=0.706,y=0.488,source="quest_giver",mapID=27},questType="standard"},
[7674] = {id=7674,name="Black Ram Exchange",level=20,requiredLevel=20,faction="alliance",expansion=0,zoneID=1,mapID=27,rewardChoices={18786,18787,18785},starts={{npcID=1261}},ends={{npcID=1261}},coords={x=0.706,y=0.488,source="quest_giver",mapID=27},questType="standard"},
[7677] = {id=7677,name="White Stallion Exchange",level=20,requiredLevel=20,faction="alliance",expansion=0,zoneID=12,mapID=37,rewardChoices={18777,18776,18778},starts={{npcID=384}},ends={{npcID=384}},coords={x=0.84,y=0.654,source="quest_giver",mapID=37},questType="standard"},
[7678] = {id=7678,name="Palomino Exchange",level=20,requiredLevel=20,faction="alliance",expansion=0,zoneID=12,mapID=37,rewardChoices={18777,18776,18778},starts={{npcID=384}},ends={{npcID=384}},coords={x=0.84,y=0.654,source="quest_giver",mapID=37},questType="standard"},
[7737] = {id=7737,name="Gaining Even More Acceptance",level=15,requiredLevel=15,faction="both",expansion=0,zoneID=51,mapID=32,objectivesText="Progress: You've worked your way up through the Brotherhood's corporate hierarchy, <race>. We have begun to look favorably upon you. Quite an accomplishment! If you're interested in more work and earning more respect amongst us, listen up. We can refine our fiery flux by adding a simple Dark Iron residue to the mix. This Dark Iron residue can be found in Blackrock Depths. Bring me all the Dark Iron residue you find!",starts={{npcID=14624}},ends={{npcID=14624}},questType="dungeon"},
[7781] = {id=7781,name="The Lord of Blackrock",level=30,requiredLevel=30,faction="alliance",expansion=0,zoneID=2677,mapID=84,description="The old feeling returns. The welcome pangs of victory reverberate throughout your being. Before you lies the monolithic, battle scarred head of Nefarian . Bring it to the Grand Admiral on the King's behalf, champion.",objectivesText="Bring the Head of Nefarian to Grand Admiral Jes-Tereth in Stormwind. Progress: Inconceivable!",rewardXP=6175,ends={{npcID=1750},{npcID=29611},{npcID=107574}},coords={mapID=84,source="quest_giver",x=0.855,y=0.326},questType="standard"},
[7782] = {id=7782,name="The Lord of Blackrock",level=30,requiredLevel=30,faction="alliance",expansion=0,zoneID=1519,mapID=84,description="Go to the Valley of Heroes and speak with Field Marshal Stonebridge .",objectivesText="Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Stonebridge .",rewardXP=6175,rewardItems={19366,19383,19384},rewardChoices={19383,19366,19384},starts={{npcID=1750},{npcID=29611},{npcID=107574}},ends={{npcID=14721}},coords={x=0.856,y=0.328,source="quest_giver",zoneID=1519},questType="standard"},
[7783] = {id=7783,name="The Lord of Blackrock",level=30,requiredLevel=30,faction="horde",expansion=0,zoneID=2677,mapID=85,description="The old feeling returns. The welcome pangs of victory reverberate throughout your being. Before you lies the monolithic, battle scarred head of Nefarian . Return it to the Warchief's advisor Eitrigg , champion.",objectivesText="Return the Head of Nefarian to Eitrigg in Orgrimmar . Progress: I wish I could have seen the look on the beast's face when you struck the killing blow!",rewardXP=6175,ends={{npcID=3144},{npcID=14720},{npcID=39605},{npcID=86832}},coords={mapID=85,source="quest_giver",x=0.49,y=0.721333},questType="standard"},
[7784] = {id=7784,name="The Lord of Blackrock",level=30,requiredLevel=30,faction="horde",expansion=0,zoneID=1637,mapID=85,description="Seek out Overlord Natoj in the Valley of Strength.",objectivesText="Speak with Overlord Natoj in Orgrimmar . He stands waiting for you in the Valley of Strength.",rewardXP=6175,rewardItems={19366,19383,19384},rewardChoices={19383,19366,19384},starts={{npcID=3144}},ends={{npcID=14392}},questType="standard"},
[7785] = {id=7785,name="Examine the Vessel",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=1377,mapID=81,description="Examine the vessel of his rebirth, mortal. It is from this that the Windseeker shall be reborn!",objectivesText="Examine the Vessel of Rebirth and return it to Highlord Demitrian . Progress: Will you release him from his eternal prison?",starts={{npcID=14347}},ends={{npcID=14347}},questType="standard"},
[7786] = {id=7786,name="Thunderaan the Windseeker",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=2717,mapID=81,description="I have told you all that I know, . It is you who must find elementium. It is you who must destroy the Firelord's corporeal form. Do this and gain the blessing of Thunderaan.",objectivesText="To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Windseeker , 10 bars of Enchanted Elementium, and the Essence of the Firelord to Highlord Demitrian in Silithus. Progress: Bring the world to its knees if you must!",rewardXP=6175,starts={{npcID=14347}},ends={{npcID=14347}},coords={x=0.296,y=0.106,source="quest_giver",zoneID=1377},questType="raid"},
[7787] = {id=7787,name="Rise, Thunderfury!",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=1377,mapID=81,description="You have defeated the Wind Seeker. Take the dormant blade and force the lying wretch, Demitrian, to use the materials you provided for his betrayal to wake Thunderfury.",objectivesText="Present the Dormant Wind Kissed Blade to Highlord Demitrian . Progress: <Demitrian cowers in your presence.>",rewardXP=6175,rewardItems={19019},starts={{npcID=14347}},ends={{npcID=14347}},questType="standard"},
[7810] = {id=7810,name="Arena Master",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5339,mapID=210,description="There must be more to being a master of the arena than this! Perhaps the Pirate who runs the event at Gurubashi will know!",objectivesText="Speak with Short John Mithril in the Stranglethorn Arena. Provided item:",rewardXP=175,ends={{npcID=14508}},coords={mapID=210,source="quest_giver",x=0.46,y=0.262},questType="pvp"},
[7838] = {id=7838,name="Arena Grandmaster",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5287,mapID=210,objectivesText="Progress: Avast Lubber! Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena! Arrrr!",rewardItems={19024},rewardChoices={19024},starts={{npcID=14508}},ends={{npcID=14508}},coords={x=0.45,y=0.254,source="quest_giver",zoneID=5287},questType="standard"},
[7848] = {id=7848,name="Attunement to the Core",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=51,mapID=36,description="Rifts stir, tear, and collapse all around us, . Not two paces from where I stand is a tear leading through the depths of Blackrock Mountain, into the maw of the Firelord. Surprised? Pity... The mortal races cannot comprehend that which they cannot see, touch, or feel. I assure you, the portal is there and access is possible. I've piqued your interest? Attunement is simple. Venture into Blackrock Depths and retrieve a core fragment . Return it to me and I shall attune your essence with the portal.",objectivesText="Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment . Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment . Progress: You must attune your soul with the Molten Core before access is granted.",rewardXP=4115,starts={{npcID=14387}},ends={{npcID=14387}},coords={x=0.182,y=0.25,source="quest_giver",zoneID=46},questType="dungeon"},
