[7905] = {id=7905,name="The Darkmoon Faire",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=5861,mapID=84,description="The Darkmoon Faire is coming! Experience our thrilling games, win fabulous prizes, have your fortune told! If you act right now, you can redeem this voucher for free prize tickets and a copy of the world-famous Darkmoon Adventurer's Guide to help you identify treasures in your travels! Just hand your voucher to Gelvas Grimegate located inside the Faire. Right now, the entrance to the Faire is outside Goldshire, in Elwynn Forest.",objectivesText="Deliver the Free Ticket Voucher to Gelvas Grimegate , located inside the Darkmoon Faire. Progress: Yes friend, may I help you? Do you have a voucher that needs redeeming?",rewardXP=25,rewardItems={71634},rewardCurrencies={{currencyID=515,quantity=1}},starts={{npcID=54334}},ends={{npcID=14828}},coords={x=0.622,y=0.73,source="quest_giver",zoneID=1519},questType="standard"},
[7907] = {id=7907,name="Darkmoon Beast Deck",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=5861,description="Now that you have gathered all of the Beast cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.",objectivesText="Return the Beast Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a deck of Beasts! Congratulations!",rewardItems={19288},starts={{npcID=14847}},ends={{npcID=14847}},questType="standard"},
[7926] = {id=7926,name="The Darkmoon Faire",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=5861,mapID=85,description="The Darkmoon Faire is coming! Experience our thrilling games, win fabulous prizes, have your fortune told! If you act right now, you can redeem this voucher for free prize tickets and a copy of the world-famous Darkmoon Adventurer's Guide to help you identify treasures in your travels! Just hand your voucher to Gelvas Grimegate located inside the Faire. Right now, the entrance to the Faire is outside Thunder Bluff in Mulgore!",objectivesText="Deliver the Free Ticket Voucher to Gelvas Grimegate , located inside the Darkmoon Faire. Progress: Yes friend, may I help you? Do you have a voucher that needs redeeming?",rewardXP=25,rewardItems={71634},rewardCurrencies={{currencyID=515,quantity=1}},starts={{npcID=55382}},ends={{npcID=14828}},coords={x=0.48,y=0.62,source="quest_giver",zoneID=1637},questType="standard"},
[7927] = {id=7927,name="Darkmoon Portals Deck",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=5861,description="Now that you have gathered all of the Portal cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.",objectivesText="Return the Portals Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a deck of Portals! Congratulations!",rewardItems={19290},starts={{npcID=14847}},ends={{npcID=14847}},questType="standard"},
[7928] = {id=7928,name="Darkmoon Warlords Deck",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=5861,description="Now that you have gathered all of the Warlord cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded. You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.",objectivesText="Return the Warlords Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a deck of Warlords! Congratulations!",rewardItems={19287},starts={{npcID=14847}},ends={{npcID=14847}},questType="standard"},
[7929] = {id=7929,name="Darkmoon Elementals Deck",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=5861,description="Now that you have gathered all of the Elemental cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.",objectivesText="Return the Elementals Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a deck of Elementals! Congratulations!",rewardItems={19289},starts={{npcID=14847}},ends={{npcID=14847}},questType="standard"},
[7937] = {id=7937,name="Your Fortune Awaits You...",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=12,description="\"Your fortune awaits you in Eastvale.\" The fortune Sayge handed you feels slightly warm to the touch. Grasping it firmly, you see an image of the Eastvale Logging Camp in Elwynn Forest. Focusing closer in on the image, you see a haystack that sits next to a stable.",objectivesText="Travel to the Eastvale Logging Camp in Elwynn Forest and seek out your fortune. Progress: This haystack looks like the one from your vision.",rewardItems={19425},ends={{npcID=180025}},coords={mapID=37,x=0.847,y=0.644},questType="standard"},
[7944] = {id=7944,name="Your Fortune Awaits You...",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=718,description="\"Your fortune awaits you inside Wailing Caverns.\" The fortune Sayge handed you feels slightly warm to the touch. Grasping it firmly, you see an image of a cave to the southwest of the Crossroads in the Barrens. Focusing closer in on the image, you wind about twisty passages until you reach a shimmering portal... one that leads into the heart of the caverns itself. Stepping through it, a strange chest appears out from nowhere.",objectivesText="Travel to the Wailing Caverns in the Barrens and seek out your fortune. Progress: This chest looks like the one from your vision...",rewardItems={19425},questType="standard"},
[7945] = {id=7945,name="Your Fortune Awaits You...",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=215,description="\"Your fortune awaits you outside Palemane Rock.\" The fortune Sayge handed you feels slightly warm to the touch. Grasping it firmly, you see an image of the Palemane Rock of Mulgore. Focusing closer in on the image, you see a tree stump that sits close to the cave entrance.",objectivesText="Travel to Palemane Rock in Mulgore and seek out your fortune. Progress: This tree stump looks like the one from your vision.",rewardItems={19425},ends={{npcID=180056}},coords={mapID=7,x=0.35,y=0.615},questType="standard"},
[7946] = {id=7946,name="Spawn of Jubjub",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=5861,objectivesText="Progress: I'm so happy Jubjub is no longer lost. She loves Dark Iron ale so much that when I ran out... she ran away to find more! Now that Jubjub's back, I want as much ale as I can get! I won't want her to run away again! Do you have any Dark Iron Ale? If you do, then I'll trade you one of Jubjub's frog eggs for a mug...",rewardItems={19450,19462},starts={{npcID=14871}},ends={{npcID=14871}},coords={x=0.558,y=0.706,source="quest_giver",zoneID=5861},questType="standard"},
[8149] = {id=8149,name="Honoring a Hero",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1,mapID=27,description="During the Harvest Festival of Azeroth, we give thanks to heroes for the sacrifices - in some cases ultimate sacrifices - they have given on our behalf. The Alliance acknowledges many heroes, but none weave a more tragic tale than that of Uther Lightbringer. Help us honor Uther by taking this offering to his tomb in the Western Plaguelands. Place it at his statue, and then return to me. I'll only be here through the end of the festival, so waste no time in giving Uther his tribute.",objectivesText="Travel to Uther's Tomb in Western Plaguelands and use Uther's Tribute at his statue, and then return to Wagner Hammerstrike outside Ironforge before the Harvest Festival is over.",rewardXP=200,rewardItems={20009,116442,116443,116444,116445},rewardChoices={116445,116444,116443,116442},rewardCurrencies={{id=3008,amount=10}},starts={{npcID=15011}},ends={{npcID=15011}},coords={x=0.598,y=0.342,source="quest_giver",zoneID=1},questType="standard"},
[8150] = {id=8150,name="Honoring a Hero",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=331,mapID=1,description="During the Harvest Festival of Azeroth, we give thanks to heroes for the sacrifices - in some cases ultimate sacrifices - they have given on our behalf. The Horde acknowledges many heroes, but none exemplify strength and sacrifice more than Grom Hellscream. Help us honor Grom by taking this offering to his monument in the Demon Fall Canyon of Ashenvale. Place it at the base, and then return to me. I'll only be here through the end of the festival, so waste no time in giving Grom his tribute.",objectivesText="Travel to Grom's Monument in the Demon Fall Canyon of Ashenvale and use Grom's Tribute at the base of the monument. Return to Javnir Nashak outside Orgrimmar before the Harvest Festival is over. Progress: Have you made the journey to Grom's Monument and placed his tribute there? The site where the monument is still touched by the taint of the Burning Legion. Should you be less experienced in the ways of adventuring, be on your toes when approaching the monument.",rewardXP=200,rewardItems={20010,116442,116443,116444,116445},rewardChoices={116445,116444,116443,116442},rewardCurrencies={{id=3008,amount=10}},starts={{npcID=15012}},ends={{npcID=15012}},coords={x=0.462,y=0.15,source="quest_giver",zoneID=14},questType="standard"},
[8194] = {id=8194,name="Apprentice Angler",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=5287,mapID=210,objectivesText="Progress: Even though we already have a contest winner, I will still buy your Tastyfish from you at a reasonable price. Whadda ya say!",rewardGold=77400,starts={{npcID=15078}},ends={{npcID=15078}},coords={x=0.414,y=0.73,source="quest_giver",zoneID=5287},questType="standard"},
[8221] = {id=8221,name="Rare Fish - Keefer's Angelfish",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=5287,mapID=210,objectivesText="Progress: *Whir* *Click* I seek rare fish for Fishmaster Bluegill to catalogue. If you bring me a Keefer's Angelfish , I will provide you with this fine reward. *Zzzap* *Whir*",rewardGold=77400,rewardItems={19972},starts={{npcID=15079}},ends={{npcID=15079}},coords={x=0.414,y=0.73,source="quest_giver",zoneID=5287},questType="standard"},
[8224] = {id=8224,name="Rare Fish - Dezian Queenfish",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=5287,mapID=210,objectivesText="Progress: *Whir* *Click* I seek rare fish for Fishmaster Bluegill to catalogue. If you bring me a Dezian Queenfish , I will provide you with this fine reward. *Zzzap* *Whir*",rewardGold=77400,rewardItems={19971},starts={{npcID=15079}},ends={{npcID=15079}},coords={x=0.414,y=0.73,source="quest_giver",zoneID=5287},questType="standard"},
