[8249] = {id=8249,name="Junkboxes Needed",level=20,requiredLevel=20,faction="both",expansion=0,zoneID=267,mapID=25,objectivesText="Progress: My rogues need to hone their lockpicking skills, and I need locks of adequate difficulty -- the stuff Zan makes us is unfit for all but the lowliest neophytes. Tell ya what, if you bring me 5 Heavy Junkboxes , I'll provide you with some of the finest throwing knives known to roguekind. You can unlock the boxes and rifle through them, but you'll have to leave at least a few coins in them... even a rogue in training needs motivation.",rewardItems={20086,25878},starts={{npcID=7323}},ends={{npcID=6707},{npcID=7323}},coords={x=0.714,y=0.45,source="quest_giver",zoneID=267},questType="standard"},
