[8632] = {id=8632,name="Enigma Circlet",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5892,description="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos. In my visions I see their monstrous faces adorned by powerful crowns. But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs. Bring me the components I require, . I will give you a headpiece of unmatched power.",objectivesText="Bring Vek'nilash's Circlet , 2 Idols of Night , 5 Bronze Scarabs and 5 Ivory Scarabs to Andorgos in Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest. Progress: Did you bring me the components I asked for, <name>?",rewardItems={21347},starts={{npcID=15502}},ends={{npcID=15502}},coords={x=0.506,y=0.826,source="quest_giver",zoneID=5892},questType="raid"},
[8633] = {id=8633,name="Enigma Robes",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,description="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power. When the stars are favorable, he will lash out against all living beings with terrible wrath. You must find him before then and find a way to bring his existence to an end. Do this and bring me a piece of his husk. I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!",objectivesText="Bring the Husk of the Old God , 2 Idols of the Sun , 5 Gold Scarabs and 5 Clay Scarabs to Vethsera inside Ahn'Qiraj. You must also attain Honored reputation with the Brood of Nozdormu to complete this quest. Progress: At his dwelling in Ahn'Qiraj, dread C'Thun awaits in slumber.",rewardItems={21343},starts={{npcID=15504}},questType="raid"},
[8634] = {id=8634,name="Enigma Boots",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,description="Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of dominance and other minor components by and I'll create a set of powerful boots for you. You will find them useful in the fight against the enemy.",objectivesText="Bring the Qiraji Bindings of Dominance , 2 Idols of the Sun , 5 Silver Scarabs and 5 Crystal Scarabs to Kandrostrasz in Ahn'Qiraj. This quest also requires Neutral faction with the Brood of Nozdormu. Progress: You've acquired the items I requested, <name>?",rewardItems={21344},starts={{npcID=15503}},questType="raid"},
