[8669] = {id=8669,name="Genesis Shoulderpads",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5892,description="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon. Bring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!",objectivesText="Bring the Qiraji Bindings of Dominance , 2 Idols of Strife , 5 Gold Scarabs and 5 Bone Scarabs to Andorgos in Ahn'Qiraj. You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest. Progress: Have you collected the components I require?",rewardItems={21354},starts={{npcID=15502}},ends={{npcID=15502}},coords={x=0.506,y=0.826,source="quest_giver",zoneID=5892},questType="raid"},
