[8689] = {id=8689,name="Shroud of Infinite Wisdom",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5695,description="I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, . I can make you a protective item that'll be of assistance in the fight against our enemy, . I shall need a Qiraji drape, which I'll resize for you of course. I'll also need idols and scarabs which I'll use to create a suitable clasp. I promise you won't be disappointed.",objectivesText="Bring 1 Qiraji Martial Drape , 2 Jasper Idols , 5 Gold Scarabs and 5 Clay Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest. Progress: Did you bring the materials for the cloak, <name>?",rewardXP=4115,rewardItems={21412},starts={{npcID=15500}},ends={{npcID=15500}},coords={x=0.594,y=0.14,source="quest_giver",zoneID=5695},questType="raid"},
