[8705] = {id=8705,name="Gavel of Infinite Wisdom",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5695,description="The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong. Just the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces. Prove your allegiance to the Circle, , and I will make you a powerful weapon from the finest Qiraji materials.",rewardXP=4115,rewardItems={21410},starts={{npcID=15499}},ends={{npcID=15499}},coords={x=0.594,y=0.14,source="quest_giver",zoneID=5695},questType="raid"},
[8706] = {id=8706,name="Hammer of the Gathering Storm",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5695,description="The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong. Just the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces. Prove your allegiance to the Circle, , and I will make you a powerful weapon from the finest Qiraji materials.",objectivesText="Bring 1 Qiraji Spiked Hilt , 2 Amber Idols , 5 Ivory Scarabs and 5 Bronze Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest. Progress: Did you bring me the components I require, <name>?",rewardXP=4115,rewardItems={21398},starts={{npcID=15499}},ends={{npcID=15499}},coords={x=0.594,y=0.14,source="quest_giver",zoneID=5695},questType="raid"},
