[8747] = {id=8747,name="The Path of the Protector",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=440,objectivesText="Progress: Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted. The signet ring of the defender will offer superior protection against the forces of evil. Be warned, once you have chosen your path, you will have no recourse should you change your mind.",rewardXP=4115,rewardItems={21196},starts={{npcID=15192}},ends={{npcID=15192}},questType="standard"},
[8748] = {id=8748,name="The Path of the Protector",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=440,objectivesText="Progress: Your continued defense of the children of Kalimdor has been acknowledged. Hand me your signet ring so that I may enhance its powers.",rewardXP=4115,rewardItems={21197},starts={{npcID=15192}},ends={{npcID=15192}},questType="standard"},
[8749] = {id=8749,name="The Path of the Protector",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=440,objectivesText="Progress: You honor my kind, <name>. Strike down the enemies of Kalimdor! Show them what it means to deface the land of eternal starlight. You have earned another enhancement. Hand me your signet ring so that I may bolster its power.",rewardXP=4115,rewardItems={21198},starts={{npcID=15192}},ends={{npcID=15192}},questType="standard"},
[8750] = {id=8750,name="The Path of the Protector",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=440,objectivesText="Progress: Dedication of this magnitude is a rarity. You have shown that your will is unfaltering, <name>. You shall be greatly rewarded for your stalwart watch over our world. Hand me your signet ring so that I may strengthen its enchantment.",rewardXP=4115,rewardItems={21199},starts={{npcID=15192}},ends={{npcID=15192}},questType="standard"},
[8751] = {id=8751,name="The Protector of Kalimdor",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=440,objectivesText="Progress: Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so! Hand me your signet ring so that I may make the necessary adjustments.",rewardXP=6175,rewardItems={21200},starts={{npcID=15192}},ends={{npcID=15192}},questType="standard"},
