[8784] = {id=8784,name="Secrets of the Qiraji",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5892,description="You have discovered an ancient Qiraji artifact ! Perhaps one of the dragons near the entrance of the temple would have a use for this relic.",objectivesText="Take the Ancient Qiraji Artifact to the dragons hiding near the entrance of the temple. Progress: You're glowing! I know what that means...",starts={{npcID=15503}},ends={{npcID=15502}},questType="standard"},
[8788] = {id=8788,name="A Gently Shaken Gift",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=1637,mapID=85,rewardItems={21241},starts={{npcID=180746}},ends={{npcID=180746}},coords={x=0.334,y=0.659,source="quest_giver",mapID=85},questType="standard"},
[8789] = {id=8789,name="Imperial Qiraji Armaments",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,description="We have not sat idly by for a millennium, . We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world. And we have learned of their own internal treachery. Weaknesses exist and we know how to use those weaknesses to our advantage. Find and bring me their ceremonial armaments: Combined with the element created from the volatility of their own God, they will become a force of reckoning.",objectivesText="Arygos in the Temple of Ahn'Qiraj will create Elementium Infused Armaments for you should you bring him Imperial Qiraji Armaments and 3 Elementium Ingots . Progress: Seek out what I requested. You will become greater than the sum of your parts, champion.",rewardItems={21242,21244,21269,21272},rewardChoices={21242,21272,21244,21269},starts={{npcID=15380}},questType="raid"},
[8790] = {id=8790,name="Imperial Qiraji Regalia",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,description="Arygos theorizes that the element which is born of conflicts between the Old Gods and their minions is also extremely deadly to them under the right conditions. I speak of Elementium, mortal. Find and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power.",objectivesText="Merithra of the Dream in the Temple of Ahn'Qiraj will create Elementium Infused Armaments for you should you bring her Imperial Qiraji Regalia and 3 Elementium Ingots . Progress: You will strike them down and free us of these bonds.",rewardItems={21268,21273,21275},rewardChoices={21273,21275,21268},starts={{npcID=15378}},questType="raid"},
[8791] = {id=8791,name="The Fall of Ossirian",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3429,mapID=81,description="A terrible menace has been laid to rest. The cruel Ossirian has been vanquished. The denizens of Kalimdor would be relieved to know of this victory. Take Ossirian's head and present it to Commander Mar'alith of Cenarion Hold.",objectivesText="Deliver the Head of Ossirian the Unscarred to Commander Mar'alith at Cenarion Hold in Silithus. Progress: Ah, <name>, you have returned! And in one piece, I might add. What news do you bring from Ahn'Qiraj?",rewardXP=6175,rewardItems={21504,21505,21506,21507},rewardChoices={21504,21507,21505,21506},ends={{npcID=15181}},coords={mapID=81,source="quest_giver",x=0.532,y=0.325},questType="raid"},
[8801] = {id=8801,name="C'Thun's Legacy",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=3428,mapID=327,description="The walls of Ahn'Qiraj tremble. A force of evil, older than the world itself, has been destroyed. As you look at the remnants of the colossal abomination your heart nearly freezes. Even in death you can feel the legacy of C'Thun's evil around you. You have done what was thought to be impossible. You grab at an eye stalk of the fiend, stowing it safely in your pack. Take the Eye of C'Thun to the dragons in the next chamber.",objectivesText="Take the Eye of C'Thun to Caelestrasz in the Temple of Ahn'Qiraj . Progress: <Caelastrasz kneels before you.> Lord <name>, you have freed us of its grasp.",rewardXP=6175,questType="standard"},
[8802] = {id=8802,name="The Savior of Kalimdor",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=440,description="To the Caverns of Time you go, . Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection.",objectivesText="Take the Eye of C'Thun to Anachronos at the Caverns of Time. Progress: Lord <name>! It is over...",rewardXP=6175,rewardItems={21709,21710,21712},rewardChoices={21712,21710,21709},starts={{npcID=15379}},questType="standard"},
[8803] = {id=8803,name="A Festive Gift",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=1637,mapID=85,rewardItems={21328},starts={{npcID=180793}},ends={{npcID=180793}},coords={x=0.336,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[8827] = {id=8827,name="Winter's Presents",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1537,mapID=87,description="I hear Greatfather Winter - with the generous support of Smokywood Pastures - has put presents for everyone under the tree in Ironforge. I wish I could go, but I've got to look after the PX-238 Winter Wondervolt. But you should definitely check it out. I'm sure Greatfather Winter has some presents with your name on them.",objectivesText="Speak with Greatfather Winter . He is located near the Smokywood Pastures vendor area in Ironforge.",rewardXP=25,starts={{npcID=15732}},ends={{npcID=13444}},questType="standard"},
[8828] = {id=8828,name="Winter's Presents",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1637,mapID=85,description="I hear Great-father Winter - with the generous support of Smokywood Pastures - has put presents for everyone under the tree in Orgrimmar. I wish I could go, but I've got to look after the PX-238 Winter Wondervolt. But you should definitely check it out. I'm sure Great-father Winter has some presents with your name on them.",objectivesText="Speak with Great-father Winter . He is located near the Smokywood Pastures vendor area in Orgrimmar.",rewardXP=25,starts={{npcID=15732}},ends={{npcID=13445}},questType="standard"},
[8860] = {id=8860,name="New Year Celebrations!",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=1519,mapID=84,description="Stormwind is holding a celebration for the new year! All day long today you can get free booze, and at night they'll put on a firework show! It should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better! Well anyway, Innkeeper Allison in Stormwind needs a supply of Smokywood Pastures fare to help feed all the party goers. Can you do me a favor and deliver it? Thanks, ! Innkeeper Allison is in The Gilded Rose, in the Trade District of Stormwind.",objectivesText="Bring the Smokywood Supplies to Innkeeper Allison in Stormwind. Progress: Greetings! Are you here for the party! Or perhaps you just need to rest those weary feet of yours...",rewardGold=5350,starts={{npcID=15732}},ends={{npcID=6740}},questType="standard"},
[8861] = {id=8861,name="New Year Celebrations!",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=1638,mapID=88,description="Thunder Bluff is holding a celebration for the new year! All day you'll find free booze there, and at night they'll put on a firework show! It should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better! Well anyway, Innkeeper Pala in Thunder Bluff needs a supply of Smokywood Pastures fare to help feed all the party goers. Can you do me a favor and deliver it? Thanks, ! Innkeeper Pala is in the inn near the bridge to Hunter's Rise.",objectivesText="Bring the Smokywood Supplies to Innkeeper Pala in Thunder Bluff. Progress: Good day, <class>! Did you come to Thunder Bluff for our celebrations? Or are you here to rest a weary hoof between hunts?",rewardGold=5350,starts={{npcID=15732}},ends={{npcID=6746}},questType="standard"},
[8866] = {id=8866,name="Bronzebeard the Elder",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=1537,mapID=87,rewardXP=100,rewardItems={21100,21746},starts={{npcID=15871}},ends={{npcID=15871}},coords={x=0.294,y=0.172,source="quest_giver",mapID=87},questType="standard"},
[8867] = {id=8867,name="Lunar Fireworks",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=6611,mapID=37,description="Every year the druids of Moonglade hold a celebration of our city's great triumph over an ancient evil. We celebrate the wisdom of our elders, share in magnificent feasts and of course... shoot fireworks! For a small donation you can purchase colorful rockets from our vendor. Try using some of the launchers around here, .",objectivesText="Launch 8 Lunar Fireworks and 2 Cluster Fireworks and return to a Lunar Festival Harbinger at any capital city. Progress: Did you find the launchers, <name>?",rewardItems={21711},starts={{npcID=15895}},ends={{npcID=15895}},coords={x=0.342,y=0.506,source="quest_giver",zoneID=12},questType="standard"},
[8868] = {id=8868,name="Elune's Blessing",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=493,mapID=80,description="The beast Omen was once a hero of this world. A wolf of great strength and fortune, Omen fought beside the heroes of the War of the Ancients until he succumbed to demonic magics. Turning against his allies, he raged across Azeroth and carried death and terror in his wake. Finally defeated here, in Moonglade, Omen now sleeps among the silt of Lake Elune'ara. But each new year, during the festival, he stirs... Gather cohorts, , and summon and defeat the beast Omen. Earn the blessing of Elune!",objectivesText="Summon Omen, defeat him and gain Elune's Blessing. Return to Valadar Starsong in Nighthaven. Progress: Omen yet stirs below below Lake Elune'ara, <name>...",rewardGold=53500,rewardXP=200,rewardItems={21540,21640},starts={{npcID=15864}},ends={{npcID=15864}},coords={x=0.54,y=0.35,source="quest_giver",zoneID=493},questType="raid"},
[8870] = {id=8870,name="The Lunar Festival",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=6611,mapID=37,description="It's that time of the year, ! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. ou will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.",objectivesText="Talk to the Lunar Festival Harbinger in the Mystic Ward of Ironforge. You can also talk to Lunar Festival Harbingers in other capital cities.",starts={{npcID=15892}},ends={{npcID=15895}},coords={x=0.346,y=0.506,source="quest_giver",zoneID=12},questType="standard"},
[8871] = {id=8871,name="The Lunar Festival",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=6611,mapID=37,description="It's that time of the year, ! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.",objectivesText="Talk to the Lunar Festival Harbinger in Stormwind City.",starts={{npcID=15892}},ends={{npcID=15895}},coords={x=0.346,y=0.506,source="quest_giver",zoneID=12},questType="standard"},
[8872] = {id=8872,name="The Lunar Festival",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=6611,mapID=37,description="It's that time of the year, ! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.",objectivesText="Talk to the Lunar Festival Harbinger at the Cenarion Enclave in Darnassus. You can also talk to Lunar Festival Harbingers in other capital cities.",starts={{npcID=15892}},ends={{npcID=15895}},coords={x=0.346,y=0.506,source="quest_giver",zoneID=12},questType="standard"},
[8873] = {id=8873,name="The Lunar Festival",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=6611,mapID=85,description="It's that time of the year, ! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.",objectivesText="Talk to the Lunar Festival Harbinger in the Valley of Wisdom in Orgrimmar. You can also talk to Lunar Festival Harbingers in other capital cities.",starts={{npcID=15891}},ends={{npcID=15895}},coords={x=0.66,y=0.368,source="quest_giver",zoneID=1497},questType="standard"},
[8874] = {id=8874,name="The Lunar Festival",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=6611,mapID=85,description="It's that time of the year, ! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.",objectivesText="Talk to the Lunar Festival Harbinger in the entrance to the Undercity. You can also talk to Lunar Festival Harbingers in other capital cities.",starts={{npcID=15891}},ends={{npcID=15895}},coords={x=0.66,y=0.368,source="quest_giver",zoneID=1497},questType="standard"},
[8875] = {id=8875,name="The Lunar Festival",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=6611,mapID=85,description="It's that time of the year, ! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.",objectivesText="Talk to the Lunar Festival Harbinger at the Elder Rise in Thunder Bluff. You can also talk to Lunar Festival Harbingers in other capital cities.",starts={{npcID=15891}},ends={{npcID=15895}},coords={x=0.66,y=0.368,source="quest_giver",zoneID=1497},questType="standard"},
[8883] = {id=8883,name="Valadar Starsong",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=493,mapID=37,description="Now that you have your Lunar Festival invitation, you may travel to Moonglade! There you will find many revelers, and in the village of Nighthaven Valadar Starsong and his sister Fariel await those eager to participate in the celebration. Travel to Moonglade through the greater moonlight and speak with Valadar Starsong ; see what prizes you might gain during the festival!",objectivesText="Use your Lunar Festival Invitation in the moonlight to travel to Moonglade. Speak with Valadar Starsong in Nighthaven when you arrive.",rewardXP=25,starts={{npcID=15895}},ends={{npcID=15864}},coords={x=0.342,y=0.506,source="quest_giver",zoneID=12},questType="standard"},
[9250] = {id=9250,name="Frame of Atiesh",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=440,mapID=71,description="With the frame formed, Atiesh is nearly whole. Only the head and base of the staff are now missing. There is also a minor issue regarding the staff being a conduit for Sargeras's evil. Find someone that can assist you in locating the remaining pieces and exorcising the evil from the staff.",objectivesText="Find someone that will help you in recovering the last two pieces of the staff and ridding it of evil.",rewardXP=4115,questType="raid"},
[9251] = {id=9251,name="Atiesh, the Befouled Greatstaff",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=440,description="You question why you are still alive. After all, you have in your possession an item of great evil. The answer is not clear, . I only do as I must. Kel'Thuzad sits atop his throne in Naxxramas, plotting... He seeks that which you hold and holds that which you seek. As for the base of the staff; the dwarf, Brann Bronzebeard, held it when he entered Ahn'Qiraj. He has left Ahn'Qiraj but the base of Atiesh remains. Should you succeed in recovering the pieces, return them to me.",objectivesText="Anachronos at the Caverns of Time in Tanaris wants the Staff Head of Atiesh and the Base of Atiesh .",rewardXP=4115,starts={{npcID=15192}},questType="raid"},
[9259] = {id=9259,name="Traitor to the Bloodsail",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=5287,mapID=210,objectivesText="Progress: That mangy dog, Revilgaz, has offered to pardon any former Bloodsails willing to turn on their cap'n! That bilge sucker asked me to go an' off me ole' mates and to bring back their bandannas as proof. I don't have it in me heart to do that, nor will I ask ye to. Bring me some silk cloth and red dye and I'll make suitable replicas. I'll tell the Baron you went turncoat, but be warned... the Bloodsails are not gonna like it!",starts={{npcID=16399}},ends={{npcID=16399}},coords={x=0.484,y=0.632,source="quest_giver",zoneID=5287},questType="standard"},
[9267] = {id=9267,name="Mending Old Wounds",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=10413,mapID=10,objectivesText="Progress: You'd better think twice before setting foot in Ratchet, <name>! Word's been getting around of your dirty deeds. You're in luck though, a ship just arrived with many wounded from an encounter with the Bloodsail Buccaneers. This is your chance to prove you're not a complete scoundrel. Lend us a hand by bringing linen cloth for bandages and empty vials for potions.",starts={{npcID=16418}},ends={{npcID=16418}},questType="standard"},
[9268] = {id=9268,name="War at Sea",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=440,mapID=71,objectivesText="Progress: You seek to befriend the goblins of Tanaris once again, <name>? We're in need of materials for sails and guns to fight off our old enemies, the Bloodsail Buccaneers. Bring me mageweave and strong flux and we'll be on our way to pardoning your trespasses.",starts={{npcID=16417}},ends={{npcID=16417}},coords={x=0.504,y=0.272,source="quest_giver",zoneID=440},questType="standard"},
[9272] = {id=9272,name="Dressing the Part",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=5287,mapID=210,rewardItems={22742,22743,22744,22745,22746},starts={{npcID=2546}},ends={{npcID=2546}},coords={x=0.466,y=0.952,source="quest_giver",mapID=210},questType="standard"},
[9362] = {id=9362,name="Warlord Krellian",level=30,requiredLevel=30,faction="none",expansion=0,zoneID=16,description="There isn't much time, <name>! My scrying spells have revealed a powerful source of magic. I cannot leave the tower, and would ask you to kill the vile creature in possession of this artifact. The pathetic little cretin is known as Warlord Krellian, hiding behind his guards in the Temple of Zin-Malor. Burn him to ashes and take the prismatic shell he covets so dearly.",objectivesText="Retrieve the Prismatic Shell for Archmage Xylem. The Archmage resides in a tower atop the cliffs of Azshara. Progress: There is not time to waste! Have you the shell?",starts={{npcID=8379}},ends={{npcID=8379}},questType="standard"},
[9364] = {id=9364,name="Fragmented Magic",level=30,requiredLevel=30,faction="none",expansion=0,description="My research has revealed a unique purpose for the prismatic shell . Carry the shell and cast your polymorph spell on the Spitelash in Azshara. If you wait a few moments, the chaotic aura of the shell will cause them to split into several smaller clones for a few moments. Kill these clones as quickly as possible, and the shell will collect their essence. When the shell is full, return it to me.",objectivesText="Polymorph the Spitelash of Azshara and kill the clones that appear several seconds later. When you have slain 50 Polymorph Clones , return to Archmage Xylem in Azshara. Progress: Have you collected the magic?",rewardXP=4115,rewardItems={4142},starts={{npcID=8379}},ends={{npcID=8379}},questType="standard"},
[9415] = {id=9415,name="Report to Marshal Bluewall",level=15,requiredLevel=15,faction="alliance",expansion=0,zoneID=1377,mapID=81,description="Are you Marshal Bluewall 's new recruits? Of course you are. What are you waiting for? Good soldiers are dying in the desert. Aren't you excited to join them? Now, get going and don't dry out on the way.",objectivesText="Speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.",starts={{npcID=17082}},ends={{npcID=17080}},coords={x=0.544,y=0.328,source="quest_giver",zoneID=1377},questType="standard"},
[9416] = {id=9416,name="Report to General Kirika",level=15,requiredLevel=15,faction="horde",expansion=0,zoneID=1377,mapID=81,description="You must be one of General Kirika 's new recruits. It's about time you showed up. Bodies wear down quick in the desert. The dwarves have been getting reinforcements daily, and we can't afford to lose ground in our struggle for resources in Silithus . Get your instructions from the General. It's not my job to train you, just find you.",objectivesText="Speak with General Kirika at the Horde encampment near Hive'Regal.",starts={{npcID=17081}},ends={{npcID=17079}},coords={x=0.53,y=0.346,source="quest_giver",zoneID=1377},questType="standard"},
[11580] = {id=11580,name="Desecrate this Fire!",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=5840,mapID=21,rewardGold=309800,rewardXP=200,rewardItems={23247},starts={{npcID=187559,x=0.242,y=0.373,mapID=15},{npcID=187559,x=0.464,y=0.144,mapID=17},{npcID=187559,x=0.767,y=0.144,mapID=51},{npcID=187559,x=0.52,y=0.47,mapID=1},{npcID=187559,x=0.332,y=0.308,mapID=70},{npcID=187559,x=0.604,y=0.535,mapID=76},{npcID=187559,x=0.499,y=0.543,mapID=10},{npcID=187559,x=0.291,y=0.564,mapID=22},{npcID=187559,x=0.408,y=0.518,mapID=50},{npcID=187559,x=0.69,y=0.428,mapID=14},{npcID=187559,x=0.515,y=0.293,mapID=36},{npcID=187559,x=0.766,y=0.744,mapID=26},{npcID=187559,x=0.385,y=0.484,mapID=115},{npcID=187559,x=0.432,y=0.714,mapID=121},{npcID=187559,x=0.403,y=0.856,mapID=120},{npcID=187559,x=0.569,y=0.518,mapID=18},{npcID=187559,x=0.496,y=0.387,mapID=21},{npcID=187559,x=0.52,y=0.593,mapID=7},{npcID=187559,x=0.545,y=0.5,mapID=25},{npcID=187559,x=0.516,y=0.668,mapID=63},{npcID=187559,x=0.725,y=0.476,mapID=69},{npcID=187559,x=0.191,y=0.613,mapID=116},{npcID=187559,x=0.261,y=0.774,mapID=66},{npcID=187559,x=0.53,y=0.624,mapID=65},{npcID=187559,x=0.498,y=0.282,mapID=71},{npcID=187559,x=0.563,y=0.658,mapID=78},{npcID=187559,x=0.484,y=0.135,mapID=117},{npcID=187559,x=0.582,y=0.473,mapID=83},{npcID=187559,x=0.508,y=0.418,mapID=81},{npcID=187559,x=0.805,y=0.53,mapID=127},{npcID=187559,x=0.463,y=0.503,mapID=94},{npcID=187559,x=0.47,y=0.259,mapID=95},{npcID=187559,x=0.573,y=0.418,mapID=100},{npcID=187559,x=0.511,y=0.342,mapID=107},{npcID=187559,x=0.519,y=0.433,mapID=108},{npcID=187559,x=0.336,y=0.303,mapID=104},{npcID=187559,x=0.356,y=0.519,mapID=102},{npcID=187559,x=0.499,y=0.59,mapID=105},{npcID=187559,x=0.323,y=0.684,mapID=109},{npcID=187559,x=0.511,y=0.119,mapID=114},{npcID=187559,x=0.473,y=0.617,mapID=119},{npcID=187559,x=0.407,y=0.672,mapID=199},{npcID=187559,x=0.533,y=0.465,mapID=241},{npcID=187559,x=0.53,y=0.345,mapID=249},{npcID=187559,x=0.506,y=0.707,mapID=210},{npcID=1875