[11966] = {id=11966,name="Incense for the Festival Scorchlings",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=3430,mapID=18,description="Did you know that our festival fires burn in every land with a Horde settlement? Flame Keepers tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue. With each Flame Keeper is a festival scorchling -- an emissary to the elemental spirits of fire. Would you like to honor a scorchling, ? Take this summer incense and bring it to any festival scorchling . Appease the little fire spirit, and it may reward you.",rewardXP=25,rewardItems={23247,35725},starts={{npcID=16818,x=0.62,y=0.668,zoneID=85},{npcID=16818,x=0.674,y=0.08,zoneID=1497},{npcID=16818,x=0.478,y=0.384,zoneID=1637},{npcID=16818,x=0.214,y=0.278,zoneID=1638},{npcID=16818,x=0.698,y=0.426,zoneID=3487},{npcID=16818,x=0.62,y=0.322,zoneID=3703}},ends={{npcID=26520,x=0.572,y=0.518,zoneID=85},{npcID=26520,x=0.522,y=0.472,zoneID=14},{npcID=26520,x=0.608,y=0.534,zoneID=16},{npcID=26520,x=0.518,y=0.592,zoneID=215},{npcID=26520,x=0.512,y=0.662,zoneID=331},{npcID=26520,x=0.464,y=0.504,zoneID=3430}},coords={x=0.62,y=0.668,source="quest_giver",zoneID=85},questType="world",worldTaskTitle="Incense for the Festival Scorchlings"},
[24902] = {id=24902,name="Lorna Crowley",level=1,requiredLevel=1,faction="alliance",categories={"vignette"},flags={"tracking"},expansion=0,zoneID=4755,mapID=202,description="It's true then? Gilneas has lost her favorite son. We will mourn when this is all over but not a day sooner. We will not allow ourselves the luxury of grief while the enemy still breathes Gilnean air. My father's men are ready to strike while we still have the Banshee Queen's trail. Just say the word if you're ready. Liam deserves swift vengeance.",rewardGold=76100,rewardXP=250,starts={{npcID=38611,x=0.384,y=0.6,mapID=202}},ends={{npcID=38611,x=0.384,y=0.6,mapID=202}},coords={x=0.384,y=0.6,source="quest_giver",mapID=202},questType="vignette",db2VignetteID=3384,db2VignetteName="Lorna Crowley"},
