[54619] = {id=54619,name="Wiping Out the Witherbark",level=50,requiredLevel=50,faction="horde",expansion=0,zoneID=45,mapID=14,description="The bloodthirsty Witherbark tribe has always refused to join the Horde... and now that the Horde holds Arathi, we will succeed where the Alliance has failed. Drive the forest trolls from the Highlands.",rewardCurrencies={{id=1716,amount=1}},questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=143237,text="Witherbark tribe trolls slain"}},worldTaskTitle="Wiping Out the Witherbark",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
