[55350] = {id=55350,name="Assault: Amathet Advance",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The Amathet seek to claim the Forge of Origination for their own. We must not allow it to fall into their hands again! Our men are defending the entrance, but they will be overwhelmed if the entire might of the Amathet advances upon them. Do what you can to route their forces before its too late.",rewardXP=10225,rewardItems={168043,168257,168267,171208,174764,174765,174961},rewardCurrencies={{id=1553,amount=500}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Drive back the Amathet"},{orderIndex=15,type=0,amount=1,objectID=161031,text="Speak with Captain Hadan"}},worldTaskTitle="Assault: Amathet Advance",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
