[56308] = {id=56308,name="Assault: Aqir Unearthed",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Our position is being overrun. The aqir are surging in greater numbers than I've ever seen! I'm not sure how long we'll be able to hold the line. We need you to drive them back!",rewardXP=10225,rewardItems={169432,174222,174224,174227,174756,174761,174960},rewardCurrencies={{id=1553,amount=500}},ends={{npcID=159544,x=0.4,y=0.212,zoneID=10833}},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Drive back the Aqir"}},worldTaskTitle="Assault: Aqir Unearthed",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
[56402] = {id=56402,name="Wastewander Coins",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=10833,mapID=1527,description="It may be too late for some of our fallen brothers and sisters, but it is not too late to give solace to their families. Every Wastewander carries with them a unique coin, signifying their status as a member of our group. If you find any of these coins, please bring them to me and I will make sure they are properly returned to their next of kin.",rewardGold=234000,rewardXP=6815,rewardItems={169432},rewardCurrencies={{id=1755,amount=325},{id=1553,amount=418},{id=1553,amount=496},{id=1560,amount=50}},starts={{npcID=159560,x=0.4,y=0.452,zoneID=10833}},ends={{npcID=159560,x=0.4,y=0.452,zoneID=10833}},coords={x=0.4,y=0.452,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Wastewander Coins"},
[56550] = {id=56550,name="Corpse Cleanup",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=10833,mapID=1527,description="Our friends continue to fall as these terrible insects pour of their nests and attack our camps. It's a terrible job to ask of anyone, but we have to dispose of the corpses as quickly as possible. We can't allow our dead to be used as fertilizer for growing their disgusting eggs.",rewardGold=234000,rewardXP=6815,rewardItems={174323},rewardCurrencies={{id=1755,amount=325},{id=1553,amount=336},{id=1553,amount=354},{id=1553,amount=363}},starts={{npcID=159682,x=0.244,y=0.552,zoneID=10833}},ends={{npcID=159682,x=0.244,y=0.552,zoneID=10833}},coords={x=0.244,y=0.552,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Corpse Cleanup"},
[56889] = {id=56889,name="Wounded Wastewanderers",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=10833,mapID=1527,description="Ahh, my friend, have you returned to render additional aid? As you can see, we are still locked in battle with these creatures, with no end to their numbers in sight. This is a war of attrition and we find ourselves at a clear disadvantage as injuries continue to mount. Please, assist any of our wounded that you find within the ruins.",rewardGold=234000,rewardXP=6815,rewardItems={174326},rewardCurrencies={{id=1553,amount=447},{id=1755,amount=325},{id=1553,amount=324},{id=1553,amount=417}},starts={{npcID=159820,x=0.28,y=0.634,zoneID=10833}},ends={{npcID=159820,x=0.28,y=0.634,zoneID=10833}},coords={x=0.28,y=0.634,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Wounded Wastewanderers"},
[57157] = {id=57157,name="Assault: The Black Empire",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=9105,mapID=1527,description="It is just as the visions fortold. Dark forces have come to claim the Forge of Origination. They must be stopped, or all of Azeroth will meet its end!",rewardXP=10225,rewardItems={170553,173372},rewardCurrencies={{id=1553,amount=750}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Drive back N'Zoth's Forces"}},worldTaskTitle="Assault: The Black Empire",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
