[57621] = {id=57621,name="Summoning Ritual",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=10833,mapID=1527,questType="world",worldTaskTitle="Summoning Ritual",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[57737] = {id=57737,name="Ramkahen Rescue",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Mar'at was overrun by those foul K'thir before we could safely evacuate our citizens. I fear the worst has happened to them. Please, if anyone is left alive within the city, tell them to come to Ramkahen.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1560,amount=55},{id=1755,amount=325},{id=1553,amount=315},{id=1553,amount=343}},starts={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},ends={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},coords={x=0.548,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Ramkahen Rescue"},
[57773] = {id=57773,name="Close to Tears",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=9105,mapID=1527,description="Our warriors have observed foul manifestations coming forth from numerous void tears within the surrounding jungle. They have been but mere weaklings, clearly intended to test our defenses before the real forces arrive. If we do not deal with this threat now, however, it will only be a matter of time until we are overrun by their fodder. Find a way to close those portals!",rewardGold=280900,rewardXP=6815,rewardCurrencies={{id=1755,amount=325},{id=1553,amount=312},{id=1553,amount=325},{id=1553,amount=364}},starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Close to Tears"},
[57774] = {id=57774,name="Nine Lives",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Scouts have returned recently, nearly on the verge of death, with reports that I find... disconcerting. Neferset have been spotted wandering the streets of their city to the south. This would normally be no cause for alarm, except the Neferset were completely wiped out. I must ask you to investigate further... and if by some foul magic these reports turn out to be true, you must do whatever you can to contain this threat!",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1560,amount=60},{id=1755,amount=325},{id=1553,amount=328},{id=1553,amount=332}},starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Nine Lives"},
[57968] = {id=57968,name="The Wastewandering Dead",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=10833,mapID=1527,description="Is there no end to these foul monsters!? I cannot abide the desecration of our dead, especially not as fodder for this disgusting insect army. Destroy as many as you can, preferably with fire!",rewardGold=312800,rewardXP=6815,rewardCurrencies={{id=1560,amount=50},{id=1755,amount=325},{id=1553,amount=321},{id=1553,amount=365}},starts={{npcID=159682,x=0.244,y=0.552,zoneID=10833}},ends={{npcID=159682,x=0.244,y=0.552,zoneID=10833}},coords={x=0.244,y=0.552,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="The Wastewandering Dead"},
[58010] = {id=58010,name="More Bits, More Bits!",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="We need more Aqir samples, $p. As many as you can get your hands on! I've made some fascinating discoveries already, but there's so much more to learn. With further study and a bit of good luck, perhaps we can slowly begin to uncover some of their weaknesses.",rewardGold=234000,rewardXP=6815,rewardItems={174356},rewardCurrencies={{id=1560,amount=60},{id=1755,amount=325},{id=1553,amount=403},{id=1553,amount=428}},starts={{npcID=161738,x=0.556,y=0.352,zoneID=10833}},ends={{npcID=161738,x=0.556,y=0.352,zoneID=10833}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="More Bits, More Bits!"},
[58146] = {id=58146,name="For the Alliance",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1519,mapID=84,description="As High Tinker, and leader of both Gnomes and Mechagnomes, I am proud to welcome you to the Alliance! A world of adventure awaits you beyond the walls of Mechagon City. When you are ready, step on the teleporter. Ambassador Moorgard will be awaiting your arrival at the Stormwind Embassy. There will be many potential avenues of advancement available to you. Choose wisely, improve, and remember to share your data.",rewardGold=34100,rewardXP=175,rewardItems={157022,174068},starts={{npcID=159587,x=0.73,y=0.336,zoneID=10290}},ends={{npcID=133362,x=0.532,y=0.152,zoneID=1519}},coords={x=0.73,y=0.336,source="quest_giver",zoneID=10290},questType="world",worldTaskTitle="For the Alliance"},
[58147] = {id=58147,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1637,mapID=84,description="Welcome to Stormwind, . I invite you to explore our fair city. Say, you look like someone who enjoys the night life. We have many popular taverns and a vibrant music scene! Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of the Mechagnomes is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, !",rewardGold=30900,rewardXP=175,starts={{npcID=133362,x=0.532,y=0.152,zoneID=1519}},ends={{npcID=160600,x=0.624,y=0.298,zoneID=1519}},coords={x=0.532,y=0.152,source="quest_giver",zoneID=1519},questType="world",worldTaskTitle="Stranger in a Strange Land"},
[58151] = {id=58151,name="Minions of N'Zoth",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=12766,mapID=1527,description="The howling winds that surround us may some day be drowned out, masked by these increasingly dark, yet familiar whispers. Something must be done. Enter the darkness, , and strike down the enemy.",rewardGold=234000,rewardXP=6815,rewardItems={174288},rewardCurrencies={{id=1719,amount=30},{id=1719,amount=50},{id=1755,amount=1500},{id=1755,amount=3000}},starts={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},ends={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},coords={x=0.842,y=0.516,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Minions of N'Zoth"},
[58155] = {id=58155,name="A Hand in the Dark",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Imagine being trapped in a world you didn't know existed--a reality unbeknownst to even yourself. Thoughts, fears, and dark desires cloud the mind, coupled with irresistible temptation. So many are lost to the darkness, unable to resist these temptations, but not all. Do what you can to preserve those that fight against the darkness. We mustn't allow them to fall.",rewardGold=234000,rewardXP=6815,rewardItems={174288},rewardCurrencies={{id=1719,amount=30},{id=1719,amount=50},{id=1755,amount=1500},{id=1755,amount=3000}},starts={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},ends={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},coords={x=0.842,y=0.516,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="A Hand in the Dark"},
[58156] = {id=58156,name="Vanquishing the Darkness",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=12766,mapID=1527,description="The darkness grows. The cycle continues. Do what you can to stay N'Zoth's efforts. If we do not stand against the corruption we may some day find ourselves drowning in darkness.",rewardGold=234000,rewardXP=6815,rewardItems={174288},rewardCurrencies={{id=1719,amount=30},{id=1755,amount=1500},{id=1755,amount=3000},{id=1719,amount=8}},starts={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},ends={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},coords={x=0.842,y=0.516,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Vanquishing the Darkness"},
[58167] = {id=58167,name="Preventative Measures",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Waves of darkness continue their assault on the shores of our world. I am afraid the waters at our feet may soon wash over us. Perhaps it is time for a different approach. Make your way into the twisted realm and seek out their dark portals. If we are able to slow their advance it might just buy us the time needed to expose a fatal weakness.",rewardGold=234000,rewardXP=6815,rewardItems={174288},rewardCurrencies={{id=1719,amount=30},{id=1719,amount=50},{id=1755,amount=1500},{id=1755,amount=3000}},starts={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},ends={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},coords={x=0.842,y=0.516,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Preventative Measures"},
[58168] = {id=58168,name="A Dark, Glaring Reality",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=12766,mapID=1527,description="Their eyes are upon us, , watching every move from the shadows. It is no wonder our efforts thus far have felt... lacking. The fault is by no means your own. We should have suspected this was the case long ago. If we are to continue our efforts with meaningful expectations we must go undetected. Our old friend has offered an elixir to aide in exposing our enemy. While there may be a few... unknown side effects, the result provides the imbiber true sight in the darkness.",rewardGold=234000,rewardXP=6815,rewardItems={173810,174288},rewardCurrencies={{id=1719,amount=30},{id=1755,amount=1500},{id=1755,amount=3000},{id=1719,amount=50}},starts={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},ends={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},coords={x=0.842,y=0.516,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="A Dark, Glaring Reality"},
[58229] = {id=58229,name="A Rallying Cry",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Our lands have been infested by the minions of the Old Gods. They strike at every front, even assailing the very minds of our soldiers. Our forces cannot handle this for long. We must strike a decisive blow to try to salvage some of their morale. Find the biggest, slimiest, tentacle-faced monstrosities that you can and bring them down. My men will rally to your example.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1755,amount=325},{id=1553,amount=301},{id=1553,amount=315},{id=1553,amount=318}},starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="A Rallying Cry"},
[58230] = {id=58230,name="Blind the Eyes",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Strange forces have been interfering with my visions of late. The ever-watching eyes pierce through the veil, shattering my clairvoyance. The eyes of our enemy peer into our very souls and pierce our minds. We must rip them out, if we truly wish to be rid of the curse on this land.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1755,amount=325},{id=1553,amount=305},{id=1553,amount=335},{id=1553,amount=343}},starts={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={x=0.546,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Blind the Eyes"},
[58231] = {id=58231,name="Wisdom From Madness",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="In my visions I hear... voices... Their words are nonsense, but over time patterns arise. I believe there is something important behind what these voices say, but I have yet to decipher a word. We will need to learn from the source. Find any writings you can among the cultists who travel with these dark creatures. Their ramblings may be the key to understanding the message beneath this madness.",rewardGold=234000,rewardXP=6815,rewardItems={173954},rewardCurrencies={{id=1553,amount=469},{id=1560,amount=60},{id=1560,amount=65},{id=1755,amount=325}},starts={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={x=0.546,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Wisdom From Madness"},
[58232] = {id=58232,name="Order Among Chaos",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=9105,mapID=1527,description="It has been a long time since the tol'vir have squared off against the forces of an Old God, so our tactical knowledge of their forces is limited. However, one tenet of combat always holds true -- striking down those that issue the orders will weaken the foe much greater than the rank and file. I have observed that the larger faceless minions act as commanders of the Old Gods' forces. Silence them, and perhaps we can sow a different kind of chaos in their ranks.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1755,amount=325},{id=1553,amount=301},{id=1553,amount=314},{id=1553,amount=415}},starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Order Among Chaos",db2QuestInfoID=1,db2QuestInfoName="Group"},
[58233] = {id=58233,name="Twisted Corruptors",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=9105,mapID=1527,description="While the fleshbeasts that accompany the invading forces appear to be no more than a nuisance, they carry within themselves a deep connection to the corrupting powers of the Old Gods. Like a pestilence, they spread the N'Zoth's corruption wherever they tread, slowly twisting the very land to their form. They must be eradicated.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1755,amount=325},{id=1553,amount=307},{id=1553,amount=310},{id=1553,amount=334}},starts={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={x=0.546,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Twisted Corruptors"},
[58234] = {id=58234,name="Questionable Sourcing",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=9105,mapID=1527,description="My clairvoyance provides a great strategic asset to the people of Ramkahen. However, the potency of my visions of late has proven taxing to my health. I have devised a tonic that may serve to dull the harm these visions cause, but it will require the coalesced essence of the Old Gods' corruption. If you could retrieve some samples of this for me, it could prove invaluable in our efforts.",rewardGold=234000,rewardXP=6815,rewardItems={173956},rewardCurrencies={{id=1755,amount=325},{id=1553,amount=311},{id=1553,amount=317},{id=1553,amount=321}},starts={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={x=0.546,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Questionable Sourcing"},
[58235] = {id=58235,name="Anchors of the Black Empire",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="This invasion struck us without warning, with structures reminiscent of the Black Empire materializing out of nothing, pouring out the forces of the Old Gods. We have no idea how they came to be or where they came from. However, whenever a new structure appears, it is preceded by malefic obelisks. We believe these obelisks act as anchors to usher in more of the Old Gods' forces. If we truly wish to stem the tide of this invasion, we must destroy the obelisks.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1755,amount=325},{id=1553,amount=303},{id=1553,amount=377},{id=1553,amount=382}},starts={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},ends={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},coords={x=0.548,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Anchors of the Black Empire"},
[58236] = {id=58236,name="Symbolic Destruction",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The cultists that follow this dark legion befoul our lands with symbols of the tyrants they follow. Their mindless followers flock to these banners, worshipping them as unholy idols. Burn them down, and cleanse their taint from our lands.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1755,amount=325},{id=1553,amount=328},{id=1553,amount=345},{id=1553,amount=361}},starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Symbolic Destruction"},
[58237] = {id=58237,name="Cleansing Uldum",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Every moment that N'Zoth's forces remain in Uldum , his corruption seeps further into the land itself. Even if we were to drive back his minions, the damage he has done to Uldum may be irreversible. We must seek out his corruption where it festers and eliminate it.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1560,amount=60},{id=1755,amount=325},{id=1553,amount=300},{id=1553,amount=305}},starts={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={x=0.546,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Cleansing Uldum"},
[58238] = {id=58238,name="Lost and Tormented",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Our citizens here in Ramkahen have managed to escape the brunt of N'Zoth's assault. Our brothers in the Lost City were not so fortunate. Those not immediately slain have been held captive only to be tortured by N'Zoth's minions. I know that you will be taking the fight to N'Zoth's forces. If you can free our allies as well, Ramkahen will be in your debt.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1755,amount=325},{id=1553,amount=326},{id=1553,amount=329},{id=1553,amount=339}},starts={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},ends={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},coords={x=0.548,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Lost and Tormented"},
[58239] = {id=58239,name="Lessons in Brigandry",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The Wastewanders have spent many generations as brigands, whether on land or sea. Though we have decided to hang up that life for a chance at a more peaceful existence, we have not forgotten the lessons we've learned in those days. One such lesson I feel is particularly relevant now -- when faced with a superior opponent, it often helps to use their weapons against them. Find their hidden caches and take whatever you can carry. You may just find something that can turn the tide of this battle.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1755,amount=325},{id=1553,amount=302},{id=1553,amount=310},{id=1553,amount=317}},starts={{npcID=160957,x=0.546,y=0.34,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.546,y=0.34,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Lessons in Brigandry"},
[58277] = {id=58277,name="Dark Deceivers",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=9105,mapID=1527,description="The Old Gods have many faceless minions at their disposal, but none so deceiving as the ones they call k'thir. Though not nearly as imposing as their brethren, the k'thir manipulate in the shadows, bending the wills of men and even reality itself. We must not allow their machinations to go unchecked.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1755,amount=325},{id=1553,amount=303},{id=1553,amount=330},{id=1553,amount=338}},starts={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={x=0.546,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Dark Deceivers"},
[58281] = {id=58281,name="Ancient Armaments",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Fighting a war on several fronts has taken its toll on our supplies. Our blacksmiths cannot repair and replace our soldiers' armor quickly enough, which is leaving us ill-equipped to face so many foes. Though the Amathet's armor is ancient, it is titan-forged and formidable. If we were able to salvage any, it could prove very useful to our defensive efforts. Can you help?",rewardGold=234000,rewardXP=6815,rewardItems={173985},rewardCurrencies={{currencyID=1755,quantity=1}},starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Ancient Armaments"},
[58282] = {id=58282,name="Down From the Sky",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The archers of Ramkahen are highly skilled, but the bows of the Amathet have the advantage of range. This makes our incursions into their territory highly dangerous. You have a knack for fighting behind enemy lines. If you could thin out their ranks, it could provide us an opportunity to push their lines back for once. Will you help?",rewardGold=309800,rewardXP=6815,rewardCurrencies={{id=1560,amount=60},{id=1755,amount=325},{id=1553,amount=300},{id=1553,amount=301}},starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Down From the Sky"},
[58283] = {id=58283,name="Blind Leading the Blind",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The Sun Priests are an ancient order for the tol'vir who have walked among all of the tribes. Those that follow the Amathet, however, have twisted our beliefs and weaponized them to justify their crusade against Ramkahen. Their soldiers follow them blindly, never questioning. They must be stopped.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1755,amount=325},{id=1553,amount=302},{id=1553,amount=317},{id=1553,amount=321}},starts={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={x=0.546,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Blind Leading the Blind"},
[58284] = {id=58284,name="Writs of the Sun King",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Very little is known about the Sun King that leads the Amathet. Our observations suggest that those closest to him are the \"Suntouched,\" a unique caste of solar magic practitioners. I would like very much to learn more about this Sun King but, unlike some members of the Explorers' League, I'm not willing to risk the lives of my researchers to do so. You seem to be able to hold your own, though. If you happen upon any records about the Sun King, I'd gladly take them off your hands.",rewardGold=234000,rewardXP=6815,rewardItems={173986},rewardCurrencies={{currencyID=1755,quantity=1}},starts={{npcID=155102,x=0.55,y=0.33,zoneID=10833}},ends={{npcID=155102,x=0.55,y=0.33,zoneID=10833}},coords={x=0.55,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Writs of the Sun King"},
[58285] = {id=58285,name="Unearthed Artifacts",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Ever since the Amathet came out of their tombs, they've been busy unearthing titan relics from the surrounding areas. I'm not sure what they intend to do with them or if they're just hoarding it so we can't have them. Sufficed to say the Explorers' League would love to study some of what they found! Of course, we can't get anywhere close to them without the Amathet trying to stick an axe in us, but that's not a problem for you, is it? Care to help?",rewardGold=234000,rewardXP=6815,rewardItems={168043},rewardCurrencies={{id=1755,amount=325},{id=1553,amount=304},{id=1553,amount=307},{id=1553,amount=320}},starts={{npcID=155102,x=0.55,y=0.33,zoneID=10833}},ends={{npcID=155102,x=0.55,y=0.33,zoneID=10833}},coords={x=0.55,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Unearthed Artifacts"},
[58286] = {id=58286,name="Far From Home",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The Amathet's conquest of eastern Uldum was sudden, and we were unable to reach some of our farthest settlements in time. Fortunately, many of the tol'vir who lived in the conquered territories were not killed, instead being put to work under the Amathet's whip. We must take any opportunity we can to free them and return them to their homes.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{currencyID=1755,quantity=1}},starts={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Far From Home"},
[58287] = {id=58287,name="A Smashing Plan",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Reports from my scouts mention various idols and monuments that the Amathet use to channel their solar magic. I don't know exactly what they're up to, but we should take away any possible advantage they have. So, I want you to go over there, and break anything that looks remotely magical. Just don't tell the Explorers' League. I'll never hear the end of it.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{currencyID=1755,quantity=1}},starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="A Smashing Plan"},
[58288] = {id=58288,name="The Sun King's Chosen",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="On the surface the Amathet appear to be unwavering, but all soldiers have their breaking point. We need to send a message to their forces that we are not to be trifled with. Seek out the strongest of their numbers and bring them down in front of their eyes. We will show them the strength of Uldum !",rewardGold=234000,rewardXP=6815,rewardCurrencies={{currencyID=1755,quantity=1}},starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="The Sun King's Chosen"},
[58289] = {id=58289,name="Guarded Secrets",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="From what we know about the Amathet, they must've been locked away in their tombs for thousands of years. Just think of what we could learn from them! Of course, that would be a lot easier if they weren't trying to kill us. If you happen upon any caches of Amathet relics in your travels, let me know. I'd love to see what sort of mysteries they contain!",rewardGold=234000,rewardXP=6815,rewardCurrencies={{currencyID=1755,quantity=1}},starts={{npcID=155102,x=0.55,y=0.33,zoneID=10833}},ends={{npcID=155102,x=0.55,y=0.33,zoneID=10833}},coords={x=0.55,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Guarded Secrets"},
[58290] = {id=58290,name="Champions of the Amathet",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The soldiers of Ramkahen are hearty and reliable. I would stand them up against any footman of the Amathet, but some of their higher-caste fighters are too much for even our toughest to handle. I don't think they'd be a problem for you, though. It would be a boon to our defense efforts if you could handle them while my soldiers engage the rank and file.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{currencyID=1755,quantity=1}},starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Champions of the Amathet",db2QuestInfoID=1,db2QuestInfoName="Group"},
[58291] = {id=58291,name="Encroaching Poachers",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The Wastewanders used the pelts of the local hyenas to construct our armor. Unfortunately since the Amathet arrived, their hunters have overrun our normal hunting grounds. We need those pelts, and will pay handsomely for them. Either take them from the hunters or skin the hyenas yourself, if you have the skill.",rewardGold=234000,rewardXP=6815,rewardItems={174008},rewardCurrencies={{id=1755,amount=325},{id=1553,amount=308},{id=1553,amount=310},{id=1553,amount=346}},starts={{npcID=160957,x=0.546,y=0.34,zoneID=10833}},ends={{npcID=160957,x=0.546,y=0.34,zoneID=10833}},coords={x=0.546,y=0.34,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Encroaching Poachers"},
[58321] = {id=58321,name="Uncommon Core",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Our scouts have reported that the Amathet are constructing new titanic watchers. We had long thought this art was lost to the sands of time. It would appear we were mistaken. I needn't tell you what a boon it would be to have the aid of watcher constructs in our battles for Uldum . We must unlock the secrets of their construction! The power of a titanic watcher lies in its core. I ask that you bring one to me, so that our artificers might divine its construction.",rewardGold=234000,rewardXP=6815,rewardItems={174009},rewardCurrencies={{currencyID=1755,quantity=1}},starts={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},ends={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},coords={x=0.548,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Uncommon Core",db2QuestInfoID=1,db2QuestInfoName="Group"},
[58742] = {id=58742,name="Retinus the Seeker",expansion=0,mapID=1527,questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2854,text="Defeat Retinus the Seeker"}},worldTaskTitle="Retinus the Seeker",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[58743] = {id=58743,name="Dune Buggy",expansion=0,mapID=1527,questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2856,text="Defeat Aqir Sandcrawler"}},worldTaskTitle="Dune Buggy",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[58744] = {id=58744,name="I Am The One Who Whispers",expansion=0,mapID=1527,questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2855,text="Defeat Whispers"}},worldTaskTitle="I Am The One Who Whispers",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[58745] = {id=58745,name="Watch Where You Step",expansion=0,mapID=1527,questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2857,text="Defeat Blotto"}},worldTaskTitle="Watch Where You Step",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[58776] = {id=58776,name="Hatching Problems",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The aqir are multiplying faster than we can put them down. If this pace continues, we will be outnumbered before long. The only way to slow down their assault is to attack their hives directly and destroy their eggs, but we have been unsuccessful in doing so. That's why I wish to conscript your services. Will you help?",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1755,amount=325},{id=1553,amount=302},{id=1553,amount=331},{id=1553,amount=354}},starts={{npcID=154443,x=0.4,y=0.212,zoneID=10833}},ends={{npcID=154443,x=0.4,y=0.212,zoneID=10833}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Hatching Problems"},
[58777] = {id=58777,name="Put Your Foot Down",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="You see that? Doesn't look like much, but believe it or not, those bugs grow out of these things. They're all over the places the aqir have taken over, feeding off of our dead and growing into these monstrosities. If you happen to see any of them, do the world a favor and take your boot to 'em.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1755,amount=325},{id=1553,amount=312},{id=1553,amount=319},{id=1553,amount=364}},starts={{npcID=159920,x=0.4,y=0.212,zoneID=10833}},ends={{npcID=159920,x=0.4,y=0.212,zoneID=10833}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Put Your Foot Down"},
[58778] = {id=58778,name="Getting Ahead",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Morale's been down at the camp lately. Funny how getting chewed on by some bugs can spoil the mood of a place. I've got an idea to perk the troops back up, though. We need a trophy! See if you can get me the head of one of those big tanky-looking ones so we can put it on display to show these bugs that we mean business! Just try to make sure it's not too mangled, okay?",rewardGold=234000,rewardXP=6815,rewardItems={174776},rewardCurrencies={{id=1755,amount=325},{id=1553,amount=315},{id=1553,amount=360},{id=1553,amount=361}},starts={{npcID=159920,x=0.4,y=0.212,zoneID=10833}},ends={{npcID=159920,x=0.4,y=0.212,zoneID=10833}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Getting Ahead",db2QuestInfoID=1,db2QuestInfoName="Group"},
[58779] = {id=58779,name="Taking the Skies",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="I'd like to see if we can get some more of these flyers in the air to drive back the aqir, but it's nearly impossible to get back to the Obelisk of the Sun with all these bugs in the air. I think we're going to have to thin them out on the ground before we can hope to gain aerial superiority. Can I count on you to lend a hand?",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1755,amount=325},{id=1553,amount=339},{id=1553,amount=402},{id=1553,amount=445}},starts={{npcID=159920,x=0.4,y=0.212,zoneID=10833}},ends={{npcID=159920,x=0.4,y=0.212,zoneID=10833}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Taking the Skies"},
[58780] = {id=58780,name="Heralds of the Hive",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The aqir that have assaulted our camp seem to mainly consist of their shock troops. However, our scouts who dare venture behind their lines have spotted a different kind of creature -- tall and thin, wielding dangerous void magic. My instinct tells me that these creatures are the leaders behind this invasion. They should be seen as targets of opportunity, and cut down wherever they're met. Are you up to the task?",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1553,amount=389},{id=1560,amount=60},{id=1755,amount=325},{id=1553,amount=321}},starts={{npcID=154443,x=0.4,y=0.212,zoneID=10833}},ends={{npcID=154443,x=0.4,y=0.212,zoneID=10833}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Heralds of the Hive",db2QuestInfoID=1,db2QuestInfoName="Group"},
[58781] = {id=58781,name="Terrors from the Deep",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The Aqir threaten the livelihood of the Wastewanders with each passing day, but I have heard of greater terrors that have been unearthed with them. Our fighters are able, but I fear what might happen if one of these ancient terrors falls upon us. I know that you have experience putting down great foes. I would like to ask you to do the same for us. After all, we can hardly help protect the forge if we've been decimated by some long-buried monster.",rewardGold=234000,rewardXP=6815,rewardCurrencies={{id=1560,amount=50},{id=1755,amount=325},{id=1553,amount=317},{id=1553,amount=434}},starts={{npcID=159544,x=0.4,y=0.212,zoneID=10833}},ends={{npcID=159544,x=0.4,y=0.212,zoneID=10833}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Terrors from the Deep"},
[58782] = {id=58782,name="Things Left Behind",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The invading aqir forced the Wastewanders to flee many of our settlements in Uldum . In our haste to escape, much was left behind. I understand you intend to take the fight to the beasts. While you're there, could you keep an eye out for any of the supplies we had to leave behind? You can keep anything of use to you, of course.",rewardGold=234000,rewardXP=6815,rewardItems={174774},rewardCurrencies={{id=1755,amount=325},{id=1553,amount=357},{id=1553,amount=413},{id=1553,amount=437}},starts={{npcID=159544,x=0.4,y=0.212,zoneID=10833}},ends={{npcID=159544,x=0.4,y=0.212,zoneID=10833}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Things Left Behind"},
[60542] = {id=60542,name="Nathanos Blightcaller",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=139,mapID=23,questType="world",worldTaskTitle="Nathanos Blightcaller",db2QuestInfoID=112,db2QuestInfoName="Epic Elite World Quest"},
