[78178] = {id=78178,name="To Gilneas",expansion=0,mapID=217,questType="world",worldTaskTitle="To Gilneas"},
[78180] = {id=78180,name="A Crusade of Red",expansion=0,mapID=217,questType="world",worldTaskTitle="A Crusade of Red"},
[78181] = {id=78181,name="Aderic's Retort",expansion=0,mapID=217,questType="world",worldTaskTitle="Aderic's Retort"},
[78182] = {id=78182,name="Knee-High",expansion=0,mapID=217,questType="world",worldTaskTitle="Knee-High"},
[78183] = {id=78183,name="Scarlet Blood",expansion=0,mapID=217,questType="world",worldTaskTitle="Scarlet Blood"},
[81886] = {id=81886,name="For the Alliance",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1519,mapID=84,description="For the first time in our history, the outside world is ours to explore and experience. An off-island faction known as the Alliance came to the aid of our kin. Valiant and wise, the stalwart Alliance has extended an open hand to our people. Will you be among the first to accept and visit their lands, learn their histories and walk amongst their people? If that path calls to you, then I hope you'll return to share those experiences and show the earthen what the world has to offer.",rewardGold=34100,rewardXP=175,ends={{npcID=133362,x=0.532,y=0.152,zoneID=1519}},questType="world",worldTaskTitle="For the Alliance"},
[81887] = {id=81887,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1637,mapID=84,description="Welcome to Stormwind, . I invite you to explore our fair city. Say, you look like someone who appreciates fine stonework! We have many impressive stone buildings and walls. Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, !",rewardGold=34100,rewardXP=175,rewardItems={224241,224242,224243,224244,224245,224246,224247,224248,224249},starts={{npcID=133362,x=0.532,y=0.152,zoneID=1519}},ends={{npcID=224806,x=0.56,y=0.174,zoneID=1519}},coords={x=0.532,y=0.152,source="quest_giver",zoneID=1519},questType="world",worldTaskTitle="Stranger in a Strange Land"},
[81888] = {id=81888,name="For the Horde",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,mapID=85,description="For the first time in our history, the outside world is ours to explore and experience. An off-island faction known as the Horde came to the aid of our kin. Spiritual and mighty, the honorable Horde has opened their hand to our people. Will you be among the first to go where no earthen has ever gone? To walk their lands, hear their songs and learn from their people? If that path calls to you, then I hope you'll return to share those experiences and show the earthen what the world has to offer.",rewardGold=200,rewardXP=175,ends={{npcID=133407,x=0.394,y=0.792,zoneID=1637}},questType="world",worldTaskTitle="For the Horde"},
[81889] = {id=81889,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1519,mapID=85,description="Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, . As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.",rewardGold=200,rewardXP=175,rewardItems={224241,224242,224243,224244,224245,224246,224247,224248,224249},starts={{npcID=133407,x=0.394,y=0.792,zoneID=1637}},ends={{npcID=224807,x=0.406,y=0.802,zoneID=1637}},coords={x=0.394,y=0.792,source="quest_giver",zoneID=1637},questType="world",worldTaskTitle="Stranger in a Strange Land"},
