[82672] = {id=82672,name="Another Timely Invitation",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=440,mapID=84,description="The bronze dragonflight is throwing a celebration just outside the Caverns of Time in Tanaris! There are all sorts of new activities to partake in that honor and remember what has transpired over the years. Head to Tanaris and join in the festivities.",rewardGold=30900,rewardXP=175,starts={{npcID=224334,x=0.498,y=0.71,zoneID=1519},{npcID=224419,x=0.478,y=0.78,zoneID=1637}},ends={{npcID=223877,x=0.628,y=0.506,zoneID=440}},coords={x=0.498,y=0.71,source="quest_giver",zoneID=1519},questType="world",worldTaskTitle="Another Timely Invitation"},
[84236] = {id=84236,name="The Great Detective",level=10,requiredLevel=30,faction="both",expansion=0,zoneID=440,mapID=71,description="Adventurer, thank the Light you are here. We have a missing guest. There was a detective who was investigating the case, but I have not heard back. Could you please check in with him?",rewardGold=34100,rewardXP=175,starts={{npcID=226683,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226796,x=0.61,y=0.506,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="world",worldTaskTitle="The Great Detective"},
[84334] = {id=84334,name="Warn the Detective",level=10,requiredLevel=30,faction="both",expansion=0,zoneID=440,mapID=71,description="Welcome back, . I saw the detective headed west. Hurry up and warn him before the shapeshifter comes for him too!",rewardGold=34100,rewardXP=175,starts={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232405,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226796,x=0.61,y=0.506,zoneID=440},{npcID=228661,x=0.61,y=0.506,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="world",worldTaskTitle="Warn the Detective"},
[84424] = {id=84424,name="Forward, to Adventure!",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=1637,mapID=85,description="We are free, . Free to do whatever it is we wish. Through the portal lies the rest of your life. A member of the bronze dragonflight will help you on your journey.",rewardGold=309800,rewardXP=1415,rewardItems={229165},starts={{npcID=229075,x=0.43,y=0.898,zoneID=15510}},ends={{npcID=167032,x=0.56,y=0.172,zoneID=1519},{npcID=167032,x=0.408,y=0.8,zoneID=1637}},coords={x=0.43,y=0.898,source="quest_giver",zoneID=15510},questType="world",worldTaskTitle="Forward, to Adventure!"},
[84563] = {id=84563,name="Toy Trouble",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=440,mapID=71,description="Adventurer, Maru is once again in need of your aid. She has an urgent matter that she would like to discuss with you.",rewardGold=34100,rewardXP=175,starts={{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232405,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226684,x=0.632,y=0.524,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="world",worldTaskTitle="Toy Trouble"},
[84755] = {id=84755,name="The Final Toy",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=440,mapID=71,description="Maru discovered that one of her toys is now missing! Could this be related to the other missing toys that you previously helped her friends with?",rewardGold=34100,rewardXP=175,starts={{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232405,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226684,x=0.632,y=0.524,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="world",worldTaskTitle="The Final Toy"},
