[85026] = {id=85026,name="Where Legends are Made",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=1637,mapID=85,description="There's so much to catch you up on ! Where do you want to start?",rewardGold=2000,rewardXP=1415,starts={{npcID=167032,x=0.56,y=0.172,zoneID=1519},{npcID=167032,x=0.408,y=0.8,zoneID=1637}},ends={{npcID=167032,x=0.56,y=0.172,zoneID=1519},{npcID=167032,x=0.408,y=0.8,zoneID=1637}},coords={x=0.56,y=0.172,source="quest_giver",zoneID=1519},questType="world",worldTaskTitle="Where Legends are Made"},
