[85475] = {id=85475,name="Secret in the Sands",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=440,mapID=71,description="Welcome back. Maru is looking for you again. She says only you have the skills to help her with this task. Oh, don't worry about me. I'll be here... As always...",rewardGold=34100,rewardXP=175,starts={{npcID=232406,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440},{npcID=232408,x=0.63,y=0.502,zoneID=440},{npcID=232410,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226684,x=0.632,y=0.524,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="world",worldTaskTitle="Secret in the Sands"},
[85502] = {id=85502,name="Festive Reflections",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=440,mapID=71,description="Oh good, you're back. I have my hands full here and Detective Jones has been asking for your help on some new case. Not that it seems to matter. For all the good we do for the guests, I think this line--if you can still call it that--has only grown longer! I should get back to it, and you should talk to Detective Jones.",rewardGold=30900,rewardXP=175,starts={{npcID=232406,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440},{npcID=232408,x=0.63,y=0.502,zoneID=440},{npcID=232410,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226796,x=0.61,y=0.506,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="world",worldTaskTitle="Festive Reflections"},
[86822] = {id=86822,name="One Final Relic",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="$p, I've asked the Sons of Lothar to meet us in the Burning Steppes near Blackrock Mountain. There's one more item we must recover there. We can depart as soon as you are ready.",rewardGold=33500,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=240747,x=0.686,y=0.32,zoneID=45}},ends={{npcID=242120,x=0.334,y=0.484,zoneID=46}},coords={x=0.686,y=0.32,source="quest_giver",zoneID=45},questType="world",worldTaskTitle="One Final Relic"},
[86823] = {id=86823,name="The Dark Horde",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="I once served under Blackhand, long ago. His son Rend was a sniveling fool: a coward who bolstered himself in that Spire after Doomhammer was defeated. He made deals with dragons, called himself Warchief, and proclaimed his Dark Horde the \"true\" Horde. Pah! This Dark Horde embraces the ideals of a past long gone. Rend died years ago, but there are still orcs and ogres here who cling to the rotting husk that remains. If they haven't seen the truth by now, there is little hope for them but death.",rewardGold=319000,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=237224,x=0.334,y=0.486,zoneID=46}},ends={{npcID=237224,x=0.334,y=0.486,zoneID=46}},coords={x=0.334,y=0.486,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="The Dark Horde"},
[86824] = {id=86824,name="None Left Standing",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="The one thing worse than seeing this Dark Horde here is their banners. It showcases their pride in this accursed mountain as a place of greatness--as a place for their horde to rise. In reality, this banner is little more than a defiled perversion of the ancestral Blackrock sigil. Burn down every one you find.",rewardGold=315900,rewardXP=12170,rewardItems={239130},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=237224,x=0.334,y=0.486,zoneID=46}},ends={{npcID=237224,x=0.334,y=0.486,zoneID=46}},coords={x=0.334,y=0.486,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="None Left Standing"},
[86825] = {id=86825,name="Faithful Servant, Faithless Cause",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="One of their lieutenants, Mar'kag , appears to be the one barking orders. His father, High Overlord Omokk, followed under Rend Blackhand's banner. Cruel, vicious... no surprise that his son follows in his footsteps. Taking Mar'kag down will spread chaos among the cowardly remnants of this Dark Horde and perhaps help them realize they are not as strong as they think. Faol also has us here to look for relic fragments. If Mar'kag has anything of note, bring it back.",rewardGold=683200,rewardXP=15215,rewardItems={246704,251829,251830,251831,251832},rewardCurrencies={{id=3316,amount=20},{id=3365,amount=100}},starts={{npcID=237224,x=0.334,y=0.486,zoneID=46}},ends={{npcID=237224,x=0.334,y=0.486,zoneID=46}},coords={x=0.334,y=0.486,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="Faithful Servant, Faithless Cause"},
[86826] = {id=86826,name="Nagosh the Scarred",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=51,mapID=36,description="The Dark Horde may strut around inside the mountain, but an orc called Nagosh is the one rulin' this roost. He barks orders, then charges straight into a fight. Rock-heads in command like that one are what gets everyone on all sides killed. I'd bet anything that numbskull claimed Faol's shiny relic. Keep an eye out. He may jump ye in the middle of a fight.",rewardGold=638000,rewardXP=15215,rewardItems={246699,251826,251828},rewardChoices={251826,251828},rewardCurrencies={{id=3316,amount=20},{id=3365,amount=100}},starts={{npcID=237268,x=0.212,y=0.398,zoneID=46}},ends={{npcID=237268,x=0.212,y=0.398,zoneID=46}},coords={x=0.212,y=0.398,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="Nagosh the Scarred"},
[86827] = {id=86827,name="Due Recognition",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=51,mapID=36,description="Blackrock Mountain is where most of the Dark Horde has holed up. All their unit commanders adorn themselves with badges, struttin' around like they won the Second War. Shameful! But it gives me an idea. Defeat them and take their badges. Can't have new leaders that way--these blowhards like the pomp of command. Who wants the stress of leadership with no fancy badge to wear? Head on in there with Arator and keep 'em busy. Sky'reen an' I will support ye from the air.",rewardGold=331700,rewardXP=12170,rewardItems={247218},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=237268,x=0.212,y=0.398,zoneID=46}},ends={{npcID=237268,x=0.212,y=0.398,zoneID=46}},coords={x=0.212,y=0.398,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="Due Recognition"},
[86828] = {id=86828,name="Not Just a Troll's Bane",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="As much as I'd love to keep harassing these Dark Horde grunts, we've found the relic piece that Faol wanted us to. We best be getting on. Danath went looking for the last piece of the relic. You go find him, and I'll tell the mad bishop that his plan is nearly complete. Find me at Lothar's Statue when yer done.",rewardGold=31900,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=237268,x=0.212,y=0.398,zoneID=46}},ends={{npcID=242120,x=0.334,y=0.484,zoneID=46}},coords={x=0.212,y=0.398,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="Not Just a Troll's Bane"},
[86829] = {id=86829,name="A Landmark Moment",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="With their leader defeated and that third relic fragment found, we should regroup with the others back at Lothar's Statue, $p. I'll meet you there.",rewardGold=335000,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=242120,x=0.334,y=0.484,zoneID=46}},ends={{npcID=248263,x=0.368,y=0.508,zoneID=46}},coords={x=0.334,y=0.484,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="A Landmark Moment"},
[86830] = {id=86830,name="A True Horde of Dark Horde",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="The remaining Dark Horde forces are gathered here, $p. Many of them look to be untrained and new to the cause. Drive away the forces gathered here, and perhaps we can hope to see some peace in this region--for the first time in decades.",rewardGold=315900,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=242120,x=0.334,y=0.484,zoneID=46}},ends={{npcID=242120,x=0.334,y=0.484,zoneID=46}},coords={x=0.334,y=0.484,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="A True Horde of Dark Horde"},
[86831] = {id=86831,name="Warriors Without a Warlord",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="Despite our work in the area, the Dark Horde continues to battle. Their leader is there, in Blackrock Stronghold, likely bolstering their spirits. Take them out. Once we do, I suspect this Dark Horde will come to nothing, with much less bloodshed. And Faol thinks there may be a fragment of the relic he's looking for in there. Recover that as well!",rewardGold=683200,rewardXP=15215,rewardItems={235625,251822,251823,251824,251825},rewardCurrencies={{id=3316,amount=20},{id=3365,amount=100}},starts={{npcID=242120,x=0.334,y=0.484,zoneID=46}},ends={{npcID=242120,x=0.334,y=0.484,zoneID=46}},coords={x=0.334,y=0.484,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="Warriors Without a Warlord"},
[86839] = {id=86839,name="Relics of Light's Hope",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=139,mapID=23,description="The holy power in my staff has been spent. Forty years of fervent prayers drained away in a few minutes. It was for a good cause, and my staff will recover in time. There are other relics, like my staff, that were important to paladins and priests. Light's Hope Chapel has many such relics stored there. Arator trained there as well. Perhaps the solution to his pain could also be found within.",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=240240,x=0.528,y=0.552,zoneID=16215}},ends={{npcID=237594,x=0.738,y=0.536,zoneID=139}},coords={x=0.528,y=0.552,source="quest_giver",zoneID=16215},questType="world",worldTaskTitle="Relics of Light's Hope"},
[86840] = {id=86840,name="Flickering Hope",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=139,mapID=23,description="Normally, $p, paladins from Light's Hope hold back the Scourge in the immediate area around the chapel, but they've all been called to fight the Void. As a result, Scourge forces have greatly increased their numbers around the chapel. We've managed to hold the line so far, but only with the help of Darion and the Ebon Blade. Give us some room to breathe--defeat as many of them as you can.",rewardGold=309800,rewardXP=12170,rewardItems={251719,251720,251721,251722},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=237594,x=0.738,y=0.536,zoneID=139}},ends={{npcID=237594,x=0.738,y=0.536,zoneID=139}},coords={x=0.738,y=0.536,source="quest_giver",zoneID=139},questType="world",worldTaskTitle="Flickering Hope"},
[86841] = {id=86841,name="Relics of Paladins Past",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=139,mapID=23,description="Alonsus tells me you're looking for relics of holy power, to sustain those performing the ritual holding the Void at bay. Now that you've beaten back the Scourge, you and Arator are certainly welcome to enter the Sanctum of Light and use what we have for the cause.",rewardGold=319000,rewardXP=12170,rewardItems={237513,237518,237519,237573,237574},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=237594,x=0.738,y=0.536,zoneID=139}},ends={{npcID=237594,x=0.738,y=0.536,zoneID=139}},coords={x=0.738,y=0.536,source="quest_giver",zoneID=139},questType="world",worldTaskTitle="Relics of Paladins Past"},
[86842] = {id=86842,name="Scarlet Power",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=85,mapID=2438,description="These artifacts will help sustain the Vanguard, but they are not enough. I know of a place nearby that would have the rest we need, but... given Arator 's state of mind, I'm hesitant to go there. Hmph... No sense in avoiding it. We must all face up to the fact that the Scarlet Crusade calls upon the power of the Light, and has for decades.",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=237601,x=0.738,y=0.534,zoneID=139}},coords={x=0.738,y=0.534,source="quest_giver",zoneID=139},questType="world",worldTaskTitle="Scarlet Power"},
[86843] = {id=86843,name="Light Miswielded",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=85,mapID=2438,description="The Scarlet Crusade has been wielding the Light for its evil purposes for decades, $p. I'm disappointed to see how many forces they still have here. Still, the Light responds to them, just as it does to us. We're here to get their relics to help the Sunwell, but while we're here, let's cleanse this place of their dark influence.",rewardGold=328500,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},questType="world",worldTaskTitle="Light Miswielded"},
[86844] = {id=86844,name="Light Repurposed",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=85,mapID=2438,description="Leaders of the Crusade have channeled the Light through their weapons every day for years. While their goals and actions are reprehensible to us, their weapons are no less useful than my own staff, especially in such a time of need. As you go through the Scarlet Halls, whenever you find a leader, defeat them and bring back their weapon. We will put it to a righteous use: to aid the Sunwell.",rewardGold=683200,rewardXP=15215,rewardItems={237576,237579,237761,251724,251725,251726,251727,251728,251729,251730,251731,251732,251733,251734},rewardChoices={251724,251725,251726,251727,251728,251729,251730,251731,251732,251733,251734},rewardCurrencies={{id=3316,amount=20},{id=3365,amount=100}},questType="world",worldTaskTitle="Light Repurposed"},
[86845] = {id=86845,name="The Sunwalker Path",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=15969,mapID=2372,description="I think I have failed Arator. In my attempt to steady him after the incident with his father, I may have shattered his faith with uncomfortable truths of the Light. I would like to consult with the wisest person I know, Sunwalker Dezco . I did not see him with the Vanguard. Tyrosus told me he may be in Hammerfall providing aid to the displaced.",rewardGold=167500,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=251355,x=0.526,y=0.558,zoneID=16215}},ends={{npcID=245186,x=0.69,y=0.376,zoneID=45}},coords={x=0.526,y=0.558,source="quest_giver",zoneID=16215},questType="world",worldTaskTitle="The Sunwalker Path"},
[86846] = {id=86846,name="Resupplying Our Suppliers",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=45,mapID=2372,description="$p, the people of Hammerfall were attacked not so long ago by saboteurs from a group called the Red Dawn. I am working to help them recover and rebuild from the attack with my fellow Sunwalkers: Malu and Nadura. One thing they have been doing is gathering supplies needed by Hammerfall's crafters from various sources. If you could deliver these supplies, it would be a great help.",rewardGold=319000,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=245186,x=0.69,y=0.376,zoneID=45}},ends={{npcID=247299,x=0.686,y=0.322,zoneID=45}},coords={x=0.69,y=0.376,source="quest_giver",zoneID=45},questType="world",worldTaskTitle="Resupplying Our Suppliers"},
[88771] = {id=88771,name="Loaknit Alphas!",expansion=0,mapID=13,questType="world",worldTaskTitle="Loaknit Alphas!"},
[88772] = {id=88772,name="Mammoth Remnants!",expansion=0,mapID=13,questType="world",worldTaskTitle="Mammoth Remnants!"},
[88804] = {id=88804,name="Defeat the Mineraw!",expansion=0,mapID=13,questType="world",worldTaskTitle="Defeat the Mineraw!"},
[89338] = {id=89338,name="Gathering Plowshares",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=45,mapID=2372,description="$p, now that Hammerfall can expect peace with Stromgarde, there's a lot more use in being able to farm and craft than in fighting. So, we've been gathering old weapons from past skirmishes to make into tools for the people of Hammerfall. Would you and Arator be willing to give me a hand?",rewardGold=335000,rewardXP=12170,rewardItems={238515,238516},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=247299,x=0.686,y=0.322,zoneID=45}},ends={{npcID=247299,x=0.686,y=0.322,zoneID=45}},coords={x=0.686,y=0.322,source="quest_giver",zoneID=45},questType="world",worldTaskTitle="Gathering Plowshares"},
[90128] = {id=90128,name="Miscreant Baras!",expansion=0,mapID=13,questType="world",worldTaskTitle="Miscreant Baras!"},
[90961] = {id=90961,name="Stranger in a New Land",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=1637,mapID=85,description=", I see you now for who you are. You are dedicated not just to our people, but to the world. The goddess has acknowledged you as well, and I can not recall such an event--not even Orweyna's ceremony was so eventful. This is where your story begins. It is time for you to take the first steps of your journey.",rewardGold=341600,rewardXP=1415,rewardItems={246740,246795},starts={{npcID=245097,x=0.318,y=0.274,zoneID=15355}},ends={{npcID=133362,x=0.532,y=0.152,zoneID=1519},{npcID=133407,x=0.394,y=0.792,zoneID=1637}},coords={x=0.318,y=0.274,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Stranger in a New Land"},
[91000] = {id=91000,name="A Humble Servant",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=45,mapID=2372,description="$p, residents of Hammerfall have been focused on daily life, defense, and survival over the past months. They have not had sufficient time, or frankly numbers, to address all the harms that were done. There is much we can do to help them get back on their feet. I know this is humble work, but it makes a very real difference to the orcs who live here.",rewardGold=341600,rewardXP=12170,rewardItems={251816,251817,251818,251819},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=245186,x=0.69,y=0.376,zoneID=45}},ends={{npcID=245186,x=0.69,y=0.376,zoneID=45},{npcID=247299,x=0.686,y=0.322,zoneID=45}},coords={x=0.69,y=0.376,source="quest_giver",zoneID=45},questType="world",worldTaskTitle="A Humble Servant"},
[91391] = {id=91391,name="Still Scouting",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="When the Alliance originally fought the Horde here, Kurdran served as a scout. He's still an excellent one. He took his gryphon to Blackrock Mountain to see what kind of forces we may be dealing with there. Meet up with him and see what kind of trouble you can cause.",rewardGold=31900,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=237224,x=0.334,y=0.486,zoneID=46}},ends={{npcID=237268,x=0.212,y=0.398,zoneID=46}},coords={x=0.334,y=0.486,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="Still Scouting"},
[91429] = {id=91429,name="Mausoloa Sarcophagi!",expansion=0,mapID=13,questType="world",worldTaskTitle="Mausoloa Sarcophagi!"},
[91726] = {id=91726,name="Unstoppable Force",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="This statue seems out of place here. Nothing else like it. But this is where Anduin Lothar fell against Orgrim Doomhammer at the Battle of Blackrock Mountain. Many fought on this field. Many didn't make it. Lothar... Let me tell ye what happened all those years ago.",rewardGold=328500,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=248250,x=0.368,y=0.51,zoneID=46}},ends={{npcID=248250,x=0.368,y=0.51,zoneID=46}},coords={x=0.368,y=0.51,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="Unstoppable Force"},
