[92715] = {id=92715,name="By Invitation Only?",level=80,requiredLevel=80,faction="horde",expansion=0,zoneID=15969,mapID=86,description="Fancy yourself a Brawl'gar contender do you, ? They don't let just anyone in there, you know. Certainly not without an invitation. That said... just between you and me, if you know where to look and you've the means they say anyone can have their moment in the spotlight these days.",rewardGold=30900,rewardXP=1470,starts={{npcID=252857,x=0.46,y=0.608,zoneID=1637},{npcID=252857,x=0.514,y=0.4,zoneID=14771},{npcID=252857,x=0.43,y=0.838,zoneID=15969}},ends={{npcID=252933,x=0.734,y=0.316,zoneID=1637}},coords={x=0.46,y=0.608,source="quest_giver",zoneID=1637},questType="world",worldTaskTitle="By Invitation Only?"},
[92845] = {id=92845,name="By Invitation Only?",level=80,requiredLevel=80,faction="alliance",expansion=0,zoneID=2257,mapID=84,description="Fancy yourself a Brawlpub contender do you, ? They don't let just anyone in there, you know. Certainly not without an invitation. That said... just between you and me, if you know where to look and you've the means they say anyone can have their moment in the spotlight these days.",rewardGold=30900,rewardXP=1470,starts={{npcID=253181,x=0.666,y=0.718,zoneID=1519},{npcID=253181,x=0.51,y=0.434,zoneID=14771},{npcID=253181,x=0.43,y=0.77,zoneID=15969}},coords={x=0.666,y=0.718,source="quest_giver",zoneID=1519},questType="world",worldTaskTitle="By Invitation Only?"},
