[94210] = {id=94210,name="Feathering the Nest",level=0,requiredLevel=0,faction="both",expansion=0,zoneID=15524,mapID=2352,description="A house isn't quite a home without the perfect furnishings. It looked like there were some vendors in town. Perhaps it would be worth checking what they have in stock.",rewardGold=34100,starts={{npcID=233063,x=0.53,y=0.4,zoneID=16105},{npcID=233708,x=0.552,y=0.576,zoneID=15524}},ends={{npcID=233063,x=0.53,y=0.4,zoneID=16105},{npcID=233708,x=0.552,y=0.576,zoneID=15524}},coords={x=0.53,y=0.4,source="quest_giver",zoneID=16105},questType="world",worldTaskTitle="Feathering the Nest",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[94379] = {id=94379,name="This Old Hearth",level=0,requiredLevel=0,faction="both",expansion=0,zoneID=15524,mapID=2351,description="It looks like your house is ready for an upgrade. This doesn't normally happen so fast, but you've really made an impression around here. Head on over to our general contractor for next steps.",rewardGold=34100,rewardItems={266892},starts={{npcID=233063,x=0.53,y=0.4,zoneID=16105},{npcID=233708,x=0.552,y=0.576,zoneID=15524}},ends={{npcID=233063,x=0.53,y=0.4,zoneID=16105},{npcID=233708,x=0.552,y=0.576,zoneID=15524}},coords={x=0.53,y=0.4,source="quest_giver",zoneID=16105},questType="world",worldTaskTitle="This Old Hearth",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[94444] = {id=94444,name="Choose a Path",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1519,mapID=85,description="Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, . As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.",rewardGold=200,rewardXP=175,starts={{npcID=133407,x=0.394,y=0.792,zoneID=1637}},ends={{npcID=257671,x=0.4,y=0.792,zoneID=1637}},coords={x=0.394,y=0.792,source="quest_giver",zoneID=1637},questType="world",worldTaskTitle="Choose a Path"},
[94445] = {id=94445,name="Choose a Path",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1637,mapID=84,description="Welcome to Stormwind, . I invite you to explore our fair city. Say, you look like someone who appreciates the great outdoors! Elwynn is lovely this time of year. Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, !",rewardGold=31200,rewardXP=175,starts={{npcID=133362,x=0.532,y=0.152,zoneID=1519}},ends={{npcID=249187,x=0.538,y=0.126,zoneID=1519}},coords={x=0.532,y=0.152,source="quest_giver",zoneID=1519},questType="world",worldTaskTitle="Choose a Path"},
