[95413] = {id=95413,name="Community Engagement",level=90,requiredLevel=90,faction="both",expansion=0,zoneID=15969,mapID=2352,description="Ah hello, . I have a flier for you. Vaeli hands you a glossy piece of paper.> DON'T MISS OUT!!! Don't miss this amazing deal available only to you! Present this coupon on your next purchase from your neighborhood endeavor trader, and get bonus items for free! Coupon valid for one week. Terms and conditions apply.",rewardGold=341600,rewardXP=13690,rewardItems={269010,274069,274070,274071,280732,280734,280737},starts={{npcID=260957,x=0.494,y=0.658,zoneID=15969}},coords={x=0.494,y=0.658,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Community Engagement"},
[95416] = {id=95416,name="Going Postal",level=90,requiredLevel=90,faction="both",expansion=0,zoneID=15524,mapID=2352,description="With so many new residents, mail in the neighborhoods is really starting to pile up. So many routes and just one of me! If only I could deputize an assistant mail carrier... Say, , would you be willing to help out? I've got some juicy parcels from the dead letter office I could offer in thanks.",rewardGold=341600,rewardXP=13690,rewardItems={269010,274069,274070,274071,280732,280734,280737},rewardChoices={3316,259085,274069,274070,274071,280734,280737},rewardCurrencies={{id=3316,amount=500},{id=3363,amount=25}},starts={{npcID=260942,x=0.518,y=0.394,zoneID=16105},{npcID=260957,x=0.494,y=0.658,zoneID=15969}},ends={{npcID=260942,x=0.518,y=0.394,zoneID=16105},{npcID=260943,x=0.528,y=0.596,zoneID=15524}},coords={x=0.518,y=0.394,source="quest_giver",zoneID=16105},questType="world",worldTaskTitle="Going Postal"},
[95438] = {id=95438,name="Lost Animals",level=90,requiredLevel=90,faction="both",expansion=0,zoneID=16105,mapID=2352,description=", I am so glad to see you. A good friend of mine has sent a letter informing me she lost track of some of her tiny pets throughout the neighborhood! She's asking for assistance from anyone who can help! Help find her lost animals right away!",rewardGold=341600,rewardXP=13690,rewardItems={269010,274069,274070,274071,280732,280734,280737},rewardChoices={3316,259085,274069,274070,274071,280732,280734,280737},rewardCurrencies={{id=3316,amount=500},{id=3363,amount=25}},starts={{npcID=260957,x=0.494,y=0.658,zoneID=15969},{npcID=260958,x=0.528,y=0.596,zoneID=15524},{npcID=260958,x=0.518,y=0.394,zoneID=16105}},ends={{npcID=261034,x=0.558,y=0.57,zoneID=15524},{npcID=261034,x=0.546,y=0.424,zoneID=16105}},coords={x=0.494,y=0.658,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Lost Animals"},
[95440] = {id=95440,name="Housewarming",level=90,requiredLevel=90,faction="both",expansion=0,zoneID=15969,mapID=2352,description="Kirin Tor scholars have argued for centuries over the semantics of a \"gathering\". How many people are required? For how long must they remain? Who is bringing the beverages? Debates have raged into the night. Papers written. Research grants awarded. Consensus yet eludes the scholars, but they still meet often to deliberate. They take turns bringing beverages.",rewardGold=341600,rewardXP=13690,rewardItems={269010,274069,274070,274071,280732,280734,280737},starts={{npcID=260957,x=0.494,y=0.658,zoneID=15969}},coords={x=0.494,y=0.658,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Housewarming",db2QuestInfoID=1,db2QuestInfoName="Group"},
